INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1381, '<p>Représente dans un repère cartésien les droites suivantes :</p><ul><li>​\(d_1 \equiv (x,y,z) = (3,4,0) + \lambda(0,0,1)\)</li><li>​\(d_2 \equiv (x,y,z) = (-2,\lambda,2)\)</li><li>​\(d_3 \equiv x = z = 1\)</li><li>​\(d_4 \equiv \begin{cases} y=2 \\ z=-1 \end{cases}\)</li></ul>', true, '2017-08-18 14:15:55.05627+02', '2017-08-18 14:15:55.0563+02', false, 'submitted', 1210, 547);
