INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (243, '<p>Si (\(U_n\)) est une suite géométrique de premier terme \(u_1\) et de raison q, calcule \(u_2\), \(u_3\), \(u_4\), \(u_5\). Pour \(u_1=10000\) et \(q=0,15\).</p><p><br/></p><p>Exprime tes réponses sous forme de nombres entiers ou décimaux exactes.</p><div class="pull-right">Auteur: Paul Robaux</div>', true, '2016-12-12 14:10:45.888519+01', '2017-07-05 15:53:42.043874+02', true, 'Q32-U2-A3B_12', NULL, 642);
