INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1382, '<p></p><p style="font-size: 16px;">Dans un repère cartésien, représente les plans suivants  :</p><ul style="font-size: 16px;"><li>​\(\pi_1 \equiv (x,y,z) = (0,0,2) + \lambda(1,0,0) + \mu(0,1,0)\)</li><li>​\(\pi_2 \equiv (x,y,z) = (\lambda+1,-2,\mu-3)\)</li><li>​\(\pi_3 \equiv x = 3\)</li><li>​\(\pi_4 \equiv y = z\)</li></ul>', true, '2017-08-18 14:27:20.309027+02', '2017-08-18 14:28:32.958451+02', true, 'submitted', 1210, 548);
