INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (245, '<p>Si (\(U_n\)) est une suite arithmétique de premier terme \(u_1\) et de raison r, calculer \(u_1\), \(u_2\), \(u_3\), \(u_4\), \(u_5\). Exprimer \(U_n\) en fonction de n et calculer \(u_{100}\) pour \(u-1=3/5\) et \(r=-2/5\):</p><p>Donne tes réponses sous forme de nombres entiers ou de fractions simplifiées.</p><div class="pull-right">Auteur: Paul Robaux</div>', true, '2016-12-12 14:10:45.888519+01', '2017-07-05 17:16:59.505725+02', true, 'Q32-U2-A3_05', NULL, 640);
