INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (417, '<h5></h5><h5></h5><h5></h5><h5></h5><h5></h5><h5></h5><h5>​</h5><h5><span style="font-size: 24px;">Edith adore le cocktail de fruits « Bora Bora » que prépare sa tante. ​</span><br/>​Ce cocktail est composé de :​</h5><h5></h5><p><li>1/2 de jus d’ananas ;</li></p><p><li>1/3 de jus de fruits de la passion ;</li></p><p><li>1/10 de jus de citron ;</li></p><p><li>le reste est de la grenadine.<br/></li></p><h5></h5><h5>Calcule la part de grenadine contenue dans le cocktail. Écris tous tes calculs sur une feuille à part et exprime ta réponse sous forme de fraction irréductible.</h5><h5 style="text-align: right;"><small>Source: CE1D 2014, Livret 1, Q11</small></h5><h5>​</h5><h5></h5>', true, '2017-01-23 10:34:02.709289+01', '2017-05-23 14:36:45.86177+02', true, 'submitted', 97, 75);
