INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (233, '<p>On connaît un terme et la raison. Si (\(Un\)) est une suite géométrique, calculer \(u_1\) et \(u_{10}\) pour \(u_2=7\) et \(q=3\).</p><p>Soit \(S_n=u_1+u_2+u_3+....+u_n\). Donne la valeur de la somme \(S_{10}\), pour n=10, et de la somme \(S_{15}\), pour n=15.</p><p><br/></p><p>Exprime tes réponses sous formes de nombres entiers ou décimaux arrondis à deux décimales.</p><div class="pull-right">Auteur: Paul Robaux</div>', true, '2016-12-12 14:10:45.888519+01', '2017-07-05 10:26:09.963575+02', true, 'Q32-U2-A3B_10', NULL, 642);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (232, '<p>On connait deux termes d''une suite arithmétique, calculer \(u_1\) et \(u_{15}\) sachant que :\(u_8=19\) et \(u_{21}=-0,5\).</p><p>Exprime tes réponses sous forme de nombres entiers ou décimaux.</p><div class="pull-right">Auteur: Paul Robaux</div>', true, '2016-12-12 14:10:45.888519+01', '2017-07-05 16:30:38.190919+02', true, 'Q32-U2-A3A_05', NULL, 641);
