INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (229, '<p>Somme de termes consécutifs. Soit (\(U_n\)) une suite arithmétique. On désigne par \(S_n\) la somme \(u_1+u2 + ... +u_n\). Calcule \(S_8\), \(S_{12}\), \(S_{20}\) si \(u_1=-4\) et \(r=3\).</p><p><br/></p><p>Exprime tes réponses sous forme de nombres entiers.</p><div class="pull-right">Auteur: Paul Robaux</div>', true, '2016-12-12 14:10:45.888519+01', '2017-07-05 17:02:02.554581+02', true, 'Q32-U2-A3A_03', NULL, 641);
