INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (231, '<p>Somme de termes consécutifs. Soit (\(U_n\)) une suite arithmétique. On désigne par \(S_n\) la somme \(u_1+u_2+ ... +u_n\). Calcule la raison r et la somme \(S_{100}\) si \(u_{10}=10\) et \(u_{1000}=100000\):</p><div class="pull-right">Auteur: Paul Robaux</div>', true, '2016-12-12 14:10:45.888519+01', '2017-07-05 16:53:03.233345+02', true, 'Q32-U2-A3A_04', NULL, 641);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (225, '<p>On connait deux termes d''une suite arithmétique. Calcule \(u_1\) et \(u_{15}\) sachant que : \(u_5=138/7\) et \(u_8=21\).</p><p>Exprime tes réponses sous forme de nombres entiers.</p><div class="pull-right">Auteur: Paul Robaux</div>', true, '2016-12-12 14:10:45.888519+01', '2017-07-05 16:56:06.636459+02', true, 'Q32-U2-A3A_07', NULL, 641);
