INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (251, '<p style="font-size: 16px;"><b>Soit une suite géométrique (\(U_n\)) de raison \(q=3\) et dont on connait le premier terme \(u_1=-7\).</b></p><p style="font-size: 16px;"><b>a.) Calcule \(u_2\).</b></p><p style="font-size: 16px;"><b>b.) Calcule \(u_{3}\).</b></p><p style="font-size: 16px;"><b>c.) Calcule \(u_{4}\).</b></p><p style="font-size: 16px;"><b>d.) Calcule \(u_{5}\).</b></p><p style="font-size: 16px;"><b>e.) Calcule \(u_{10}\).</b></p><p style="font-size: 16px;"><br/></p><div class="pull-right">Auteur: Paul Robaux</div>', true, '2016-12-12 14:10:45.888519+01', '2017-07-05 11:15:13.307524+02', true, 'Q32-U2-A3B_01', NULL, 642);
