INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (246, '<p>Si (\(U_n\)) est une suite arithmétique de premier terme \(u_1\) et de raison r, calcule \(u_2\), \(u_3\), \(u_4\), \(u_5\). Exprimer \(U_n\) en fonction de n et calcule \(u_{100}\) pour \(u_1=3,8\) et \(r=-0,7\):</p><p>Exprime tes réponses sous forme de nombres entiers ou décimaux.</p><div class="pull-right">Auteur: Paul Robaux</div>', true, '2016-12-12 14:10:45.888519+01', '2017-07-05 17:24:56.223529+02', true, 'Q32-U2-A3_04', NULL, 640);
