INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (255, '<p><b><span style="font-size: 12.0pt;color: #555555;">Soit une suite géométrique (<span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-msubsup"><span class="mjx-base"><span id="MJXc-Node-14" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">U</span></span></span><span class="mjx-sub" style="font-size: 70.7%;vertical-align: -0.212em;"><span id="MJXc-Node-15" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">n</span></span></span></span></span></span><span class="MJX_Assistive_MathML">Un</span></span></span></b>) dont on connait deux termes \(u_2=392\) et \(u_5=49\)<span style="font-size: 12.0pt;color: #555555;"></span></p><p><b><span style="font-size: 12.0pt;color: #555555;">On désigne par \(S_n\) </span></b><b><span style="font-size: 12pt;">la somme \(u_1+u_2+u_3+....+u_n\).<br/></span></b></p><p><b><span style="font-size: 12.0pt;color: #555555;">a.) Calcule la raison q.</span></b><span style="font-size: 12.0pt;color: #555555;"></span></p><p><b><span style="font-size: 12.0pt;color: #555555;">b.) Calcule le premier terme \(u_1\).</span></b><span style="font-size: 12.0pt;color: #555555;"></span></p><p><b><span style="font-size: 12.0pt;color: #555555;">c.) Calcule le terme \(u_4\)</span></b><span style="font-size: 12.0pt;color: #555555;"></span></p><p><b><span style="font-size: 12.0pt;color: #555555;">d.) Calcule la somme \(S_{20}\)</span></b><span style="font-size: 12.0pt;color: #555555;"></span></p><p><span style="font-size: 12.0pt;color: #555555;"></span></p><p><span style="font-size: 12.0pt;color: #555555;">Donne tes réponses sous forme de nombres <b><u><i>arrondis à l''entier</i></u></b><b> le plus proche.</b> </span></p><p><br/></p><div class="pull-right">Auteur: Paul Robaux</div>', true, '2016-12-12 14:10:45.888519+01', '2017-07-05 15:26:57.837655+02', true, 'Q32-U2-A3B_06', NULL, 642);
