INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (837, '<p>Nous souhaitons déterminer le nombre de manières de : </p><p>(1) <i>diffuser les 65 chansons différentes, enregistrées dans la mémoire d''un smartphone, en utilisant la fonction &#34;lecture aléatoire&#34;</i></p><p>(2) <i>accrocher chacun des 31 manteaux différents à un des 50 crochets numérotés de 1 à 50 d''un porte-manteaux</i></p><p>(3) <i>former un numéro de téléphone pour l''agglomération de Bruxelles au format national (9 chiffres dont le premier est 0 et le deuxième l''indicateur 2 de la zone de Bruxelles)</i></p><p>(4) <i>choisir 4 passagers parmi 8 pour un covoiturage</i></p><p>(5)<i> écrire un anagramme du mot &#34;exponentiel&#34; (le mot &#34;exponentiel&#34; non compté)</i></p><p><b></b><br/></p><p><b>Précise </b>d''abord<b> </b>le type de groupement de chacune des situations.</p><p><b>Calcule </b>ensuite le nombre de choix possibles <i>(répondre en notation scientifique avec 3 chiffres significatifs. Exemples : \( 1,23 \cdot 10^8 \) ; \( 4,90 \cdot 10^{14} \) )</i></p><p><b></b></p>', true, '2017-07-04 17:13:01.541168+02', '2017-07-05 09:23:50.878925+02', true, 'submitted', 99, 498);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (248, '<p><b>Soit une suite géométrique (\(U_n\)) de raison \(q=1/3\) et dont on connait le terme \(u_3=2,25\).</b></p><p style="font-size: 16px;"><b>On désigne par <span id="MathJax-Element-5-Frame" class="mjx-chtml MathJax_CHTML" style="text-align: left;font-size: 19.36px;float: none;direction: ltr;"><span id="MJXc-Node-24" class="mjx-math"><span id="MJXc-Node-25" class="mjx-mrow" style="text-align: left;"><span id="MJXc-Node-26" class="mjx-msubsup" style="text-align: left;"><span class="mjx-base" style="text-align: left;"><span id="MJXc-Node-27" class="mjx-mi" style="text-align: left;"><span class="mjx-char MJXc-TeX-math-I" style="text-align: left;">S</span></span></span><span class="mjx-sub" style="text-align: left;font-size: 13.6875px;vertical-align: -0.212em;"><span id="MJXc-Node-28" class="mjx-mi" style="text-align: left;"><span class="mjx-char MJXc-TeX-math-I" style="text-align: left;">n</span></span></span></span></span></span><span class="MJX_Assistive_MathML" style="height: 1px !important;width: 1px !important;">Sn</span></span> la somme \(u_1+u_2+u_3+.....+u_n\) <span id="MathJax-Element-6-Frame" class="mjx-chtml MJXc-processed" style="text-align: left;font-size: 121%;float: none;direction: ltr;"><span id="MJXc-Node-29" class="mjx-math"><span id="MJXc-Node-30" class="mjx-mrow" style="text-align: left;"><span id="MJXc-Node-31" class="mjx-msubsup" style="text-align: left;"><span class="mjx-base" style="text-align: left;"><span id="MJXc-Node-32" class="mjx-mi" style="text-align: left;"><span class="mjx-char MJXc-TeX-math-I" style="text-align: left;">u</span></span></span><span class="mjx-sub" style="text-align: left;font-size: 13.6875px;vertical-align: -0.212em;"><span id="MJXc-Node-33" class="mjx-mn" style="text-align: left;"><span class="mjx-char MJXc-TeX-main-R" style="text-align: left;">1</span></span></span></span><span id="MJXc-Node-34" class="mjx-mo MJXc-space2" style="text-align: left;"><span class="mjx-char MJXc-TeX-main-R" style="text-align: left;">+</span></span><span id="MJXc-Node-35" class="mjx-msubsup MJXc-space2" style="text-align: left;"><span class="mjx-base" style="text-align: left;"><span id="MJXc-Node-36" class="mjx-mi" style="text-align: left;"><span class="mjx-char MJXc-TeX-math-I" style="text-align: left;">u</span></span></span><span class="mjx-sub" style="text-align: left;font-size: 13.6875px;vertical-align: -0.212em;"><span id="MJXc-Node-37" class="mjx-mn" style="text-align: left;"><span class="mjx-char MJXc-TeX-main-R" style="text-align: left;">2</span></span></span></span><span id="MJXc-Node-38" class="mjx-mo MJXc-space2" style="text-align: left;"><span class="mjx-char MJXc-TeX-main-R" style="text-align: left;">+</span></span><span id="MJXc-Node-39" class="mjx-msubsup MJXc-space2" style="text-align: left;"><span class="mjx-base" style="text-align: left;"><span id="MJXc-Node-40" class="mjx-mi" style="text-align: left;"><span class="mjx-char MJXc-TeX-math-I" style="text-align: left;">u</span></span></span><span class="mjx-sub" style="text-align: left;font-size: 13.6875px;vertical-align: -0.212em;"><span id="MJXc-Node-41" class="mjx-mn" style="text-align: left;"><span class="mjx-char MJXc-TeX-main-R" style="text-align: left;">3</span></span></span></span><span id="MJXc-Node-42" class="mjx-mo" style="text-align: left;"><span class="mjx-char MJXc-TeX-main-R" style="text-align: left;">+</span></span><span id="MJXc-Node-43" class="mjx-mo" style="text-align: left;"><span class="mjx-char MJXc-TeX-main-R" style="text-align: left;">.</span></span><span id="MJXc-Node-44" class="mjx-mo MJXc-space1" style="text-align: left;"><span class="mjx-char MJXc-TeX-main-R" style="text-align: left;">.</span></span><span id="MJXc-Node-45" class="mjx-mo MJXc-space1" style="text-align: left;"><span class="mjx-char MJXc-TeX-main-R" style="text-align: left;">.</span></span><span id="MJXc-Node-46" class="mjx-mo MJXc-space1" style="text-align: left;"><span class="mjx-char MJXc-TeX-main-R" style="text-align: left;">.</span></span><span id="MJXc-Node-47" class="mjx-mo MJXc-space1" style="text-align: left;"><span class="mjx-char MJXc-TeX-main-R" style="text-align: left;">.</span></span><span id="MJXc-Node-48" class="mjx-mo MJXc-space1" style="text-align: left;"><span class="mjx-char MJXc-TeX-main-R" style="text-align: left;">+</span></span><span id="MJXc-Node-49" class="mjx-msubsup" style="text-align: left;"><span class="mjx-base" style="text-align: left;"><span id="MJXc-Node-50" class="mjx-mi" style="text-align: left;"><span class="mjx-char MJXc-TeX-math-I" style="text-align: left;">u</span></span></span><span class="mjx-sub" style="text-align: left;font-size: 13.6875px;vertical-align: -0.212em;"><span id="MJXc-Node-51" class="mjx-mi" style="text-align: left;"><span class="mjx-char MJXc-TeX-math-I" style="text-align: left;">n</span></span></span></span></span></span><span class="MJX_Assistive_MathML" style="height: 1px !important;width: 1px !important;">u1+u2+u3+.....+un</span><span id="MJXc-Node-80" class="mjx-math"><span id="MJXc-Node-81" class="mjx-mrow"><span id="MJXc-Node-82" class="mjx-msubsup"><span class="mjx-base"><span id="MJXc-Node-83" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">U</span></span></span><span class="mjx-sub" style="font-size: 70.7%;vertical-align: -0.212em;"><span id="MJXc-Node-84" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">n</span></span></span></span></span></span><span class="MJX_Assistive_MathML">Un</span></span>.</b></p><p style="font-size: 16px;"><b>a.) Calcule \(u_1\).</b></p><p style="font-size: 16px;"><b>b.) Calcule \(u_{5}\).</b></p><p style="font-size: 16px;"><b>c.) Calcule \(S_{5}\).</b></p><p style="font-size: 16px;"><b>d.) Calcule \(u_{6}\) si \(u_1=100\) et \(q=0,5\).</b></p><p><br/></p><p>Donne tes réponses sous forme de nombres entiers ou décimaux exacts.</p><div class="pull-right">Auteur: Paul Robaux</div>', true, '2016-12-12 14:10:45.888519+01', '2017-07-05 11:09:20.270602+02', true, 'Q32-U2-A3B_08', NULL, 642);
