INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (234, '<p><b><span style="font-size: 12.0pt;color: #555555;">Soit une suite géométrique (\(U_n\)) de raison \(q=1,06\) et dont on connait le premier terme \(u_1=1500\).</span></b><span style="font-size: 12.0pt;color: #555555;"></span></p><p><b><span style="font-size: 12.0pt;color: #555555;">On désigne par \(S_n\)</span></b><span class="apple-converted-space"><b><span style="font-size: 12.0pt;color: #555555;"> </span></b></span><b><span style="font-size: 12.0pt;color: #555555;">la somme \(u_1+u_2+u_3+.....+u_n\) .</span></b><span style="font-size: 12.0pt;color: #555555;"></span></p><p><b><span style="font-size: 12.0pt;color: #555555;">a.) Calcule \(u_2\).</span></b><span style="font-size: 12.0pt;color: #555555;"></span></p><p><b><span style="font-size: 12.0pt;color: #555555;">b.) Calcule \(u_{3}\).</span></b><span style="font-size: 12.0pt;color: #555555;"></span></p><p><b><span style="font-size: 12.0pt;color: #555555;">c.) Calcule \(S_{4}\).</span></b><span style="font-size: 12.0pt;color: #555555;"></span></p><p><b><span style="font-size: 12.0pt;color: #555555;">d.) Après avoir exprimé \(U_n\) en fonction de n sur une feuille de papier, calcule \(u_{10}\).</span></b><span style="font-size: 12.0pt;color: #555555;"></span></p><p><span style="font-size: 12.0pt;color: #555555;"></span></p><p><span style="font-size: 12.0pt;color: #555555;">Donne tes réponses sous forme de nombres entiers ou décimaux arrondis à deux décimales.</span></p><p><br/></p><div class="pull-right">Auteur: Paul Robaux</div>', true, '2016-12-12 14:10:45.888519+01', '2017-07-05 15:35:31.082099+02', true, 'Q32-U2-A3B_11', NULL, 642);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (848, '<p>Un joueur tire une carte d''un jeu de 32 cartes. Il dit : &#34;la carte est une figure&#34;.</p><p><b>Quelle est la probabilité que ce soit un roi ?</b></p><p><i>(réponse sous forme de fraction irréductible)</i><br/></p>', true, '2017-07-05 15:58:34.86412+02', '2017-07-05 15:58:34.864152+02', true, 'submitted', 99, 500);
