INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (498, 'Dans une académie, les élèves candidats au baccalauréat série ES se répartissent en 2003 selon les trois enseignements de spécialité : mathématiques, sciences économiques et sociales et langue vivante. \n
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (500, 'Mr Choco est directeur d''un supermarché. Il achète à une usine, des boîtes de chocolats au prix de 5 € la boîte. Il revend ses boîtes dans son magasin à 13,60 € la boîte. Habituellement, il en vend 3 000 par semaine. Mr Choco réalise une étude de marché qui montre que toute baisse du prix de 10 centimes fait augmenter la vente de 100 boîtes par semaine.  A quel prix Mr Choco doit-il vendre ses boîtes de chocolats afin de maximiser son bénéfice ?', true, '2017-03-13 12:48:06.349832+01', '2017-03-13 12:48:06.349862+01', true, 'submitted', 97, 353);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (503, 'Mr Choco est directeur d''un supermarché. Il achète à une usine, des boîtes de chocolats au prix de 5 € la boîte. Il revend ses boîtes dans son magasin à 13,60 € la boîte. Habituellement, il en vend 3 000 par semaine. Mr Choco réalise une étude de marché qui montre que toute baisse du prix de 10 centimes fait augmenter la vente de 100 boîtes par semaine.', true, '2017-03-13 12:57:45.269041+01', '2017-03-13 12:57:45.269068+01', true, 'submitted', 97, 352);
