INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (839, '<p>On extrait une main de 13 cartes d''un jeu de 52 cartes.<br/></p>', true, '2017-07-05 10:09:11.960204+02', '2017-07-05 10:09:11.960237+02', true, 'submitted', 99, 498);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (844, '<p>Le clavier d''une machine comporte 42 touches dont 9 chiffres et 26 lettres.</p><p>Sachant que les touches soient équiprobables, <b>calcule</b> la probabilité :</p><p><i>(réponse au millième près ou en notation scientifique avec 4 chiffres significatifs)</i><br/></p>', true, '2017-07-05 11:28:01.713535+02', '2017-07-05 11:28:01.713577+02', true, 'submitted', 99, 500);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (849, '<p>Jacin joue avec sa Nintendo DS.</p><p>Une partie consiste en un duel entre Jacin et 3 monstres \( M_1 , M_2 \) et \(M_3 \) choisis par le jeu.</p><p>Le jeu est programmé de telle sorte que le monstre \( M_1 \) ait une probabilité \( \frac{1}{2} \) d''apparaître et les deux autres monstres aient la même probabilité d''apparition.</p><p>Le niveau de Jacin est tel que la probabilité qu''il gagne contre :</p><p>- \( M_1 \) est de 0,3</p><p>- \( M_2 \) est de 0,4</p><p>- \( M_3 \) est de 0</p><p><b>Quelle est la probabilité que Jacin gagne la partie ?</b><br/></p>', true, '2017-07-05 16:04:32.61577+02', '2017-07-05 16:04:32.615802+02', true, 'submitted', 99, 500);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (219, '<p>Si (\(U_n\)) est une suite suite arithmétique, calculer \(u_1\) et \(u_{16}\). Pour \(u_{10}=58\) et une raison r = 4:</p><p>Exprime tes réponses sous forme de nombres entiers.</p><div class="pull-right">Auteur: Paul Robaux</div>', true, '2016-12-12 14:10:45.888519+01', '2017-07-05 16:42:59.776752+02', true, 'Q32-U2-A3A_08', NULL, 641);
