INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (227, '<p>On connait deux termes. Si (\(U_n)\) est une suite géométrique, calcule \(u_1\) et q pour \(u_6=7012758,654\) et \(u_2=5350000\).</p><p>Calcule ensuite \(u_{10}\) et \(S_{10}\).</p><p>Exprime tes réponses sous forme de nombres entiers ou décimaux exacts.</p><div class="pull-right">Auteur: Paul Robaux</div>', true, '2016-12-12 14:10:45.888519+01', '2017-07-05 10:10:16.271351+02', true, 'Q32-U2-A3B_07', NULL, 642);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (239, '<p><b><span style="font-size: 12.0pt;color: #555555;">Soit une suite géométrique (\(U_n\)) de raison \(q=0,5\) et dont on connait le premier terme \(u_1=128\).</span></b><span style="font-size: 12.0pt;color: #555555;"></span></p><p><b><span style="font-size: 12pt;">On désigne par \(S_n\)</span></b><span class="apple-converted-space"><b><span style="font-size: 12.0pt;color: #555555;"> </span></b></span><b><span style="font-size: 12.0pt;color: #555555;">la somme \(u_1+u_2+u_3+.....+u_n\) .</span></b><span style="font-size: 12.0pt;color: #555555;"></span></p><p><b><span style="font-size: 12.0pt;color: #555555;">a.) Calcule \(u_2\).</span></b><span style="font-size: 12.0pt;color: #555555;"></span></p><p><b><span style="font-size: 12.0pt;color: #555555;">b.) Calcule \(u_{3}\).</span></b><span style="font-size: 12.0pt;color: #555555;"></span></p><p><b><span style="font-size: 12.0pt;color: #555555;">c.) Calcule \(S_{5}\).</span></b><span style="font-size: 12.0pt;color: #555555;"></span></p><p><b><span style="font-size: 12.0pt;color: #555555;">d.) Après avoir exprimé \(U_n\) en fonction de n sur une feuille de papier, calcule \(u_{10}\).</span></b></p><p><br/></p><p>Exprime tes réponses sous forme de nombres entiers ou décimaux (pas de fractions).</p><div class="pull-right">Auteur: Paul Robaux</div>', true, '2016-12-12 14:10:45.888519+01', '2017-07-05 15:42:48.989056+02', true, 'Q32-U2-A3B_13', NULL, 642);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (252, '<p><b><span style="font-size: 12.0pt;color: #555555;">Soit une suite géométrique (<span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-msubsup"><span class="mjx-base"><span id="MJXc-Node-14" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">U</span></span></span><span class="mjx-sub" style="font-size: 70.7%;vertical-align: -0.212em;"><span id="MJXc-Node-15" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">n</span></span></span></span></span></span><span class="MJX_Assistive_MathML">Un</span></span></span></b>) dont on connait deux termes \(u_6=567\) et \(u_7=15309\).<span style="font-size: 12.0pt;color: #555555;"></span></p><p><b></b></p><p><b>Soit la somme \(S_n\) définie comme \(u_1+u_2+u_3+....+u_n\).</b></p><p><b>a.) Calcule la raison q.</b></p><p><b>b.) Calcule le premier terme \(u_1\).</b></p><p><b>c.) Calcule le terme \(u_{9}\).</b></p><p><b>d.) Calcule la somme \(S_{9}\).</b></p><p></p><p><span style="font-size: 12.0pt;color: #555555;"></span></p><p><span style="font-size: 12.0pt;color: #555555;">Donne tes réponses sous forme de nombres entiers ou décimaux arrondis à deux décimales.</span></p><div class="pull-right">Auteur: Paul Robaux</div>', true, '2016-12-12 14:10:45.888519+01', '2017-07-05 15:09:31.407894+02', true, 'Q32-U2-A3B_03', NULL, 642);
