INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (850, '<p>Un lot de pièces présente 5% de pièces défectueuses.</p><p>La procédure de contrôle en sortie de fabrication n''est pas infaillible : 96% des pièces bonnes sont acceptées et 98% des pièces mauvaises sont rejetées.</p><p>On choisit une pièce en sortie de fabrication au hasard.</p><p><b>Quelle est la probabilité pour que...</b><br/></p>', true, '2017-07-05 16:13:12.737088+02', '2017-07-24 12:07:56.509366+02', true, 'submitted', 99, 501);
