INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (851, '<p>On estime généralement qu''une souris a 8 chances sur 10 de passer l''hiver lorsqu''elle est en bonne santé, et 3 chances sur 10 lorsqu''elle est malade.</p><p>Si 20% d''une population de souris n''est pas en bonne santé, <b>quel pourcentage de cette population doit-on s''attendre à retrouver en vie à la fin de l''hiver ?</b><br/></p>', true, '2017-07-05 16:24:29.670902+02', '2017-07-05 16:24:29.670947+02', true, 'submitted', 99, 501);
