INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (765, '<p>Quelle est la hauteur d''un cylindre de 5 kg et de 32 cm de pourtour, si sa masse volumique est de 1400 kg/m³ ?</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-06-09 20:22:38.884501+02', '2017-06-09 20:22:38.884586+02', true, 'submitted', 593, 590);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (655, '<p><b><span style="font-size: 12.0pt;color: #555555;">Soit une suite géométrique (\(U_n\)) dont on connait deux termes, \(u_2=392\) et \(u_5=49\).</span></b><span style="font-size: 12.0pt;color: #555555;"></span></p><p><b><span style="font-size: 12.0pt;color: #555555;">On désigne par \(S_n\) </span></b><b><span style="font-size: 12.0pt;color: #555555;">la somme \(u_1+u_2+u_3+.....+u_n\) .</span></b><span style="font-size: 12.0pt;color: #555555;"></span></p><p><b><span style="font-size: 12.0pt;color: #555555;">a.) Calcule la raison q.</span></b><span style="font-size: 12.0pt;color: #555555;"></span></p><p><b><span style="font-size: 12.0pt;color: #555555;">b.) Calcule le premier terme \(u_{1}\).</span></b><span style="font-size: 12.0pt;color: #555555;"></span></p><p><b><span style="font-size: 12.0pt;color: #555555;">c.) Calcule \(S_{5}\).</span></b><span style="font-size: 12.0pt;color: #555555;"></span></p><p><b><span style="font-size: 12.0pt;color: #555555;">d.) Calcule \(u_{10}\) si \(u_1=4000\) et \(q=0,5\).</span></b><span style="font-size: 12.0pt;color: #555555;"></span></p><p><span style="font-size: 12.0pt;color: #555555;"></span></p><p><span style="font-size: 12.0pt;color: #555555;">Donne tes réponses sous forme de nombres entiers ou décimaux exacts.</span></p><div class="pull-right">Auteur: Paul Robaux</div>', true, '2017-05-01 20:49:20.28148+02', '2017-07-05 15:51:52.745039+02', true, 'adapted', 94, 642);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (728, '<p>Le quotient de deux nombres est 7.</p><p>Détermine ces deux nombres sachant que si on retire 70 au plus grand, on obtient le double du plus petit.</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 16:20:19.582581+02', '2017-05-31 16:20:19.582612+02', true, 'submitted', 593, 297);
