INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (831, '<p>Ecris les expressions suivantes sous la forme d''un carré parfait. ATTENTION : écris ta réponse sous la forme (a+b)². Exemple : (x+2)²</p><p>Résous les équations qui en découlent.</p><p><br/></p><p>\(x²+8x+16\)</p><p>\(x²+\frac{x}{2}+\frac{1}{16}\)</p><p>\(x²-3x+2,25\)</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-07-04 15:02:35.282673+02', '2017-07-04 15:07:56.474374+02', true, 'submitted', 593, 342);
