INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (739, '<p>Il y a 10 ans, une femme avait le septuple de l''âge de sa fille.</p><p>Quels sont leurs âges actuels sachant que la mère a eu sa fille à l''âge de 42 ans?</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 18:09:43.096495+02', '2017-05-31 18:09:43.096527+02', true, 'submitted', 593, 297);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (745, '<p>On a partagé 4450€ entre 20 personnes.</p><p>Chaque adulte a reçu 250€ et chaque enfant 200€.</p><p>Combien d''enfants et d''adultes y avait-il?</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 21:23:59.572388+02', '2017-05-31 21:23:59.572416+02', true, 'submitted', 593, 297);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (756, '<p>Quel est le volume d''une pyramide en fer de 36 cm d''apothème dont la base est un hexagone de 8 cm de côté et de 6,9 cm d''apothème?</p><p><span style="font-size: 17.5px;"></span></p><div style="text-align: right;">​L.Vds.</div><p></p>', true, '2017-06-09 19:31:36.138057+02', '2017-06-09 19:31:36.138098+02', true, 'submitted', 593, 590);
