INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (244, '<p><b>Soit une suite géométrique de raison \(q=3\) et de premier terme \(u_1=-2\).</b></p><p><b>On désigne par \(S_n\) la somme \(u_1+u_2+u_3+.....+u_n\).</b></p><p><b>a.) Calcule \(u_{11}\).</b></p><p><b>b.) Calcule \(S_{11}\).</b></p><p><b>c.) Si maintenant la raison est \(q=5\) et le premier terme est toujours le même (<b style="font-size: 16px;">\(u_1=-2\)</b><b style="font-size: 16px;">), calcule <b style="font-size: 16px;">\(u_{7}\) et <b style="font-size: 16px;">\(S_{7}\).</b></b></b></b></p><p><br/></p><div class="pull-right">Auteur: Paul Robaux</div>', true, '2016-12-12 14:10:45.888519+01', '2017-07-05 10:40:24.56797+02', true, 'Q32-U2-A3B_05', NULL, 642);
