INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (741, '<p>Pour se déguiser en fée au carnaval, une petite fille souhaite un chapeau conique de 60cm de hauteur.</p><p>Quelle superficie de carton faut-il prévoir si le pourtour de sa tête est de 6,28dm?</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 21:10:56.082013+02', '2017-05-31 21:10:56.082044+02', true, 'submitted', 593, 598);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (746, '<p>Un disque en or coûte 25€ du cm².</p><p>Quelle est la circonférence d''un disque coûtant 706,86€?</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 21:30:00.10361+02', '2017-05-31 21:30:00.103643+02', true, 'submitted', 593, 596);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (730, '<p>Partage 4450€ en trois parts de manière que le deuxième ait 300€ de plus que le premier et le troisième 350€ de moins que le premier.</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 16:27:36.864984+02', '2017-05-31 16:27:36.865016+02', true, 'submitted', 593, 297);
