INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (658, '<p><b id="docs-internal-guid-87f71658-ce5d-9a0e-dd6f-e1f9194c8416"></b></p><p dir="ltr"><span style="font-size: 12pt;color: #555555;background-color: #ffffff;vertical-align: baseline;">Résous les équations suivantes. </span></p><p><br/></p><p dir="ltr"><span style="font-size: 12pt;color: #555555;background-color: #ffffff;vertical-align: baseline;">Les réponses doivent être écrites sous forme numérique, au millième près (exemple : 1,234).</span></p><p dir="ltr"><span style="font-size: 12pt;color: #555555;background-color: #ffffff;vertical-align: baseline;">Si il existe plusieurs réponses, les écrire séparées d''un &#34;et&#34; (exemple : 1 et 2).</span></p><p dir="ltr"></p><p>S''il n''existe aucune solution, écrire &#34;impossible&#34;.</p><p></p><p><br/></p><p><span style="font-size: 12pt;color: #555555;background-color: #ffffff;vertical-align: baseline;"></span><div style="text-align: right;">L.Vds.​</div></p>', true, '2017-05-03 15:00:37.171079+02', '2017-05-03 15:00:37.171121+02', true, 'submitted', 593, 523);
