INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (685, '<p>Le toit d''une remise de 8m de profondeur et de 12m de façade est situé à une hauteur de 5m.</p><p><br/></p><p>On désire peindre les murs extérieurs de cette remise.</p><p><br/></p><p style="text-align: right;">L.Vds.​</p><p><br/></p>', true, '2017-05-17 15:47:45.298331+02', '2017-05-17 15:51:25.23138+02', true, 'submitted', 593, 177);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (692, '<p>Un disque de 693 cm de rayon est placé à l''intérieur d''un hexagone régulier de 8 m de côté.</p><p style="text-align: right;"><br/></p><p style="text-align: right;">L.Vds.​</p><p><br/></p>', true, '2017-05-19 09:40:34.152351+02', '2017-05-19 09:40:34.152378+02', true, 'submitted', 593, 176);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (705, '<p>Quelle est la superficie d''un triangle isocèle de 5m de côté et de 8m de base?</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-30 12:52:23.492904+02', '2017-05-30 12:52:23.492932+02', true, 'submitted', 593, 176);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (729, '<p>Quelle est la superficie d''un losange dont le périmètre mesure 40m et l''une des diagonales 12m?</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 16:24:47.81651+02', '2017-05-31 16:24:47.816539+02', true, 'submitted', 593, 176);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (743, '<p>Un pentagone régulier de 8cm de côté est placé dans un cercle de 0,68dm de rayon.</p><p>Calcule la superficie du pentagone.</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 21:18:32.897326+02', '2017-05-31 21:18:32.897385+02', true, 'submitted', 593, 587);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (747, '<p>Une pyramide a une base carrée de 720cm de côté, et un apothème de 4,5m.</p><p>Combien de litres d''eau peut-elle contenir?</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 21:32:04.705602+02', '2017-05-31 21:32:04.705636+02', true, 'submitted', 593, 598);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (659, '<p><b id="docs-internal-guid-87f71658-ce66-6898-61a6-295a3bb1f446"></b></p><p dir="ltr"><span style="font-size: 12pt;color: #555555;background-color: #ffffff;vertical-align: baseline;">Résous les équations suivantes sans utiliser de logarithmes. </span></p><p><br/></p><p dir="ltr"><span style="font-size: 12pt;color: #555555;background-color: #ffffff;vertical-align: baseline;">Les réponses doivent être écrites sous forme numérique, au millième près (exemple : 1,234).</span></p><p dir="ltr"><span style="font-size: 12pt;color: #555555;background-color: #ffffff;vertical-align: baseline;">Si il existe plusieurs réponses, les écrire séparées d''un &#34;et&#34; (exemple : 1 et 2).</span></p><p dir="ltr"><span style="font-size: 12pt;color: #555555;background-color: #ffffff;vertical-align: baseline;">S''il n''existe aucune solution, écrire &#34;impossible&#34;.</span></p><p><br/></p><p><span style="font-size: 12pt;color: #555555;background-color: #ffffff;vertical-align: baseline;"></span><div style="text-align: right;">L.Vds.​</div></p>', true, '2017-05-03 15:15:48.722004+02', '2017-05-03 15:15:48.722046+02', true, 'submitted', 593, 523);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (656, '<p>Résous les équations suivantes sans utiliser de logarithmes. </p><p><br/></p><p>Les réponses doivent être écrites sous forme numérique, au millième près (exemple : 1,234).</p><p>Si il existe plusieurs réponses, les écrire séparées d''un &#34;et&#34; (exemple : 1 et 2).</p><p><span id="docs-internal-guid-87f71658-ce75-2d74-c865-9a4656789f8f"><span style="font-size: 12pt;vertical-align: baseline;">S''il n''existe aucune solution, écrire &#34;impossible&#34;.</span></span><br/></p><p><br/></p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-03 14:48:10.781972+02', '2017-05-03 15:18:45.156588+02', true, 'submitted', 593, 523);
