INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (664, '<p><img src="/media/exercices/T4-U4-A2_01.PNG"/>Les fonctions <span style="font-size: 16px;float: none;">\(f_1, f_2\) et \(f_3\) </span>sont de fonctions de 2nd degré, c''est à dire qu''elles s''expriment toutes sous la forme: \(f(x)=ax^2 +bx+c\). \(f_1, f_2\) et \(f_3\) sont représentées par leurs tracés sur la figure ci-dessus.</p>', true, '2017-05-08 19:47:22.478381+02', '2017-05-08 19:49:54.990683+02', true, 'adapted', 878, 331);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (665, '<p><img src="/media/exercices/T4-U4-A1_01.PNG"/>Les fonctions <span style="font-size: 16px;float: none;">\(f_1, f_2\) et \(f_3\) </span>sont tracées sur la figure. Les graphiques montrent \(f_1\) en vert, <span style="font-size: 16px;float: none;">\(f_2\) </span>en rouge est <span style="font-size: 16px;float: none;">\(f_3\) </span>en noir.</p>', true, '2017-05-08 19:50:04.584028+02', '2017-05-08 19:52:53.848128+02', true, 'adapted', 878, 330);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (660, '<p>Soient les fonctions f suivantes.</p><p><br/></p><p>Calcule f''(2), soit la valeur de la fonction dérivée de f en x=2.</p><p>Exprime ta réponse sous forme numérique au millième près (exemple : 1,234).</p><p><br/></p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-03 16:59:41.107697+02', '2017-05-10 11:00:07.159673+02', true, 'submitted', 593, 527);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (687, '<p>Une citerne cylindrique est placée à l''intérieur d''un cube de 3 m de côté.</p><p><br/></p><p>Sachant que toutes les faces du cube sont en contact avec la citerne, <br/></p><p><br/></p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-17 16:15:06.061661+02', '2017-05-17 16:15:06.061849+02', true, 'submitted', 593, 177);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (693, '<p>Une pièce de 17,875 m² est carrelée au moyen de 250 losanges dont l''une des diagonales mesure 22 cm.</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-19 09:46:18.912273+02', '2017-05-19 09:46:18.912302+02', true, 'submitted', 593, 176);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (707, '<p>Une femme de 67 ans a eu son fils à l''âge de 32 ans.</p><p>Il y a combien d''années la mère était-elle cinq fois plus âgée que son fils?</p><p style="text-align: right;">L.Vds.​</p><p><br/></p>', true, '2017-05-30 18:55:35.283212+02', '2017-05-30 18:55:35.283251+02', true, 'submitted', 593, 297);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (733, '<p>Un père a 45ans et son fils 21ans.</p><p>Quand le père avait-il le quadruple de l''âge de son fils?</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 16:40:54.906641+02', '2017-05-31 16:40:54.906681+02', true, 'submitted', 593, 297);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (744, '<p>Quelle est la masse d''une sphère dont la densité est de 4,9 et l''aire 314 dm²?</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 21:21:31.162069+02', '2017-05-31 21:21:31.162101+02', true, 'submitted', 593, 598);
