INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (688, '<p>On remplit d''eau une pyramide à base carrée de 80 cm de côté, dont l''aire latérale est de 1,92 m².</p><p><br/></p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-17 16:40:53.471936+02', '2017-05-17 16:40:53.471965+02', true, 'submitted', 593, 222);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (668, '<p>Calculez la valeur des intégrales définies ci-dessous.</p><p><i>Indice: les réponses sont des nombres entiers.<br/></i></p><p style="text-align: right;">L.F.<i><br/></i></p>', true, '2017-05-10 11:49:19.163272+02', '2017-05-10 11:49:19.163301+02', true, 'submitted', 2, 518);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (669, '<p style="font-size: 16px;">Soit la fonction \(f=\frac{lnx}{x-2}\)</p><p style="font-size: 16px;"><span>Réponds aux questions suivantes :</span></p><p style="font-size: 16px;"><br/></p><p style="font-size: 16px;text-align: right;">L.Vds​</p>', true, '2017-05-10 12:00:14.917555+02', '2017-05-10 12:00:14.917583+02', true, 'submitted', 593, 527);
