INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (694, '<blockquote><p>Partage 120€ entre deux personnes sachant que si la première donne 18€ à la seconde, elle aura cinq fois autant que la deuxième.</p><p style="text-align: right;">L.Vds.​</p></blockquote>', true, '2017-05-19 09:52:55.687851+02', '2017-05-19 09:52:55.687876+02', true, 'submitted', 593, 297);
