INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (748, '<p>Si je gagnais 5€, j''aurais trois fois autant que si j''en perdais cinq.</p><p>Quelle somme d''argent ai-je?</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 21:35:17.299632+02', '2017-05-31 21:35:17.299663+02', true, 'submitted', 593, 288);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (731, '<p>Un disque a un rayon de 30cm.</p><p>De combien faut-il réduire le rayon pour que son périmètre diminue de 12%?<br/></p><p>De combien faut-il augmenter son rayon pour que sa surface augmente de 25%? <br/></p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 16:34:40.720127+02', '2017-05-31 16:34:40.720478+02', true, 'submitted', 593, 176);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (672, '<p><b id="docs-internal-guid-67285fd9-f280-7daf-47a1-4eb82971bc22"></b></p><p dir="ltr"><span style="font-size: 12pt;color: #555555;background-color: #ffffff;vertical-align: baseline;">Les éléments constitués d''un noyau instable sont dits </span><span style="font-size: 12pt;color: #555555;background-color: #ffffff;vertical-align: baseline;"><i>radioactifs.</i></span><span style="font-size: 12pt;color: #555555;background-color: #ffffff;vertical-align: baseline;"> Lorsque ces noyaux se désintègrent, ils émettent des particules qui peuvent tuer des cellules du corps humain; c''est l''effet recherché en </span><span style="font-size: 12pt;color: #555555;background-color: #ffffff;vertical-align: baseline;"><i>radiothérapie </i></span><span style="font-size: 12pt;color: #555555;background-color: #ffffff;vertical-align: baseline;">: on cherche alors à tuer des cellules cancéreuses pour traiter le cancer.</span></p><p dir="ltr"><span style="font-size: 12pt;color: #555555;background-color: #ffffff;vertical-align: baseline;">Lors du traitement du cancer de la thyroïde (glande localisée dans le cou), le patient absorbe de l''iode-131, qui se concentrera dans sa thyroïde. L''iode-131 détruira ainsi les cellules depuis l''intérieur.</span></p><p><br/></p><p dir="ltr"><span style="font-size: 12pt;color: #555555;background-color: #ffffff;vertical-align: baseline;">La désintégration des noyaux suit la loi suivante : <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">A</span></span><span id="MJXc-Node-14" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-15" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">t</span></span><span id="MJXc-Node-16" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span><span id="MJXc-Node-17" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-18" class="mjx-msubsup MJXc-space3"><span class="mjx-base"><span id="MJXc-Node-19" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">A</span></span></span><span class="mjx-sub" style="font-size: 70.7%;vertical-align: -0.212em;"><span id="MJXc-Node-20" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">0</span></span></span></span><span id="MJXc-Node-21" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">.</span></span><span id="MJXc-Node-22" class="mjx-msubsup MJXc-space1"><span class="mjx-base"><span id="MJXc-Node-23" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">e</span></span></span><span class="mjx-sup" style="font-size: 70.7%;vertical-align: 0.513em;"><span id="MJXc-Node-24" class="mjx-texatom"><span id="MJXc-Node-25" class="mjx-mrow"><span id="MJXc-Node-26" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">−</span></span><span id="MJXc-Node-27" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">λ</span></span><span id="MJXc-Node-28" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">t</span></span></span></span></span></span></span></span><span class="MJX_Assistive_MathML">A(t)=A0.e−λt</span></span></span> est le temps nécessaire pour que la moitié des noyaux se soit désintégrée.</p><p><br/></p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-10 15:34:56.275952+02', '2017-05-10 15:36:03.054073+02', true, 'submitted', 593, 531);
