INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (675, '<p>Soit l''équation :</p><p><br/></p><p>\(ln x=ln (3x+2)\)</p><p><br/></p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-10 16:04:15.221827+02', '2017-05-10 16:51:43.502687+02', true, 'submitted', 593, 524);
