INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (689, '<p>Un bassin cylindrique de 1m de rayon contient de l''eau.</p><p><br/></p><p>On immerge totalement un cube de 1,2 m de côté dans ce bassin.</p><p><br/></p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-17 16:43:53.031376+02', '2017-05-17 16:43:53.031412+02', true, 'submitted', 593, 177);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (118, '<h5></h5><h5>Sur un pot de yaout, on lit l''information suivante : &#34;Contient 10% de fruits&#34;.</h5><h5>Si nous mélangeons 8 pots identiques de ce yaourt dans un plat, quel pourcentage de fruits aurons-nous dans ce plat ?</h5>', true, '2016-12-12 14:10:45.888519+01', '2017-05-23 14:43:08.260779+02', true, 'S32d_1', NULL, 76);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (725, '<p>Un véhicule part de Lima au Pérou vers Santiago du Chili avec une vitesse moyenne de 50km/h.</p><p>Les deux villes sont distantes d''environ 3000km.</p><p>Après combien de temps et à quelle distance de Lima ce véhicule va-t-il dépasser un camion parti 105 minutes plus tôt de Lima dans la même direction, avec une vitesse moyenne de 30km/h?</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 15:58:32.547099+02', '2017-05-31 15:58:32.547134+02', true, 'submitted', 593, 297);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (736, '<p>Partage 40 en deux parts de telle manière que la somme du double de l''une et du triple de l''autre soit égale à 95.</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 16:53:39.673195+02', '2017-05-31 16:53:39.67323+02', true, 'submitted', 593, 297);
