INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (214, '<p>On connaît un terme et la raison. Si (\(U_n\)) est une suite géométrique, calculer \(u_1\) et \(u_{10}\) pour \(u_5=512\) et \(q=2\).</p><p>Exprime tes réponses sous formes de nombres entiers.</p><div class="pull-right">Auteur: Paul Robaux</div>', true, '2016-12-12 14:10:45.888519+01', '2017-07-05 15:55:42.283199+02', true, 'Q32-U2-A3B_02', NULL, 642);
