INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (322, '<p><img src="/media/exercices/S32AII_02.PNG"/></p><h5>A l''aide de l''image ci-dessus, complète chaque phrase par une fraction. <span style="font-size: 16px;float: none;"><br/></span></h5><p><span style="font-size: 16px;float: none;">Clique sur la barre de fraction du clavier mathématique pour entrer ta réponse.</span></p><div><span style="float: none;"><b><br/></b></span><div style="font-size: 16px;text-align: right;"><b><span style="font-size: 13.6px;">Source: CEB 2013, Livret 10, Q8</span></b></div><!--StartFragment--><div style="text-align: right;"><font color="#000000"><br/></font></div><br/></div><div><span style="font-size: 16px;float: none;"><b><br/></b></span></div><div class="pull-right"><small><br/><br/></small></div>', true, '2017-01-05 16:30:01.119268+01', '2017-05-23 17:32:05.186208+02', true, 'submitted', 97, 73);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (311, '<h5><br/></h5><h5>Une école vient d''aménager un espace pour créer un potager. Les élèves souhaitent cultiver des tomates et s’informent.</h5><h5><br/></h5><h5>Consignes pour repiquer les plants de tomates :</h5><h5>• repiquer 7 plants sur une rangée de 3,50 m de long ;</h5><h5>• espacer chaque plant de 50 cm ;</h5><h5>• attacher chaque plant à un tuteur de 1,20 m de hauteur.</h5><h5><br/></h5><h5><b>Combien de plants de tomates faut-il acheter pour en planter 2 rangées ?</b></h5><h5><br/></h5><p><br/></p><div class="pull-right"><small>Source: CEB 2013, Livret 8, Q1</small></div><p><br/></p>', true, '2017-01-05 15:40:54.622526+01', '2017-05-23 18:07:16.809988+02', true, 'submitted', 97, 14);
