INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (737, '<p>A l''intérieur d''un champ rectangulaire de 20,8 ares et de 52m de côté, on place des arbres à 2m des bords du champs et à 4m les uns des autres.</p><p>Combien d''arbres faut-il planter?</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 18:01:32.077641+02', '2017-05-31 18:01:32.07767+02', true, 'submitted', 593, 596);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (699, '    <p><br/></p><table class="table table-bordered"><tbody><tr><td>34</td><td>34</td><td>34</td><td>31</td><td>32</td><td>30</td><td>31</td><td>31</td><td>33</td><td>34</td><td>31</td><td>33</td><td>30</td><td>31</td><td>30</td><td>34</td><td>32</td><td>32</td><td>34</td><td>30</td></tr><tr><td>31</td><td>31</td><td>31</td><td>31</td><td>32</td><td>32</td><td>31</td><td>32</td><td>34</td><td>32</td><td>31</td><td>31</td><td>31</td><td>33</td><td>34</td><td>33</td><td>31</td><td>31</td><td>32</td><td>31</td></tr></tbody></table><p><br/></p><p>À l’aide du tableau brut ci-dessus construit le tableau recensé ci-dessous en complétant les trous laissés.</p><p><br/></p><p><br/></p><table class="table table-bordered"><tbody><tr><td>Modalités</td><td>Effectifs</td><td>Fréquences</td><td>Effectifs cumulés</td><td>Fréquences cumulés</td></tr><tr><td>30</td><td>4</td><td>10%</td><td>4</td><td>h)</td></tr><tr><td>31</td><td>16</td><td>40%</td><td>f)</td><td>50%</td></tr><tr><td>32</td><td>8</td><td>c)</td><td>28</td><td>70%</td></tr><tr><td>33</td><td>a)</td><td>10%</td><td>32</td><td>i)</td></tr><tr><td>34</td><td>8</td><td>d)</td><td>g)</td><td>100%</td></tr><tr><td>totaux</td><td>b)</td><td>e)</td><td>40</td><td>100%</td></tr></tbody></table><p><br/></p><p><br/></p><p><br/></p>', true, '2017-05-24 12:11:00.691822+02', '2017-05-24 12:24:16.043348+02', true, 'adapted', 164, 606);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (841, '<p>On tire au hasard une carte d''un jeu de 52 cartes.</p><p>On considère les événements suivants :</p><p><i><b>A :</b> &#34;La carte est un as&#34;</i></p><p><i><b>B :</b> &#34;La carte est rouge&#34;</i></p><p><b>Calcule</b> les probabilités suivantes : </p><p><i>(réponse sous forme fractionnaire)</i><br/></p>', true, '2017-07-05 10:42:48.372561+02', '2017-07-05 10:42:48.372617+02', true, 'submitted', 99, 499);
