INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (708, '<p>La base d''un triangle correspond à 60% de la base d''un autre triangle qui lui est semblable.</p><p>Le plus grand de ces triangles a des côtés mesurant respectivement 26 et 32 cm.</p><p>Détermine la longueur des 2 côtés correspondants de l''autre triangle.</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-30 19:01:28.330054+02', '2017-05-30 19:01:28.330089+02', true, 'submitted', 593, 249);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (710, '<h5>Repère les équations du second degré.</h5><p style="text-align: right;">Contribution: C. Verians<br/></p>', true, '2017-05-31 11:47:07.526162+02', '2017-05-31 11:47:07.5262+02', true, 'submitted', 97, 337);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (706, '<p><img src="/media/exercices/S31FII_01.PNG"/></p><p><br/></p><p><br/></p><p>Yana et Zoé jouent aux billes. Lors de la deuxième partie, Yana perd 7 billes.Elle compte ses billes à la fin de la deuxième partie, elle en a 23. Elle estcontente car, avant de commencer à jouer, elle n’en avait que 19. </p><p><br/></p><p>Le dessin ci-dessus présente le problème sous la forme d’une bande dessinée. Il est incomplet.</p><p><br/></p><p>Relie les informations du dessus à l’endroit qui convient.</p><p><br/></p><p><br/></p><div class="pull-right"><small>Source: Evaluation externe non certificative, 5e primaire, 2014, Q6</small></div><p><br/></p>', true, '2017-05-30 15:13:12.666749+02', '2017-06-01 14:25:18.862133+02', false, 'adapted', 1063, 69);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (717, '<p><br/></p><!--StartFragment--><p><br/></p><h5>Résous algébriquement ces équations du second degré.</h5><p><b> ATTENTION</b>: Dans ta réponse, donne uniquement la ou les réponses, séparées de virgules, sans parenthèses. <i>ex</i>. \(\dfrac{3}{4} , 3 \) <br/></p><p>Si la solution est inexistante  ( \(\emptyset\) ), écris &#34;inexistant&#34;.<br/></p><p><span id="selectionBoundary_1496236788792_7916171896345293" class="rangySelectionBoundary">&#65279;</span></p><p><br/></p><p><br/></p><p style="text-align: right;"><i>Note : Le polynôme est incomplet. </i></p><div style="text-align: right;">Contribution : C. Verians<br/></div><p><br/></p><!--StartFragment-->', true, '2017-05-31 15:20:01.915106+02', '2017-05-31 15:20:01.915146+02', true, 'submitted', 97, 340);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (711, '<p><br/></p><!--StartFragment--><h5>Une équation du second degré s’écrit ax² + bx + c = 0 </h5><h5>Détermine les coefficients a, b et c dans les équations suivantes :<br/></h5><h5>a) 4x² + 1 - 3x = 0<!--EndFragment--><br/></h5><h5>b) - 2x² + x√3 + √2 = 0<!--EndFragment--><br/></h5><p><br/></p><p style="text-align: right;">Contribution : C. Verians</p><!--EndFragment--><p><br/></p><p><br/></p>', true, '2017-05-31 12:09:30.26441+02', '2017-05-31 12:09:30.264445+02', true, 'submitted', 97, 337);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (712, '<p><br/></p><!--StartFragment--><h5></h5><h5>​Une équation du second degré s’écrit ax² + bx + c = 0 </h5><h5>Détermine les coefficients a, b et c dans les équations suivantes :<br/></h5><h5>a) (√3+ 1)x - 34 x²= -1<!--EndFragment--><br/></h5><h5>b) 3x² = 2x<!--EndFragment--><br/></h5><p><br/></p><p style="text-align: right;">Contribution : C. Verians<br/> </p><p><br/></p>', true, '2017-05-31 14:42:33.730336+02', '2017-05-31 14:42:33.730368+02', true, 'submitted', 97, 337);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (713, '<p><br/></p><!--StartFragment--><h5></h5><h5>​Une équation du second degré s’écrit ax² + bx + c = 0. </h5><h5>Détermine les coefficients a, b et c dans les équations suivantes :<br/></h5><h5>a) 6x – 5x² = 2x + 1<!--EndFragment--><br/></h5><h5>b) (3x + 1) (√2x + 4) = 0<!--EndFragment--><br/></h5><p><br/></p><p style="text-align: right;">Contribution : C. Verians<br/> </p><div style="text-align: right;"><br/></div>', true, '2017-05-31 14:48:22.916012+02', '2017-05-31 14:48:22.916041+02', true, 'submitted', 97, 337);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (714, '<h5></h5><h5><!--StartFragment-->​Une équation du second degré s’écrit ax² + bx + c = 0 </h5><h5>Détermine les coefficients a, b et c dans les équations suivantes :<br/></h5><!--StartFragment--><h5>a) 3x² + 4x – 5 = 0 <br/></h5><h5>b) 4x² = 9 <br/></h5><p><br/></p><p style="text-align: right;">Contribution : C. Verians<br/> </p><h5></h5>', true, '2017-05-31 14:54:21.19063+02', '2017-05-31 14:54:21.190658+02', true, 'submitted', 97, 337);
