INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (720, '<p>Il y a 15ans, un père avait 6 fois l''âge de son enfant.</p><p>Quels sont leurs âges actuels sachant que le père a 20 ans de plus que son enfant?</p><p style="text-align: right;">L.Vds.​</p><p style="text-align: right;">​</p>', true, '2017-05-31 15:28:57.086532+02', '2017-05-31 15:28:57.086564+02', true, 'submitted', 593, 297);
