INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (723, '<p>Un triangle d''une hauteur de 3cm est formé d''une base de 60mm.</p><p>Détermine le périmètre de ce triangle sachant que l''un des côtés mesure 0,55dm.</p><p>Quelle serait l''aire de ce triangle si on réduisait sa hauteur de 50%?</p><p><br/></p><p>Enonce tes réponses au dixième près.</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 15:48:22.693638+02', '2017-05-31 15:48:22.693666+02', true, 'submitted', 593, 176);
