INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (732, '<p>Quelle est la masse d''un prisme droit de densité égale à 3,8 si sa base est un triangle équilatéral de 15cm de côté?</p><p>Ce prisme placé dans un cylindre de 8cm de hauteur en touche tous les bords.</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 16:38:03.639766+02', '2017-05-31 16:38:03.639798+02', true, 'submitted', 593, 226);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (734, '<p>Un triangle rectangle a une hauteur de 12m et une base de 15m.</p><p>Quelle serait la hauteur d''un autre triangle, semblable au premier, dont l''hypothènuse est augmenté de 14%?</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 16:46:17.731981+02', '2017-05-31 16:46:17.732011+02', true, 'submitted', 593, 263);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1072, '<img src="/media/exercices/TG5-U4-T3A_02.PNG" />
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (735, '<p>Un cône de 16,5 tonnes dont le pourtour de la base mesure 118,438dm est fabriqué dans un matériau inconnu.</p><p>Si la génératrice de ce cône est de 2,5m, détermine la densité du matériau utilisé.</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 16:51:38.830466+02', '2017-05-31 16:51:38.830496+02', true, 'submitted', 593, 226);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (738, '<p>Quelle quantité de peinture faut-il prévoir pour couvrir la surface totale d''un prisme droit à base hexagonale de 7cm de côté, de 60mm d''apothème et de 0,30m de hauteur.</p><p>Il faut compter 3 litres de peinture pour 9m² à peindre.</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 18:06:09.351309+02', '2017-05-31 18:06:09.351341+02', true, 'submitted', 593, 598);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (740, '<p>Quel est le périmètre d''un triangle de 18m de hauteur et de 270m² de superficie?</p><p>Que deviendrait l''aire de ce triangle si on augmentait sa hauteur de 12%?</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 19:35:45.063104+02', '2017-05-31 19:35:45.063138+02', true, 'submitted', 593, 596);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (742, '<p>Une voiture part de Douala vers Yaoundé, située à 300km de Douala, avec une vitesse moyenne de 60km/h.</p><p>Après combien de temps et où va-t-elle croiser un camion parti de Yaoundé vers Douala 30 minutes plus tard, avec une vitesse moyenne de 45km/h?</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 21:16:19.14572+02', '2017-05-31 21:16:19.14575+02', true, 'submitted', 593, 297);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (749, '<p>Quelle est la hauteur d''un trapèze dont la petite base mesure 4m et l''autre la surpasse de 2m, sachant que sa surface est de 10 m²?</p><p>Que deviendrait son aire si on réduisait sa hauteur de moitié?</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-05-31 21:39:50.775517+02', '2017-05-31 21:39:50.775552+02', true, 'submitted', 593, 587);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (842, '<p>On lance deux dés, un rouge et un vert.</p><p><br/></p><p>On considère les événements suivants :</p><p><i><b>A :</b> &#34;la somme des nombres fait 6&#34;</i></p><p><i><b>B :</b> &#34;on obtient un nombre pair sur le dé rouge&#34;</i></p><p><i><br/></i></p><p>Les événements A et B sont-ils indépendants ?</p><p><b>Explique</b> ta réponse<br/></p>', true, '2017-07-05 10:47:01.528886+02', '2017-07-05 10:47:01.528921+02', false, 'submitted', 99, 499);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (753, '<p>Quel est l''inverse des nombres suivants ?</p>', true, '2017-06-02 10:15:00.434452+02', '2017-06-02 10:15:00.434486+02', true, 'submitted', 122, 82);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (758, '<p>Détermine le périmètre total d''un demi-disque dont l''aire est de 34,7 m².</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-06-09 19:38:53.565487+02', '2017-06-09 19:38:53.565549+02', true, 'submitted', 593, 585);
