INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (752, '<p>Quelle est l''écriture décimale de 7/25 et de 8/125 ?</p>', true, '2017-06-02 09:33:48.048827+02', '2017-06-02 09:36:19.75654+02', true, 'adapted', 122, 36);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (757, '<p>Un voiture part d''Alger vers Tunis à 8h30 avec une vitesse moyenne de 75 km/h.</p><p>A quelle heure et où va-t-elle dépasser un camion parti 2 heures plus tôt d''Alger vers Tunis avec une vitesse moyenne de 50 km/h?</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-06-09 19:36:45.547245+02', '2017-06-09 19:36:45.547284+02', true, 'submitted', 593, 297);
