INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (759, '<p>Une sphère de 17 cm de rayon est placée dans un cube.</p><p>Sachant que toutes les faces du cube sont en contact avec la sphère, détermine le volume du cube (en litres).</p><p>Quel pourcentage du volume du cube, le volume de la sphère représente-t-il?</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-06-09 19:43:18.034393+02', '2017-06-09 19:43:18.034431+02', true, 'submitted', 593, 596);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (760, '<p>Une voiture part de Rome vers Naples, située à 200 km de Rome, à 7h30, avec une vitesse moyenne de 100 km/h.</p><p style="text-align: left;">A quelle heure et à quelle distance de Rome va-t-elle croiser un camion parti de Naples vers Rome 30 minutes plus tôt avec une vitesse moyenne de 80 km/h?<span style="font-size: 17.5px;">​</span></p><p style="text-align: left;"></p><p style="text-align: right;">L.Vds.​</p><p></p><p style="text-align: left;"></p><p style="text-align: right;">​</p><p></p>', true, '2017-06-09 19:47:56.522891+02', '2017-06-09 19:47:56.522967+02', true, 'submitted', 593, 297);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (763, '<p>Comment paiera-t-on la somme de 300€ avec des billets de 20€ et de 5€, de manière qu''il y ait 36 billets en tout?</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-06-09 20:07:10.66704+02', '2017-06-09 20:07:10.667082+02', true, 'submitted', 593, 297);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (764, '<p>Un triangle rectangle a une base de 16 cm et une hauteur de 120 mm.</p><p>Quelle serait la hauteur d''un autre triangle rectangle ayant les angles correspondants de même amplitude, et d''une base réduite de 25%?</p><p><br/></p><p>Détermine l''hypothèse de ces deux triangles.</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-06-09 20:16:30.796855+02', '2017-06-09 20:16:30.796895+02', true, 'submitted', 593, 263);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (766, '<p>Soient les fractions rationnelles suivantes.</p><p>Détermine les conditions d''existence.</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-06-09 21:17:14.78993+02', '2017-06-09 21:17:14.78997+02', true, 'submitted', 593, 294);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (767, '<p>Pour les fractions rationnelles suivantes, quelles sont les conditions d''existence <b>simplifiées</b>?</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-06-09 21:31:55.123428+02', '2017-06-09 21:31:55.123468+02', true, 'submitted', 593, 294);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (768, '<p>Quel est le domaine de définition de la fonction \(f(x)=\sqrt{\frac{1}{x}}\) ?</p><p><br/></p><p><span style="font-size: 17.5px;"></span></p><div style="text-align: right;">​L.Vds.</div><p></p>', true, '2017-06-09 21:46:09.174837+02', '2017-06-09 21:46:09.174879+02', true, 'submitted', 593, 462);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (769, '<p>Détermine le domaine de définition des fonctions suivantes : </p><p><br/></p><p>\(f_1(x)=\frac{x-3}{x-1}\)</p><p><span style="font-size: 16px;float: none;">\(f_2(x)=1+\sqrt{x-3}\)</span></p><p><span style="font-size: 16px;float: none;">\(f_3(x)=\frac{x²-5x+4}{x}\)</span><!--EndFragment--><br/><br/><br/></p><div style="text-align: right;">L.Vds.</div><p><br/></p><p></p>', true, '2017-06-09 21:58:15.748795+02', '2017-06-09 21:58:15.748832+02', false, 'submitted', 593, 462);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (770, '<p>Détermine le domaine de définition des fonctions suivantes : </p><p><br/></p><p>\(f_1(x)=\sqrt{\frac{1}{x}}\)</p><p><span style="font-size: 16px;float: none;">\(f_2(x)=1-\sqrt{x+2}\)</span></p><p><span style="font-size: 16px;float: none;">\(f_3(x)=\frac{1}{x³}\)</span></p><p><br/></p><p></p><div style="text-align: right;">L.Vds.</div><!--EndFragment--><p><br/></p><p><br/></p><p><br/></p><p><br/></p><p></p>', true, '2017-06-09 22:01:37.509667+02', '2017-06-09 22:01:37.509703+02', false, 'submitted', 593, 462);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (788, '<p><b>Quelle est la probabilité pour une famille de trois enfants :</b></p><p>\( \bullet \) d''avoir des enfants de même sexe ?</p><p>\( \bullet \) d''avoir au moins une fille ?</p><p><br/></p><p>Identifie pour cet énoncé:</p><p><i>a) l''expérience aléatoire</i></p><p><i>b) la catégorie d''épreuve</i></p><p><i>c) les événements de l''énoncé</i>​</p>', true, '2017-07-03 15:20:21.582929+02', '2017-07-03 15:20:21.58297+02', false, 'submitted', 99, 496);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (771, '<p style="font-size: 16px;">Détermine le domaine de définition des fonctions suivantes : </p><p style="font-size: 16px;"><br/></p><p style="font-size: 16px;">\(f_1(x)=x²-1\)</p><p style="font-size: 16px;"><span style="font-size: 16px;float: none;">\(f_2(x)=\sqrt{-1-x²}\)</span></p><p style="font-size: 16px;"><span style="font-size: 16px;float: none;">\(f_3(x)=\frac{1}{x²+3x}\)</span></p><p style="font-size: 16px;"><br/></p><div style="font-size: 16px;text-align: right;">L.Vds.</div><!--EndFragment--><p><br/></p><p><br/></p>', true, '2017-06-09 22:03:36.989541+02', '2017-06-09 22:03:36.989581+02', false, 'submitted', 593, 462);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (772, '<p>Calcule les limites suivantes. Exprime tes réponses sous forme décimale, au centième près.</p><p><span style="font-size: 17.5px;"></span></p><div style="text-align: right;">​L.Vds.</div><p></p>', true, '2017-06-09 22:32:29.084573+02', '2017-06-09 22:32:29.084617+02', true, 'submitted', 593, 463);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1227, '<p><img src="/media/exercices/P3D-U1-A3B_01.PNG"/></p><p><b>Complète</b> le tableau de nombres suivant correspondant à la fonction \( f(x) = 2x - 3 \)<br/></p>', true, '2017-07-28 11:06:21.624328+02', '2017-07-28 11:15:56.746074+02', true, 'submitted', 99, 206);
