INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (217, '<p>On connaît un terme et la raison. Si (\(U_{n}\)) est une suite géométrique, calcule \(u_{1}\) et \(u_{10}\) pour \(u_{4}\) = 0.001 et q = 0,2.</p><p>Soit la somme \(S_{n}=u_{1}+u_{2}+u_{3}+....+u_{n}\). Calcule cette somme pour n=4 et n=100.</p><p>Exprime tes réponses sous forme de nombres décimaux exacts.</p><div class="pull-right">Auteur: Paul Robaux</div>', true, '2016-12-12 14:10:45.888519+01', '2017-07-04 16:28:23.753714+02', true, 'Q32-U2-A3B_09', NULL, 642);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (856, '<img src="/media/exercices/T3-U3-A2_01.PNG" />
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (778, '<p><b id="docs-internal-guid-67285fd9-f280-7daf-47a1-4eb82971bc22"></b></p><p dir="ltr"><span style="font-size: 12pt;color: #555555;background-color: #ffffff;vertical-align: baseline;">Les éléments constitués d''un noyau instable sont dits </span><span style="font-size: 12pt;color: #555555;background-color: #ffffff;vertical-align: baseline;"><i>radioactifs.</i></span><span style="font-size: 12pt;color: #555555;background-color: #ffffff;vertical-align: baseline;"> Lorsque ces noyaux se désintègrent, ils émettent des particules qui peuvent tuer des cellules du corps humain; c''est l''effet recherché en </span><span style="font-size: 12pt;color: #555555;background-color: #ffffff;vertical-align: baseline;"><i>radiothérapie </i></span><span style="font-size: 12pt;color: #555555;background-color: #ffffff;vertical-align: baseline;">: on cherche alors à tuer des cellules cancéreuses pour traiter le cancer.</span></p><p dir="ltr"><span style="font-size: 12pt;color: #555555;background-color: #ffffff;vertical-align: baseline;">Lors du traitement du cancer de la thyroïde (glande localisée dans le cou), le patient absorbe de l''iode-131, qui se concentrera dans sa thyroïde. L''iode-131 détruira ainsi les cellules depuis l''intérieur.</span></p><p><br/></p><p dir="ltr"><span style="font-size: 12pt;color: #555555;background-color: #ffffff;vertical-align: baseline;">La désintégration des noyaux suit la loi suivante : <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">A</span></span><span id="MJXc-Node-14" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-15" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">t</span></span><span id="MJXc-Node-16" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span><span id="MJXc-Node-17" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-18" class="mjx-msubsup MJXc-space3"><span class="mjx-base"><span id="MJXc-Node-19" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">A</span></span></span><span class="mjx-sub" style="font-size: 70.7%;vertical-align: -0.212em;"><span id="MJXc-Node-20" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">0</span></span></span></span><span id="MJXc-Node-21" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">.</span></span><span id="MJXc-Node-22" class="mjx-msubsup MJXc-space1"><span class="mjx-base"><span id="MJXc-Node-23" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">e</span></span></span><span class="mjx-sup" style="font-size: 70.7%;vertical-align: 0.513em;"><span id="MJXc-Node-24" class="mjx-texatom"><span id="MJXc-Node-25" class="mjx-mrow"><span id="MJXc-Node-26" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">−</span></span><span id="MJXc-Node-27" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">λ</span></span><span id="MJXc-Node-28" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">t</span></span></span></span></span></span></span></span><span class="MJX_Assistive_MathML">A(t)=A0.e−λt</span></span></span> est le temps nécessaire pour que la moitié des noyaux se soit désintégrée.</p><p><br/></p><p style="text-align: right;">L.Vds.​</p>', true, '2017-06-10 11:31:03.39457+02', '2017-06-10 11:31:03.394607+02', true, 'adapted', 561, 531);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (779, '<p><br/><span id="DeltaPlaceHolderMain"><span class="ms-rteStyle-bv-tableauexemple">Au début d''une expérience, un chercheur possédait 50 g d''un élément <br/>radioactif. Cet élément se désintègre et sa masse diminue de moitié <br/>trois fois par heure. On souhaite représenter cette situation par une <br/>équation exponentielle.</span></span></p><p><span id="DeltaPlaceHolderMain"></span></p><p>On note :</p><p><br/><!--StartFragment--><span id="DeltaPlaceHolderMain"><span class="ms-rteStyle-bv-tableauexemple">x: le temps écoulé (en heures) depuis le début de l''expérience.<br/>y: la masse restante (en grammes) de l''élément radioactif.</span></span><!--EndFragment--><br/><br/><br/></p><!--EndFragment--><p><br/></p><p><br/></p><p><br/></p><p></p>', true, '2017-06-10 11:42:37.5226+02', '2017-06-10 11:42:37.522664+02', true, 'submitted', 561, 531);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (780, '<p><b>Vrai ou faux?</b></p><p><br/></p><p>Soit \((u)_n\) la suite définie par \(u_n=3n²\).</p><p>On a, pour tout entier naturel n : </p><p style="text-align: right;">L.Vds.​</p><p><br/></p>', true, '2017-06-14 15:46:08.623874+02', '2017-06-14 15:46:08.62392+02', true, 'submitted', 593, 450);
