INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (787, '<div><p>La probabilité pour que l''étudiante Aline réussisse son année est de \( \frac{3}{5} \) et celle de Benoit est de \( \frac{2}{3} \).</p><p><b>Quelle est la probabilité pour que :</b></p><p>\( \bullet \) les deux étudiants réussissent leur année ?</p><p><b></b>\( \bullet \) au moins un des deux étudiants réussisse son année ?</p><p>​</p><p>Identifie pour chaque cas :</p><p><i>a) l''expérience aléatoire</i></p><p><i>b) la catégorie d''épreuve</i></p><p><i>c) les événements de l''énoncé</i><br/></p></div>', true, '2017-07-03 15:15:12.133368+02', '2017-07-03 15:15:12.133431+02', false, 'submitted', 99, 496);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (786, '<p>Lorsque je lance une punaise sur un sol lisse, celle-ci peut retomber de deux manières : &#34;pointe en l''air&#34; ou &#34;appuyée sur sa pointe&#34;.</p><p><b>Quelles sont les chances qu''elle retombe &#34;pointe en l''air&#34; ?</b></p><p><b><br/></b></p><p>Identifie pour cet énoncé :</p><p><i>a) l''expérience aléatoire</i></p><p><i>b) la catégorie d''épreuve</i></p><p><i>c) l''événement de l''énoncé</i><br/></p>', true, '2017-07-03 15:06:18.119223+02', '2017-07-03 15:17:39.018232+02', true, 'submitted', 99, 496);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1114, '<p>Esquisse le graphique des fonctions de référence ci-dessous.</p><p>\(f(x) = 2\sqrt [3] {x} + 1 \)</p><p>\(g(x) = \dfrac{1}{4x} \)</p><p>\(h(x) = \dfrac{1}{2}x^3\)</p><p>\(p(x) = 3(x-1)^2-2 \)</p>', true, '2017-07-25 11:27:57.13904+02', '2017-07-25 11:27:57.139068+02', false, 'submitted', 1207, 326);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (789, '<p>Un dé non pipé est lancé deux fois de suite. On note la somme des points obtenus.</p><p><b>Quelle est la probabilité d''obtenir :</b></p><p><span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">∙</span></span></span></span><span class="MJX_Assistive_MathML">∙</span></span> une somme de points nulle</p><p><br/></p><p>Identifie pour cet énoncé :</p><p><i>a) l''expérience aléatoire</i></p><p><i>b) la catégorie d''épreuve</i></p><p><i>c) les événements de l''énoncé</i>​</p>', true, '2017-07-03 15:24:05.589455+02', '2017-07-24 10:47:41.759891+02', true, 'submitted', 99, 496);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1188, '<p>Soit l''équation suivante :</p><p>\(\frac{x²-10x+25}{-3x+m}=0\)</p><p>Quelle doit être la valeur de m pour que cette équation n''ait pas de solution?</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-07-27 13:48:21.153786+02', '2017-07-27 13:48:21.153817+02', true, 'submitted', 593, 356);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (215, '<p>On connait deux termes d''une suite arithmétique, calcule la raison r, le premier terme <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MJXc-processed" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-msubsup"><span class="mjx-base"><span id="MJXc-Node-14" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">u</span></span></span><span class="mjx-sub" style="font-size: 70.7%;vertical-align: -0.212em;"><span id="MJXc-Node-15" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">1</span></span></span></span></span></span><span class="MJX_Assistive_MathML">u1</span><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-msubsup"><span class="mjx-base"><span id="MJXc-Node-14" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">u</span></span></span><span class="mjx-sub" style="font-size: 70.7%;vertical-align: -0.212em;"><span id="MJXc-Node-15" class="mjx-texatom"><span id="MJXc-Node-16" class="mjx-mrow"><span id="MJXc-Node-17" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">15</span></span></span></span></span></span></span></span><span class="MJX_Assistive_MathML">u15</span></span> et le terme <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML"></span>\(u_{15}\) sachant que : \(u_{13}=-0,34\) et \(u_2=-0,01\).</p><p>Soit la somme \(S_n\) définie comme \(u_1+u_2+u_3+....+u_n\). Calcule la somme \(S_{15}\).</p><p>Exprime tes réponses sous forme de nombres décimaux exacts.</p><div class="pull-right">Auteur: Paul Robaux</div>', true, '2016-12-12 14:10:45.888519+01', '2017-07-05 16:38:49.623211+02', true, 'Q32-U2-A3A_06', NULL, 641);
