INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (663, '<h5>Soit la fonction transformée de la racine cubique : </h5><h5><span class="MathJax_Preview" style="color: inherit;"></span><br/><div style="text-align: center;"><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">f</span></span><span id="MJXc-Node-14" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-15" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-16" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span><span id="MJXc-Node-17" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-18" class="mjx-mn MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">3</span></span><span id="MJXc-Node-19" class="mjx-msqrt"><span class="mjx-box"><span class="mjx-surd"><span class="mjx-char MJXc-TeX-main-R">√</span></span><span class="mjx-box"><span id="MJXc-Node-20" class="mjx-mrow"><span id="MJXc-Node-21" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span></span></span></span></span><span id="MJXc-Node-22" class="mjx-mo MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">+</span></span><span id="MJXc-Node-23" class="mjx-mn MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">2</span></span></span></span><span class="MJX_Assistive_MathML">f(x)=3x+2</span></span></div><br/></h5><p>a) Donne les coordonnées des points d''intersection avec les axes du repère.<br/><br/>b) Trace le graphique sur une feuille quadrillée, en utilisant un repère orthonormé.<br/><br/></p>', true, '2017-05-08 19:45:25.263688+02', '2017-08-21 10:46:25.314139+02', false, 'adapted', 878, 332);
