INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (868, '<p style="font-size: 16px;">a.) Complète : La méthode des moindres carrés est utilisée pour définir ....</p><p style="font-size: 16px;">b.) En quoi consiste la méthode ? Coche ce qui convient :</p><p style="font-size: 16px;">Il s''agit de déterminer une droite d d''équation y=ax+b qui minimise :</p><p style="font-size: 16px;">​<span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-ams-R">□</span></span></span></span><span class="MJX_Assistive_MathML">◻</span></span><br/></p><p></p>', true, '2017-07-07 10:07:45.833856+02', '2017-07-26 08:34:00.410281+02', true, 'submitted', 1220, 433);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (866, '<p>a.) Complète : La méthode des moindres carrés est utilisée pour définir ....</p><p>b.) En quoi consiste la méthode ? Coche ce qui convient :</p><p>Il s''agit de déterminer une droite d d''équation y=ax+b qui minimise :</p><p><span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-ams-R">□</span></span></span></span><span class="MJX_Assistive_MathML">◻</span></span><br/><!--StartFragment--><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-ams-R">□</span></span></span></span></span><!--EndFragment--> la somme des carrés des distances entre chaque point <span id="MathJax-Element-12-Frame" class="mjx-chtml MJXc-processed" style="text-align: left;font-size: 121%;float: none;direction: ltr;"><span id="MJXc-Node-74" class="mjx-math"><span id="MJXc-Node-75" class="mjx-mrow" style="text-align: left;"><span id="MJXc-Node-76" class="mjx-mo" style="text-align: left;"><span class="mjx-char MJXc-TeX-main-R" style="text-align: left;">(</span></span><span id="MJXc-Node-77" class="mjx-msubsup" style="text-align: left;"><span class="mjx-base" style="text-align: left;"><span id="MJXc-Node-78" class="mjx-mi" style="text-align: left;"><span class="mjx-char MJXc-TeX-math-I" style="text-align: left;">x</span></span></span><span class="mjx-sub" style="text-align: left;font-size: 13.6875px;vertical-align: -0.212em;"><span id="MJXc-Node-79" class="mjx-mi" style="text-align: left;"><span class="mjx-char MJXc-TeX-math-I" style="text-align: left;">i</span></span></span></span><span id="MJXc-Node-80" class="mjx-mo" style="text-align: left;"><span class="mjx-char MJXc-TeX-main-R" style="text-align: left;">,</span></span><span id="MJXc-Node-81" class="mjx-msubsup MJXc-space1" style="text-align: left;"><span class="mjx-base" style="text-align: left;"><span id="MJXc-Node-82" class="mjx-mi" style="text-align: left;"><span class="mjx-char MJXc-TeX-math-I" style="text-align: left;">y</span></span></span><span class="mjx-sub" style="text-align: left;font-size: 13.6875px;vertical-align: -0.212em;"><span id="MJXc-Node-83" class="mjx-mi" style="text-align: left;"><span class="mjx-char MJXc-TeX-math-I" style="text-align: left;">i</span></span></span></span><span id="MJXc-Node-84" class="mjx-mo" style="text-align: left;"><span class="mjx-char MJXc-TeX-main-R" style="text-align: left;">)</span></span></span></span><span class="MJX_Assistive_MathML" style="height: 1px !important;width: 1px !important;">(xi,yi)</span><span id="MJXc-Node-106" class="mjx-math"><span id="MJXc-Node-107" class="mjx-mrow"><span id="MJXc-Node-108" class="mjx-mi"><span class="mjx-char MJXc-TeX-ams-R">□</span></span></span></span><span class="MJX_Assistive_MathML">◻</span><span id="MJXc-Node-46" class="mjx-math"><span id="MJXc-Node-47" class="mjx-mrow" style="width: 2.72em;"><span id="MJXc-Node-48" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">L</span></span><span id="MJXc-Node-49" class="mjx-mspace" style="width: 0px;height: 0px;"></span><span id="MJXc-Node-50" class="mjx-mpadded"><span class="mjx-block" style="width: 0px;"><span class="mjx-box" style="width: 0px;"><span id="MJXc-Node-51" class="mjx-mrow"><span id="MJXc-Node-52" class="mjx-texatom"><span id="MJXc-Node-53" class="mjx-mrow"><span id="MJXc-Node-54" class="mjx-mstyle" style="font-size: 80%;"><span id="MJXc-Node-55" class="mjx-mrow" style="font-size: 88.4%;"><span id="MJXc-Node-56" class="mjx-texatom"><span id="MJXc-Node-57" class="mjx-mrow"><sp