INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (919, '<p>Soit f(x)=2x-3, une fonction du premier degré appartenant au plan Oxy.</p><p>Calcule algébriquement l''intersection entre la fonction f(x) et la fonction g(x) pour chacun des cas suivants: </p><p>\(\textit{La réponse attendue est un point et doit donc être écrite suivant l''exemple suivant: (3 ; -1)}\)</p><p>\(\textit{S''il n''y a pas d''intersection, tu écriras simplement : /}\) .</p>', true, '2017-07-11 16:06:51.484204+02', '2017-07-11 16:06:51.48424+02', true, 'submitted', 1220, 285);
