INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (920, '<p style="font-size: 16px;">Soit f(x)=2-0,5x, une fonction du premier degré appartenant au plan Oxy.</p><p style="font-size: 16px;">Détermine graphiquement l''intersection entre la fonction f(x) et la fonction g(x) pour chacun des cas suivants: </p><p>a.) g(x)= -1+x</p><p>b.) g(x)= 3</p><p>c.) g(x) = -2,5 + 0,5x</p><p>d.) g(x) = -0,1 x + 1</p>', true, '2017-07-11 16:15:27.558153+02', '2017-07-11 16:15:27.558184+02', false, 'submitted', 1220, 284);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (952, '<p>Résoudre l''équation \( cos(x) + sin(x) = 1 \)</p><p><i>Les réponses données doivent être comprises dans l''intervalle </i>\( [0,2\pi [ \)<i></i><br/></p>', true, '2017-07-17 10:37:29.334054+02', '2017-07-17 10:37:29.334086+02', true, 'submitted', 99, 491);
