INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1078, '<p><img src="/media/exercices/T3-U1-T3_02.PNG"/></p><p>Soit ABC , un triangle quelconque. Les points D et E sont respectivement les milieux de [AC] et [BC].</p><p>1) <b>Démontre</b> que les droites [AB] et [DE] sont parallèles</p><p>2) <b>Démontre</b> que les triangles ABC et DEC sont semblables.<br/></p>', true, '2017-07-24 09:49:00.065112+02', '2017-07-24 09:49:43.896358+02', true, 'submitted', 99, 247);
