INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (872, '<p>En rentrant chez moi, je m''aperçois que j''ai oublié mes clés. Je sais que le bas de la fenêtre du premier étage se trouve à 4m du sol et qu''elle est entrouverte. Un voisin me prête une échelle de 4,2 m de long ; pour grimper sans tomber, je suis obligé de poser les pieds de l''échelle à au moins 1,9 m du pied du mur.</p><p>Pourrais-je atteindre le bas de ma fenêtre ? <b>Justifie</b><br/></p>', true, '2017-07-07 10:42:07.321591+02', '2017-07-25 10:16:38.914126+02', true, 'submitted', 99, 179);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (966, '<p>Soit le polynôme \(P(x)=-3x^2-5x+2\).</p><p>Sans effectuer de division, reconnais s''il est divisible par les expressions suivantes : </p>', true, '2017-07-17 12:42:36.857126+02', '2017-07-17 12:42:36.857175+02', true, 'submitted', 1220, 291);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (926, '<p>Détermine les paramètres m et p de chaque droite (y=mx+p) pour les différentes conditions suivantes:</p><p>Ecris ta réponse sous la forme &#34;m= et p=&#34;. Par exemple : m=3 et p=2,7</p><p><br/></p>', true, '2017-07-12 11:59:44.252125+02', '2017-07-12 11:59:44.252157+02', true, 'submitted', 1220, 280);
