INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (969, '<p>Résous l''inéquation suivante et justifie les étapes :</p><p>\(x^3+3x^2&gt;4x\)</p>', true, '2017-07-17 14:21:50.525991+02', '2017-07-17 14:21:50.526024+02', false, 'submitted', 1220, 289);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (982, '<p>Dans un repère du plan \( (O ; \vec{i} ; \vec{j} ) \),</p><p>Soit : \( d_1 \equiv 2x + y - 3 = 0 \) et \( d_2 \equiv -4x -2y + 5 = 0 \).</p><p>Est-ce que les droites \( d_1 \) et \(d_2 \) sont-elles parallèles ? <b>Justifie</b><br/></p>', true, '2017-07-17 17:06:37.252492+02', '2017-07-17 17:06:37.252523+02', false, 'submitted', 99, 369);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1079, '<p><img src="/media/exercices/TG5-U3-A3_02.PNG"/></p><p>Des informations sur les limites et asymptotes de fonctions te sont fournies. Apparie les informations aux graphiques correspondants \(f(x)\), \(g(x)\), \(h(x)\) et \(p(x)\).</p>', true, '2017-07-24 10:00:40.303187+02', '2017-07-24 10:04:19.50362+02', true, 'submitted', 1207, 464);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1110, '<img src="/media/exercices/T3-U4-A5A_01.PNG" />
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (488, '<p><img src="/media/exercices/T4-U4-A2_01.PNG"/></p><p><br/></p><p>Les fonctions f1, f2 et f3 sont de fonctions de second degré, c''est à dire qu''elles s''expriment toutes sous la forme: f(x)=ax^2 +bx+c. <br/><br/>f1, f2 et f3 sont représentées par leurs tracés sur la figure ci-dessus.<br/><br/>Trouve l''expression analytique de f1, f2 et f3 et donne les valeurs de a, b et c.<br/><br/></p>', true, '2017-02-05 13:09:26.670139+01', '2017-08-21 16:06:39.986354+02', true, 'submitted', 556, 331);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (933, '<p>Calcule la dérivée des fonctions suivantes. </p><p>Détermine l''expression analytique de la dérivée de chacune des fonctions suivantes sur une feuille de papier. Pour pouvoir vérifier ta réponse, on te demande seulement d''écrire la valeur de la dérivée pour une certaine valeur d''abscisse.</p><p><br/></p><p>Ecris ta réponse sous forme de nombres décimaux, arrondis à deux décimales. </p><p>Veille à séparer les unités des décimales par une virgule (pas un point). </p>', true, '2017-07-13 15:34:48.894971+02', '2017-07-13 15:34:48.895005+02', true, 'submitted', 1220, 473);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (934, '<p style="font-size: 16px;">Calcule la dérivée des fonctions suivantes. </p><p style="font-size: 16px;">Détermine l''expression analytique de la dérivée de chacune des fonctions suivantes sur une feuille de papier. Pour pouvoir vérifier ta réponse, on te demande seulement d''écrire la valeur de la dérivée pour une certaine valeur d''abscisse.</p><p style="font-size: 16px;"><br/></p><p style="font-size: 16px;">Ecris ta réponse sous forme de nombres décimaux, arrondis à deux décimales. </p><p style="font-size: 16px;">Veille à séparer les unités des décimales par une virgule (pas un point). </p>', true, '2017-07-13 15:41:56.324769+02', '2017-07-13 15:41:56.3248+02', true, 'submitted', 1220, 473);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (935, '<p style="font-size: 16px;">Calcule la dérivée des fonctions suivantes. </p><p style="font-size: 16px;">Détermine l''expression analytique de la dérivée de chacune des fonctions suivantes sur une feuille de papier. Pour pouvoir vérifier ta réponse, on te demande seulement d''écrire la valeur de la dérivée pour une certaine valeur d''abscisse.</p><p style="font-size: 16px;"><br/></p><p style="font-size: 16px;">Ecris ta réponse sous forme de nombres décimaux, arrondis à deux décimales. </p><p style="font-size: 16px;">Veille à séparer les unités des décimales par une virgule (pas un point). </p>', true, '2017-07-13 15:49:19.530553+02', '2017-07-13 15:49:19.530587+02', true, 'submitted', 1220, 473);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1062, '<img src="/media/exercices/TG5-U4-T3B_01.PNG" />
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1064, '<p>Le 1er janvier 2000, Oscar a placé 1100€ sur un compte à un taux de 4% à intérêts \(\textbf{simples}\).</p><p>Le même jour, Odile a placé 1000 € sur un compte à un taux de 4% à intérêts \(\textbf{composés}\).</p><p><br/></p><p>Arrondis tes réponses à <i>deux décimales.</i></p><p><br/></p>', true, '2017-07-20 15:15:28.316534+02', '2017-07-20 15:15:28.316562+02', true, 'submitted', 1220, 455);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (936, '<p><img src="/media/exercices/TG5-U4-C2_01.PNG"/></p><p>Voici le graphe de la fonction <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">f</span></span><span id="MJXc-Node-14" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-15" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-16" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span><span id="MJXc-Node-17" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-18" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-19" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-20" class="mjx-mo MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">−</span></span><span id="MJXc-Node-21" class="mjx-mn MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">1</span></span><span id="MJXc-Node-22" class="mjx-msubsup"><span class="mjx-base"><span id="MJXc-Node-23" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span></span><span class="mjx-sup" style="font-size: 70.7%;vertical-align: 0.513em;"><span id="MJXc-Node-24" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">3</span></span></span></span><span id="MJXc-Node-25" class="mjx-mo MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">+</span></span><span id="MJXc-Node-26" class="mjx-mn MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">1</span></span></span></span><span class="MJX_Assistive_MathML">f(x)=(x−1)3+1</span></span>, représentée dans le plan Oxy.</p><p>En observant le graphe, détermine les signes et leurs changements successifs de ses dérivées premières et secondes. </p><p>Tu noteras les signes successifs en partant de l''infini négatif vers l''infini positif.</p><p>Par exemple les signes de f(x) se noteraient ici : -0+</p>', true, '2017-07-13 16:22:40.318662+02', '2017-08-09 09:51:55.802289+02', true, 'submitted', 1220, 471);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (562, '<p><img src="/media/exercices/S31E_02.GIF"/>Mesure l''amplitude de cet angle saillant.</p>', true, '2017-03-29 16:27:44.29701+02', '2017-08-21 16:57:24.610875+02', false, 'submitted', 123, 67);
