INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (937, '<p><img src="/media/exercices/TG5-U4-C2_02.PNG"/></p><p>Voici le graphe de la fonction \(f(x)=(x-1)(x+2)(x+0,4)\), représentée dans le plan Oxy.</p><p style="font-size: 16px;">En observant le graphe, détermine les signes et leurs changements successifs de ses dérivées premières et secondes. </p><p style="font-size: 16px;">Tu noteras les signes successifs en partant de l''infini négatif vers l''infini positif et en mentionnant lorsque les fonctions intersectent l''axe des abscisses.</p><p style="font-size: 16px;">Par exemple les signes de f(x) se noteraient ici : -0+0-0+</p>', true, '2017-07-13 16:30:27.879679+02', '2017-08-09 09:49:32.917488+02', true, 'submitted', 1220, 471);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (942, '<p><img src="/media/exercices/TG5-U4-T5_02.PNG"/></p><p style="font-size: 16px;">Sur chacun des graphes ci-dessus sont représentées deux fonctions dans le plan Oxy.</p><p style="font-size: 16px;">Il s''agit à chaque fois du graphique d''une fonction et celui de sa dérivée.</p><p style="font-size: 16px;">Distingue pour chaque cas, quel graphique correspond à celui de la dérivée et lequel correspond à celui de la fonction.</p>', true, '2017-07-14 10:47:25.66224+02', '2017-08-09 09:38:00.549086+02', true, 'submitted', 1220, 481);
