INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1008, '<p>Trace le graphique des fonctions trigonométriques suivantes :</p><p>1) \( 2\cos(x) + \dfrac{3}{2} \)</p><p>2) \( \sin(x) + \cos(x+ \dfrac{\pi}{2}) \)</p><p>3) \( \cos(4x + 3) - 2 \)</p><p>4) \( \tan( \dfrac{1}{2}x) - 1 \)</p><p><br/></p>', true, '2017-07-19 09:53:57.540468+02', '2017-07-19 09:53:57.540512+02', false, 'submitted', 1207, 489);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (963, '<p style="font-size: 16px;">Sans effectuer de division, identifie et coche les polynômes par lesquels les polynômes suivant sont divisibles : </p><p style="font-size: 16px;">N.B.: Plusieurs réponses peuvent être cochées.</p>', true, '2017-07-17 12:31:00.376101+02', '2017-07-17 12:31:00.376164+02', true, 'submitted', 1220, 291);
