INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1003, '<p>Un travail \( W \) est fourni lorsqu''une certaine force \( F \) agit sur un objet et engendre ainsi un déplacement \( d \). L''intensité de ce travail est obtenue grâce à la formule suivante : <br/></p><p>\(W = F \cdot d \)</p><p>Les unités du travail sont le Joule \(J\). Par ailleurs, \(1J = 1~Nm\).</p><p>Soit un ressort dont la longueur au repos vaut \(1~cm\). Ce ressort nécessite une force de \(480~N\) pour qu''il puisse s''allonger et atteindre la longueur de \(3~cm\). </p>', true, '2017-07-18 16:16:19.148436+02', '2017-07-18 16:16:19.148467+02', true, 'submitted', 1207, 520);
