INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (101, '<p>CLASSE ces valeurs par ordre croissant (du plus petit au plus grand).</p><p><br/></p><p>    0,2      \(\dfrac {1} {4}\)     30%     \(\dfrac {33} {200}\)</p><p><br/></p><div class="pull-right"><small>Source: Laurent Fourny, Test prérequis 1, 6TQ</small></div><p><br/></p>', true, '2016-12-12 14:10:45.888519+01', '2017-08-21 17:27:30.52283+02', true, 'S13k_1', NULL, 29);
