INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (964, '<p>Calcule la valeur de la constante \( a \) afin que la valeur numérique du polynôme soit égale à \( 3 \) lorsque celui-ci est évalué en \( x = -2\). Ecris la solution sous forme de fraction irréductible.</p>', true, '2017-07-17 12:33:00.12073+02', '2017-07-17 12:33:00.120806+02', true, 'submitted', 1207, 293);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1020, '<p>Soit 2 triangles \( \Delta_1 \) et  \( \Delta_2 \).</p><p>\( \cdot \)  \( \Delta_1 \) a un angle de 45° compris entre deux côtés mesurant respectivement 30 et 60 mm</p><p>\( \cdot \)  \( \Delta_2 \) a un angle de 45° compris entre deux côtés mesurant respectivement 13 et 26 mm<br/></p>', true, '2017-07-19 11:47:12.864949+02', '2017-07-19 11:47:12.86498+02', true, 'submitted', 99, 244);
