INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1089, '<p>Donne un exemple de limite de fonction qui illustre les cas d''indétermination ci-dessous :</p><p><br/></p><p>1) \( +\infty - \infty \)</p><p>2) \(0 \cdot (-\infty) \)</p><p>3) \( \dfrac{0}{0} \)</p><p>4) \( \dfrac{+\infty}{-\infty} \)</p>', true, '2017-07-24 11:38:18.832352+02', '2017-07-24 11:38:18.83238+02', false, 'submitted', 1207, 461);
