INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (948, '<p>Résoudre l''équation \( sin(\frac{x}{2}) + cos x = 1 \)</p><p><i>Les réponses données doivent être comprise dans l''intervalle</i> \( [0,2\pi ] \)<i></i><br/></p>', true, '2017-07-17 10:15:08.298238+02', '2017-07-17 10:15:08.298281+02', true, 'submitted', 99, 491);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (949, '<p>Résous les équations suivantes. Ecris la solution sous forme d''ensemble solution: si elle vaut 4, écris S = {4}.</p>', true, '2017-07-17 10:17:25.570299+02', '2017-07-17 10:17:25.570333+02', true, 'submitted', 1207, 295);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (950, '<p>Résoudre l''équation \( cos (3x + \pi) = cos x \)</p><p><i>Les réponses données doivent être compris dans l''intervalle </i>\( [ 0,2\pi ] \)<i></i><br/></p>', true, '2017-07-17 10:30:02.046836+02', '2017-07-17 10:30:02.046891+02', true, 'submitted', 99, 491);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (951, '<p>Résoudre l''équation \( cos(x) + cos(2x) = 0 \)</p><p><i>Les réponses données doivent être comprise dans l''intervalle </i>\( [0,2\pi [ \)<br/></p>', true, '2017-07-17 10:35:04.011367+02', '2017-07-17 10:35:04.011407+02', true, 'submitted', 99, 491);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (954, '<p>Résous les équations suivantes. Ecris la solution sous forme de fraction irréductible. Si la solution est négative, place de signe &#34;-&#34; devant la fraction. Utilise uniquement le clavier qui apparait sur ton écran. </p>', true, '2017-07-17 10:45:27.584163+02', '2017-07-17 10:45:27.584197+02', true, 'submitted', 1207, 295);
