INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1011, '<p>Calcule la limite et la dérivée suivante.</p><p><i>Rappel :</i> \( tanh(x) = \frac{e^x-e^{-x}}{e^x+e^{-x}} \)<br/></p>', true, '2017-07-19 10:34:59.375711+02', '2017-07-19 10:34:59.37575+02', true, 'submitted', 99, 525);
