INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (887, '<p><img src="/media/exercices/S12AII_02.PNG"/></p><p>Des nombres peuvent être représentés avec des jetons dans un abaque.</p><p>En te basant sur l''exemple du Tableau 1, <b>complète</b> le Tableau 2.<br/></p>', true, '2017-07-07 12:49:47.945981+02', '2017-07-25 10:34:29.003089+02', true, 'submitted', 99, 10);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (956, '<p style="font-size: 16px;"><b><u>Division de polynômes :</u></b></p><p style="font-size: 16px;">Soit, la division du polynôme P(x) par un polynôme D(x) : \(\frac{P(x)}{D(x)}\)<span id="MathJax-Element-1-Frame" class="mjx-chtml MathJax_CHTML" style="text-align: left;font-size: 19.36px;float: none;direction: ltr;"><span id="MJXc-Node-1" class="mjx-math"><span id="MJXc-Node-2" class="mjx-mrow" style="text-align: left;"><span id="MJXc-Node-3" class="mjx-mfrac" style="text-align: left;"><span class="mjx-box MJXc-stacked" style="text-align: left;height: 0px;width: 1.681em;"><span class="mjx-numerator" style="text-align: center;font-size: 13.6875px;width: 2.378em;"><span id="MJXc-Node-4" class="mjx-mrow" style="text-align: left;"><span id="MJXc-Node-5" class="mjx-mi" style="text-align: left;"><span class="mjx-char MJXc-TeX-math-I" style="text-align: left;"><br/></span></span></span></span></span></span></span></span></span></p><p style="font-size: 16px;">La division de l''un par l''autre donnera une solution du type : \(\frac{P(x)}{D(x)}=P_2(x)+\frac{R(x)}{D(x)}\) où \(P_2(x)\)<span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="text-align: left;font-size: 19.36px;float: none;direction: ltr;"><span class="MJX_Assistive_MathML" style="height: 1px !important;width: 1px !important;">P2(x)</span></span> est un polynôme et <span id="MathJax-Element-4-Frame" class="mjx-chtml MathJax_CHTML" style="text-align: left;font-size: 19.36px;float: none;direction: ltr;"><span id="MJXc-Node-54" class="mjx-math"><span id="MJXc-Node-55" class="mjx-mrow" style="text-align: left;"><span id="MJXc-Node-56" class="mjx-mi" style="text-align: left;"><span class="mjx-char MJXc-TeX-math-I" style="text-align: left;">R</span></span><span id="MJXc-Node-57" class="mjx-mo" style="text-align: left;"><span class="mjx-char MJXc-TeX-main-R" style="text-align: left;">(</span></span><span id="MJXc-Node-58" class="mjx-mi" style="text-align: left;"><span class="mjx-char MJXc-TeX-math-I" style="text-align: left;">x</span></span><span id="MJXc-Node-59" class="mjx-mo" style="text-align: left;"><span class="mjx-char MJXc-TeX-main-R" style="text-align: left;">)</span></span></span></span><span class="MJX_Assistive_MathML" style="height: 1px !important;width: 1px !important;">R(x)</span></span> est le reste. <br/></p><p style="font-size: 16px;">On te demande d''effectuer la division et puis d''identifier et d''écrire les polynôme <span id="MathJax-Element-5-Frame" class="mjx-chtml MathJax_CHTML" style="text-align: left;font-size: 19.36px;float: none;direction: ltr;"><span id="MJXc-Node-60" class="mjx-math"><span id="MJXc-Node-61" class="mjx-mrow" style="text-align: left;"><span id="MJXc-Node-62" class="mjx-msubsup" style="text-align: left;"><span class="mjx-base" style="text-align: left;"><span id="MJXc-Node-63" class="mjx-mi" style="text-align: left;"><span class="mjx-char MJXc-TeX-math-I" style="text-align: left;">P</span></span></span><span class="mjx-sub" style="text-align: left;font-size: 13.6875px;vertical-align: -0.212em;"><span id="MJXc-Node-64" class="mjx-mn" style="text-align: left;"><span class="mjx-char MJXc-TeX-main-R" style="text-align: left;">2</span></span></span></span><span id="MJXc-Node-65" class="mjx-mo" style="text-align: left;"><span class="mjx-char MJXc-TeX-main-R" style="text-align: left;">(</span></span><span id="MJXc-Node-66" class="mjx-mi" style="text-align: left;"><span class="mjx-char MJXc-TeX-math-I" style="text-align: left;">x</span></span><span id="MJXc-Node-67" class="mjx-mo" style="text-align: left;"><span class="mjx-char MJXc-TeX-main-R" style="text-align: left;">)</span></span></span></span><span class="MJX_Assistive_MathML" style="height: 1px !important;width: 1px !important;">P2(x)</span></span> et \(R(x)\)<span id="MathJax-Element-6-Frame" class="mjx-chtml MJXc-processed" style="text-align: left;font-size: 121%;float: none;direction: ltr;"><span id="MJXc-Node-68" class="mjx-math"><span id="MJXc-Node-69" class="mjx-mrow" style="text-align: left;"><span id="MJXc-Node-70" class="mjx-mi" style="text-align: left;"><span class="mjx-char MJXc-TeX-math-I" style="text-align: left;">R</span></span><span id="MJXc-Node-71" class="mjx-mo" style="text-align: left;"><span class="mjx-char MJXc-TeX-main-R" style="text-align: left;">(</span></span><span id="MJXc-Node-72" class="mjx-mi" style="text-align: left;"><span class="mjx-char MJXc-TeX-math-I" style="text-align: left;">x</span></span><span id="MJXc-Node-73" class="mjx-mo" style="text-align: left;"><span class="mjx-char MJXc-TeX-main-R" style="text-align: left;">)</span></span></span></span><span class="MJX_Assistive_MathML" style="height: 1px !important;width: 1px !important;">R(x)</span><span id="MJXc-Node-80" class="mjx-math"><span id="MJXc-Node-81" class="mjx-mrow"><span id="MJXc-Node-82" class="mjx-mfrac"><span class="mjx-box MJXc-stacked" style="width: 1.655em;"><span class="mjx-numerator" style="font-size: 70.7%;width: 2.341em;"><span id="MJXc-Node-83" class="mjx-mrow"><span id="MJXc-Node-84" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">P</span></span><span id="MJXc-Node-85" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-86" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-87" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span></span></span><span class="mjx-denominator" style="font-size: 70.7%;width: 2.341em;"><span id="MJXc-Node-88" class="mjx-mrow"><span id="MJXc-Node-89" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">Q</span></span><span id="MJXc-Node-90" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-91" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-92" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span></span></span><span class="mjx-line" style="width: 1.655em;"></span></span><span class="mjx-vsize" style="height: 1.803em;vertical-align: -0.652em;"></span></span></span></span><span class="MJX_Assistive_MathML">P(x)Q(x)</span></span> pour les divisions suivantes :</p><p style="font-size: 16px;">Remarques : Utilise le clavier mathématique pour répondre. De plus, tes réponses seront des polynômes. Veille à les écrire de manière ordonnée (du plus grand exposant vers le plus petit). </p><p style="font-size: 16px;">Exemples de réponse : </p><p style="font-size: 16px;">x^3+2x-1</p><p style="font-size: 16px;">2x</p><p style="font-size: 16px;">0</p><p style="font-size: 16px;">-x^2+x+1</p><p style="font-size: 16px;">...</p>', true, '2017-07-17 11:21:36.753522+02', '2017-07-17 11:21:36.753563+02', true, 'submitted', 1220, 290);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1054, '<p><img src="/media/exercices/T4-U4-A4B_01.PNG"/></p><p>Soit la fonction <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">h</span></span><span id="MJXc-Node-14" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-15" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-16" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span><span id="MJXc-Node-17" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-18" class="mjx-mfrac MJXc-space3"><span class="mjx-box MJXc-stacked" style="width: 0.495em;"><span class="mjx-numerator" style="font-size: 70.7%;width: 0.7em;"><span id="MJXc-Node-19" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">1</span></span></span><span class="mjx-denominator" style="font-size: 70.7%;width: 0.7em;"><span id="MJXc-Node-20" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">2</span></span></span><span style="width: 0.495em;" class="mjx-line"></span></span><span style="height: 1.331em;vertical-align: -0.415em;" class="mjx-vsize"></span></span><span id="MJXc-Node-21" class="mjx-msubsup"><span class="mjx-base"><span id="MJXc-Node-22" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span></span><span class="mjx-sup" style="font-size: 70.7%;vertical-align: 0.513em;"><span id="MJXc-Node-23" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">3</span></span></span></span><span id="MJXc-Node-24" class="mjx-mo MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">−</span></span><span id="MJXc-Node-25" class="mjx-mn MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">10</span></span><span id="MJXc-Node-26" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span></span></span><span class="MJX_Assistive_MathML">h(x)=12x3−10x</span></span>.</p><p>Utilise le graphique de cette fonction pour déterminer une des solutions des équations suivantes :</p><p><i>(Les réponses données sont approximative)</i><br/></p>', true, '2017-07-20 12:35:08.133723+02', '2017-07-26 11:01:17.754875+02', true, 'submitted', 99, 668);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1144, '<p><img src="/media/exercices/T4-U5-C2_02.PNG"/></p><p>Soit les fonctions suivantes :</p><p>\( \cdot f(x) = \frac{x-1}{(x-2)(5-x)}\)</p><p>\( \cdot g(x) = \frac{1}{2} (x-1) \)</p><p>Sans effectuer de calcul, <b>donne</b> l''ensemble des solutions pour \( f(x)=g(x) \) en te basant sur le graphique de ces 2 fonctions. <i>Veille bien à justifier ta réponse !</i><br/></p>', true, '2017-07-26 11:46:19.522233+02', '2017-07-26 11:49:14.196035+02', true, 'submitted', 99, 339);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (953, '<p><b><u>Division de polynômes :</u></b></p><p>Soit, la division du polynôme P(x) par un polynôme D(x) : \(\frac{P(x)}{D(x)}\)</p><p>La division de l''un par l''autre donnera une solution du type :  \(\frac{P(x)}{D(x)}=P_2(x)+\frac{R(x)}{D(x)}\) où <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-5-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-56" class="mjx-math"><span id="MJXc-Node-57" class="mjx-mrow"><span id="MJXc-Node-58" class="mjx-msubsup"><span class="mjx-base"><span id="MJXc-Node-59" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">P</span></span></span><span class="mjx-sub" style="font-size: 70.7%;vertical-align: -0.212em;"><span id="MJXc-Node-60" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">2</span></span></span></span><span id="MJXc-Node-61" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-62" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-63" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span></span></span><span class="MJX_Assistive_MathML">P2(x)</span></span> pour les divisions suivantes.</p><p>Remarques : Utilise le clavier mathématique pour répondre. De plus, tes réponses seront des polynômes. Veille à les écrire de manière ordonnée (du plus grand exposant vers le plus petit). </p><p>Exemples de réponse : </p><p>x^3+2x-1</p><p>2x</p><p>0</p><p>-x^2+x+1</p><p>...</p>', true, '2017-07-17 10:41:49.188833+02', '2017-07-17 11:24:51.088174+02', true, 'submitted', 1220, 290);
