INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (958, '<p>Résous l''équation suivante:</p><p>\( \dfrac{3x^2+3x+1}{x-1} = \dfrac{7}{x-1} \)</p><p>Afin d''y arriver, suis les étapes indiquées dans chaque sous-question. </p>', true, '2017-07-17 11:40:34.462168+02', '2017-07-17 11:40:34.462201+02', true, 'submitted', 1207, 296);
