INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (960, '<p>Quelle est la valeur numérique des polynômes suivants? Ecris la solution sous forme de fraction irréductible. Utilise uniquement le clavier qui apparait sur ton écran.</p>', true, '2017-07-17 12:12:09.856631+02', '2017-07-17 12:12:09.856678+02', true, 'submitted', 1207, 293);
