INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (978, '<p>Démontrer la formule donnant la somme des n premiers termes d''une suite arithmétique.</p><p>Démontrer la formule donnant la somme des n premiers termes d''une suite géométrique.</p><p><br/></p><p>Développe ces démonstrations sur une feuille de papier et fais les corriger par ton/ta professeur.</p>', true, '2017-07-17 16:41:28.557559+02', '2017-07-17 16:41:28.557592+02', false, 'submitted', 1220, 442);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (973, '<p>Voici une série de grandeurs massiques:</p><p><b>\( \textbf{Série (A)} \)</b></p><p></p><p style="font-size: 16px;">1. \(0,005 \) mg</p><p style="font-size: 16px;">2. \(21 \cdot 10^{-1} \) tonnes</p><p style="font-size: 16px;">3. \(162 \cdot 10^{-2} \) g</p><p style="font-size: 16px;">4. \(8,2 \cdot 10^{-4} \mu\)g</p><p style="font-size: 16px;">5. \(150 \) kg</p><p style="font-size: 16px;">6. \( 1,6 \cdot 10^{3} \) kg</p>', true, '2017-07-17 14:53:18.689067+02', '2017-07-17 14:53:18.6891+02', true, 'submitted', 1207, 298);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (974, '<p><b>Donne</b> une primitive des fonctions ci-dessous en utilisant la méthode d''intégration par partie.<br/></p>', true, '2017-07-17 14:54:26.132359+02', '2017-07-17 14:54:26.132392+02', true, 'submitted', 99, 675);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (975, '<p>Calcule les limites suivantes. </p><p><br/></p><p style="text-align: right;">Source : Pr. Bolly, cours de rhétorique du Collège Saint-Michel​</p>', true, '2017-07-17 15:43:59.166906+02', '2017-07-17 15:43:59.16694+02', true, 'submitted', 1207, 526);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (976, '<p>Calcule les limites suivantes.</p>', true, '2017-07-17 15:51:31.370233+02', '2017-07-17 15:51:31.370267+02', true, 'submitted', 1207, 526);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (980, '<p>Deux fonctions te sont données. Vérifie que \(F(x)\) est bien la primitive de \(f(x)\). \(C\) représente une constante.</p><p style="text-align: right;">​</p><p style="text-align: right;">Source : P. Bolly, cours de rhétorique du Collège Saint-Michel</p>', true, '2017-07-17 16:48:15.949819+02', '2017-07-17 16:48:15.949874+02', true, 'submitted', 1207, 516);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (983, '<p>Soient deux fonctions:</p><p>\( f(x) = x-1 \)</p><p>\( g(x) = \dfrac{1}{9} (x-1)^3 \)</p><p><br/></p><p>Cet exercice a pour but de calculer l''aire comprise entre certaines courbes. Pour ce faire, calcule d''abord les trois points d''intersection. Encode-les dans l''ordre croissant des abscisses (le point d''intersection avec la plus petite abscisse sera encodé en premier, et ainsi de suite). Par exemple, s''il y a deux points d''intersection, tu écris: </p><p>\( (-1,0),(1,2) \)</p><p><br/></p><p>N''hésite pas à faire un dessin pour y voir plus clair! En tenant compte des axes, tu devrais distinguer trois aires distinctes.</p>', true, '2017-07-18 09:40:26.968671+02', '2017-07-18 09:40:26.968715+02', true, 'submitted', 1207, 519);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1099, '<img src="/media/exercices/TG5-U5-C3_01.PNG" />
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (992, '<p style="font-size: 16px;">Soit \((U(n))=u_1, u_2, u_3, ... u_n\), une suite géométrique de premier terme \(u_1\) et de raison q.</p><p style="font-size: 16px;"><br/></p><p style="font-size: 16px;">Pour les suites définies ci-dessous, détermine la raison q et l''expression du terme général.</p>', true, '2017-07-18 12:07:54.594452+02', '2017-07-18 12:07:54.594484+02', true, 'submitted', 1220, 447);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (984, '<p>Cet exercice a pour but de calculer le volume de certains solides. Tu vas enfin comprendre d''où proviennent les mystérieuses formules (volume d''une sphère, d''un cône, ...) que tu as du apprendre par coeur tout au long de ta scolarité. </p><p><br/>Ces formules sont obtenues par la révolution (la rotation) d''une courbe autour de l''axe des abscisses, sur un intervalle \( \left[a,b\right] \).</p><p><br/></p><p>La formule traduisant cela est la suivante:</p><p>\( V = \int_{a}^{b} \left[f(x)\right]^2dx \)</p>', true, '2017-07-18 10:36:42.79042+02', '2017-07-18 10:36:42.790452+02', true, 'submitted', 1207, 519);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (986, '<p>Soit<b> S</b> définit comme le succès et <b>p(S)</b> sa probabilité.</p><p>Pour chacune des situations suivantes, <b>calcule </b>la probabilité de succès <b>p(S)</b><br/></p>', true, '2017-07-18 11:05:32.00262+02', '2017-07-26 10:09:44.597429+02', true, 'submitted', 99, 506);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1082, '<img src="/media/exercices/TG5-U3-A5_02.PNG" />
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1104, '<p>Trace le graphique des fonctions suivantes :</p><p>\(f(x) = 3 + 3x \)</p><p>\(g(x) = -2.5x+0.5\)</p><p>\(h(x) = 4 \)</p><p>\(i(x) = -\dfrac{3}{2}x - 5 \)</p><p><br/></p><p>Lorsque \( x = 5\), quelle fonction fournit la plus petite image? Et la plus grande?</p>', true, '2017-07-25 08:39:30.153677+02', '2017-07-25 08:39:30.153757+02', false, 'submitted', 1207, 279);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (990, '<img src="/media/exercices/TG6-U3-C2_01.PNG" />
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (988, '<p>Soit \((U_n)=u_1, u_2, u_3, ..., u_n\), une suite arithmétique de premier terme \(u_1\) et de raison r.</p><p>Pour les suites définies ci-dessous, trouve la raison r et l''expression du terme général. </p>', true, '2017-07-18 11:06:18.742518+02', '2017-07-18 11:55:34.910108+02', true, 'submitted', 1220, 446);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (987, '<p style="font-size: 16px;"></p><p style="font-size: 16px;">Soit \((U_n)=u_1, u_2, u_3, ..., u_n\), une suite arithmétique de premier terme \(u_1\) et de raison r.</p><p style="font-size: 16px;">Pour les suites définies ci-dessous, trouve la raison r et l''expression du terme général. </p><p style="font-size: 16px;"></p>', true, '2017-07-18 11:05:47.664692+02', '2017-07-18 11:56:03.162914+02', true, 'submitted', 1220, 446);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1021, '<p>Réponds aux questions ci-dessous sur la somme des termes d''une suite arithmétique.</p><p>La somme d''une suite est définie comme :</p><p>\(S_n=u_1 + u_2 + u_3 + ... + u_n\).</p>', true, '2017-07-19 11:53:21.72897+02', '2017-07-19 11:53:21.729001+02', true, 'submitted', 1220, 453);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1056, '<p>Représente graphiquement les fonctions trigonométriques usuelles : \( \sin(x) \), \( \cos(x) \) et \( \tan(x) \).</p><p>Sois précis!</p>', true, '2017-07-20 12:44:43.963053+02', '2017-07-20 12:44:43.963082+02', false, 'submitted', 1207, 483);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1083, '<img src="/media/exercices/T3-U2-A1_02.PNG" />
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (915, '<p>A.) Trace les fonctions suivantes sur un graphe Oxy :</p><p>f(x) = 0,5x+3</p><p>g(x) = -2</p><p>h(x) = 5+2x</p><p>k(x) = -0,25x-2</p><p><br/></p><p>B.) Pour chacune des fonctions du premier degré ci-dessus (du type f(x)=mx+p), identifie et indique sur ton graphe les paramètres m et p.</p>', true, '2017-07-11 14:35:53.362516+02', '2017-07-26 09:24:36.31933+02', true, 'submitted', 1220, 279);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (995, '<p style="font-size: 16px;">Soit \((U_n)= u_1, u_2, u_3, ... , u_n\), une suite </p><blockquote style="font-size: 17.5px;"><p>-​soit, arithmétique de raison r</p><p>-soit, géométrique de raison q.</p></blockquote><p><span style="font-size: 17.5px;">​</span></p><p><br style="font-size: 16px;"/></p><blockquote style="font-size: 17.5px;"><p></p></blockquote><div style="font-size: 16px;"><p>Pour les suites définies ci-dessous, trouve la raison (r ou q) ainsi que l''expression du terme général et, réponds aux questions.</p></div>', true, '2017-07-18 12:30:34.43524+02', '2017-07-18 12:30:34.435281+02', true, 'submitted', 1220, 445);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1224, '<img src="/media/exercices/P2D-U1-T1_01.PNG" />
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (993, '<p>Soit \((U(n))=u_1, u_2, u_3, ... u_n\), une suite géométrique de premier terme \(u_1\) et de raison q.</p><p><br/></p><p>Pour les suites définies ci-dessous, détermine la raison q et l''expression du terme général.</p><p><br/></p>', true, '2017-07-18 12:08:02.124018+02', '2017-07-18 12:08:02.124064+02', true, 'submitted', 1220, 447);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (994, '<p>Calcule la primitive des fonctions suivantes. La constante de la primitive sera notée \(c\) et sera toujours le dernier terme de ta solution lorsque tu l''encodes. Utilise uniquement le clavier qui apparait sur ton écran. </p><p>De plus, il est interdit de mettre le signe \(\cdot\) : il faut écrire \( 3x \) et non \(3\cdot x \) par exemple. Lorsqu''une fraction apparait, veille bien à écrire celle-ci \( avant \) le terme en \(x\) : il faut écrire \( \dfrac{1}{2}x \) et non \( \dfrac{x}{2} \). De même, il faut écrire \( \dfrac{5}{2}x \) et non \( \dfrac{5x}{2} \).</p>', true, '2017-07-18 12:16:36.127544+02', '2017-07-18 12:16:36.127579+02', true, 'submitted', 1207, 674);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (996, '<p>Soit \((U_n)= u_1, u_2, u_3, ... , u_n\), une suite </p><blockquote><p>-​soit, arithmétique de raison r</p><p>-soit, géométrique de raison q.</p></blockquote><p><span style="font-size: 17.5px;">​</span></p><p><br/></p><blockquote><p></p></blockquote><div><p>Pour les suites définies ci-dessous, trouve la raison (r ou q) ainsi que l''expression du terme général et, réponds aux questions.</p></div>', true, '2017-07-18 12:30:44.843372+02', '2017-07-18 12:30:44.843405+02', true, 'submitted', 1220, 445);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1061, '<img src="/media/exercices/TG5-U4-T3A_01.PNG" />
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (997, '<p style="font-size: 16px;">Calcule la primitive des fonctions suivantes. La constante de la primitive sera notée \(c\)<span id="MathJax-Element-1-Frame" class="mjx-chtml MathJax_CHTML" style="text-align: left;font-size: 19.36px;float: none;direction: ltr;"><span class="MJX_Assistive_MathML" style="height: 1px !important;width: 1px !important;">c</span></span> et sera toujours le dernier terme de ta solution lorsque tu l''encodes. Utilise uniquement le clavier qui apparait sur ton écran. </p><p style="font-size: 16px;">De plus, il est interdit de mettre le signe \( \cdot \)<span id="MathJax-Element-2-Frame" class="mjx-chtml MathJax_CHTML" style="text-align: left;font-size: 19.36px;float: none;direction: ltr;"><span class="MJX_Assistive_MathML" style="height: 1px !important;width: 1px !important;">⋅</span></span> : il faut écrire \(3x\) et non \( 3 \cdot x\) par exemple. Lorsqu''une fraction apparait, veille bien à écrire celle-ci \(avant \) le terme en \(x \) : il faut écrire \( \dfrac{1}{2}x \) et non \( \dfrac{x}{2} \). De même, il faut écrire \( \dfrac{5}{2}x \) et non \( \dfrac{5x}{2} \).</p><p></p>', true, '2017-07-18 14:07:14.255649+02', '2017-07-18 14:07:14.255683+02', true, 'submitted', 1207, 674);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (998, '<p>Deux fonctions te sont données. Vérifie que \(F(x)\) est bien la primitive de \(f(x)\). \(C\) représente une constante.<br/></p><p style="text-align: right;"><br/></p><p style="text-align: right;">Source : P. Bolly, issu du cours de rhéto (MATH8) du Collège Saint-Michel​</p>', true, '2017-07-18 14:56:48.700768+02', '2017-07-18 14:56:48.700801+02', true, 'submitted', 1207, 516);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (999, '<p>En utilisant tes connaissances dans les suites, réponds aux questions suivantes: </p>', true, '2017-07-18 14:59:14.568119+02', '2017-07-18 14:59:14.568175+02', true, 'submitted', 1220, 459);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1000, '<p>Calcule la primitive des fonctions suivantes. Utilise la méthode d''intégration par parties. </p><p>Lorsque tu encodes ta réponse, veille à ne pas utiliser le signe \( \cdot \) entre chacun des termes. Par exemple, il faut écrire \( 3x \) et pas \(3 \cdot x \). Tu ne dois pas y ajouter la constante d''intégration. De plus, écris toujours les expressions trigonométriques en dernier : \( 3x\cos(x) \) et pas \( \cos(x) 3x\). Enfin, factorise le plus possible ton expression finale.</p>', true, '2017-07-18 15:34:05.843491+02', '2017-07-18 15:34:05.84353+02', true, 'submitted', 1207, 675);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1004, '<div><p>Alors qu''Oscar se balade à la mer avec ses parents, il aperçoit un escargot qui traverse la digue (d''une largeur d''environ 21m) et veut mesurer le temps qu''il met à la traverser. Il a, à sa disposition, un mètre et un sablier qui s''écoule en une minute (et qu''il doit donc retourner chaque minute). Lorsqu''Oscar démarre le sablier, l''escargot a déjà parcouru 5,30m. </p><p><u>Cas A</u> : A la fin de la première minute, l''escargot arrive à 6,08m; à la fin de la deuxième minute, il arrive à 6,86m; à la fin de la 3e minute, il arrive à 7,64m. Il avance donc de 78cm chaque minute.</p><p><u>Cas B</u> : En réalité, l''escargot se fatigue au fur et à mesure de sa course, et les mesures décrites ci-dessus ne sont pas tout-à-fait exactes. Oscar aurait plutôt mesuré comme suit : Après la première minute, l''escargot arrive bien à 6,08m; mais après la deuxième, à un peu moins de 6,83m, après la troisième minute à un peu moins de 7,55m. En fait, il ne parcours chaque minute que 96% de la distance parcourue lors de la minute précédente.</p><p>​</p><p>Les parents d''Oscar le rappellent alors pour finir la balade. Il ne peut plus continuer ses mesures. Pour chaque cas, détermine à partir de ces trois mesures, après combien de minutes l''escargot aura fini sa traversée.<br/></p></div>', true, '2017-07-18 16:39:01.737444+02', '2017-07-18 16:59:43.185653+02', true, 'submitted', 1220, 459);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1005, '<img src="/media/exercices/TG5-U5-A3_01.PNG" />
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1006, '<p>Soit \((U_n)=u_1, u_2, u_3, ..., u_n\), une suite arithmétique de raison r et de premier terme \(u_1\).</p><p>Pour les suites arithmétiques définies ci-dessous, donne le terme de rang demandé.</p>', true, '2017-07-18 17:29:06.063629+02', '2017-07-18 17:29:06.063664+02', true, 'submitted', 1220, 449);
