INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1009, '<p>Soit \((U_n)=u_1, u_2, u_3, ..., u_n\), une suite arithmétique dont on connait deux termes : \(u_{50}=16550\)  et \(u_{70}=18770\).</p><p>Trouve les valeurs demandées.</p>', true, '2017-07-19 10:20:00.475023+02', '2017-07-19 10:20:00.475076+02', true, 'submitted', 1220, 449);
