INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1013, '<p>Soit une suite géométrique \((U_n)=u_1, u_2, u_3, ..., u_n\).</p><p>Trouve les valeurs demandées pour les suites géométriques définies ci-dessous.</p><p>Arrondis tes réponses à deux décimales.</p>', true, '2017-07-19 10:49:03.943879+02', '2017-07-19 10:49:03.943919+02', true, 'submitted', 1220, 450);
