INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1016, '<p>Soit un triangle ABC rectangle en A tel que \( AB = 3 cm \) et \(AC = 2 cm \).</p><p>Le triangle A''B''C'' est un agrandissement du triangle ABC. Ce triangle est rectangle en A'' et d''aire \( 27 cm^2 \)</p><p><i>(Les réponses doivent être exprimées en cm)</i><br/></p>', true, '2017-07-19 11:25:34.309856+02', '2017-07-19 11:25:34.309886+02', true, 'submitted', 99, 242);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1017, '<p>Soit 2 triangles \( \Delta_1 \) \( \Delta_2 \).</p><p>\( \Delta_1 \) a des côtés mesurant 24, 50 et 42 cm.</p><p>\( \Delta_2 \) a des côtés mesurant 25, 21 et 12 cm.<br/></p>', true, '2017-07-19 11:38:36.341473+02', '2017-07-19 11:38:36.341505+02', true, 'submitted', 99, 244);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1018, '<p style="font-size: 16px;">Soit \((U_n)=u_1, u_2, u_3, ... u_n\), une suite :</p><blockquote style="font-size: 17.5px;"><p>-Soit arithmétique, de raison r et de premier terme \(u_1\)</p><p>-Soit géométrique, de raison q et de premier terme \(u_1\)</p></blockquote><p><span style="font-size: 17.5px;"></span></p><div><span style="font-size: 17.5px;"><br/></span></div><p>Recherche les valeurs demandées pour les suites définies ci-dessous.</p><div style="font-size: 16px;"><span style="font-size: 17.5px;"><br/></span></div><div style="font-size: 16px;"><span style="font-size: 17.5px;">N''arrondis pas tes valeurs.​</span></div>', true, '2017-07-19 11:42:52.57934+02', '2017-07-19 11:42:52.579372+02', true, 'submitted', 1220, 448);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1019, '<p>Soit \((U_n)=u_1, u_2, u_3, ... u_n\), une suite :</p><blockquote><p>-Soit arithmétique, de raison r et de premier terme \(u_1\)</p><p>-Soit géométrique, de raison q et de premier terme \(u_1\)</p></blockquote><p><span style="font-size: 17.5px;"></span><div><span style="font-size: 17.5px;"><br/></span></div>Recherche les valeurs demandées pour les suites définies ci-dessous.</p><div><span style="font-size: 17.5px;"><br/></span></div><div><span style="font-size: 17.5px;">N''arrondis pas tes valeurs.​</span><br/></div>', true, '2017-07-19 11:43:11.44188+02', '2017-07-19 11:43:11.441921+02', true, 'submitted', 1220, 448);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1026, '<p>Représente sur un graphique la suite \(u_n=\frac{n+1}{n}\), pour les valeur de \(n=1, n=2, n=3, n=4, n=8\).</p><p>Observe la limite de la suite lorsque n tend vers l''infini.</p>', true, '2017-07-19 12:34:24.621484+02', '2017-07-19 12:34:24.621517+02', false, 'submitted', 1220, 444);
