INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1107, '<p>Représente sur un graphique la suite \( u_{n+1} = \frac{2}{u_n} + 3\), avec \( u_0 = 6 \), pour les valeurs de \(n=1,n=2,n=3,n=5,=n=9\).<br/></p>', true, '2017-07-25 09:39:20.99201+02', '2017-07-25 09:39:20.992049+02', false, 'submitted', 99, 444);
