INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1028, '<p>Résous les quatre inéquations suivantes. Exprime ta solution en fraction irréductible ou en nombre entier. </p>', true, '2017-07-19 14:06:09.316272+02', '2017-07-19 14:06:09.316301+02', true, 'submitted', 1207, 286);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1015, '<p>Pour chacune des expressions analytiques ci-dessous, détermine l''amplitude, la période, le déphasage et le décalage vertical. </p><p>Exemple : \(f(x) = 3\sin(x+2) - 4\)</p><p>L''amplitude vaut \(3\), la période vaut \(2\pi\), le déphasage vaut \(-2\) et le décalage vertical vaut \(-4\). Tu encoderas ta réponse de la manière suivante, en respectant l''ordre ci-dessus :<br/></p><p>\(3\), \(2\pi\), \(-2\), \(-4\)<br/></p><p>Lorsqu''une fraction qui contient le terme \(\pi\) apparait, tu écriras le \(\pi\) derrière la fraction sous forme irréductible. Par exemple, si tu obtiens \( \dfrac{2\pi}{4}\), tu écriras \( \dfrac{1}{2}\pi \).</p>', true, '2017-07-19 11:21:31.577783+02', '2017-07-19 14:36:43.936675+02', true, 'submitted', 1207, 492);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1029, '<p>Convertis ces angles en radians. Exprime ta réponse sous forme de fraction.</p>', true, '2017-07-19 14:39:07.701707+02', '2017-07-19 14:39:07.701736+02', true, 'submitted', 1207, 486);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1030, '<p>Convertis les angles donnés (en radians) en degrés.</p>', true, '2017-07-19 14:51:05.366902+02', '2017-07-19 14:51:05.366945+02', true, 'submitted', 1207, 486);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1035, '<p>Trace le graphique des fonctions trigonométriques suivantes :</p><p>1) \(f(x) = \cos(2x) -1 \)</p><p>2) \(f(x) = 3\sin(x+ \pi) \)<br/></p><p>3) \(f(x) = \sin \left(\dfrac{2}{5}x -1 \right) +1\)</p><p>4) \(f(x) = 3\cos(x) - \dfrac{1}{2} \)<br/></p>', true, '2017-07-19 15:49:10.470045+02', '2017-07-19 15:49:10.470074+02', false, 'submitted', 1207, 489);
