INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1033, '<p><img src="/media/exercices/T3-U1-T5_01.JPEG"/></p><p>Oscar se baladait tranquillement dans une forêt à côté de son village. Très vite, un grand arbre attira son attention. Il se demandait comment il allait bien faire pour savoir combien mesure la hauteur de cet arbre. C''est à ce moment-là qu''il se rappela son cours de math. Ayant un bâton dans la paume de ses mains, il décida de le placer comme sur la figure ci-dessus. Ensuite il décide de se placer au sommet de l''ombre de l''arbre.</p><p>Sachant : - que son bâton (RT) mesure 1,6 m</p><p>            - que la distance le séparant de l''arbre (AE) mesure 10 m</p><p>            - que la distance le séparant de son bâton (RE) mesure 2,5 m</p><p>Aide Oscar à <b>calculer</b> la hauteur de l''arbre. (AB)</p><p><i>Les segments AB et RT sont bien évidemment parallèle (on néglige la largeur du bâton)</i>​</p>', true, '2017-07-19 15:22:44.782356+02', '2017-07-26 10:47:46.990671+02', true, 'submitted', 99, 249);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1043, '<p><img src="/media/exercices/TG5-U1-A2_03.PNG"/></p><p>Voici trois tableaux de séries statistiques à deux variables. </p>', true, '2017-07-20 10:37:48.757354+02', '2017-07-20 11:04:46.017281+02', true, 'submitted', 1207, 435);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1046, '<p>Donne la limite des suites suivantes lorsque n tend vers +∞.</p>', true, '2017-07-20 11:05:45.038015+02', '2017-07-20 11:05:45.038042+02', true, 'submitted', 1220, 451);
