INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1063, '<p><b>Recherche</b> les zéros éventuels des fonctions suivantes.</p><p><i>S''il n''en existe pas : met un &#34;moins&#34; entre parenthèse (-) !</i>​</p>', true, '2017-07-20 15:06:43.53227+02', '2017-07-26 11:05:08.524963+02', true, 'submitted', 99, 667);
