INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1057, '<p style="font-size: 16px;">Dans les situations ci-dessous, une certaine somme d''argent est placée à <i>intérêts composés</i> à la banque, pendant un certain temps et à un certain taux. </p><p style="font-size: 16px;">Réponds aux questions ci-dessous et arrondis tes réponses à <b><i>deux décimales</i></b>.</p>', true, '2017-07-20 12:48:42.448186+02', '2017-08-08 10:19:19.920782+02', true, 'submitted', 1220, 457);
