INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1068, '<p>Soit la fonction \(f(x) = \dfrac{2x+1}{x^2-x-2} \).</p><p>Sa dérivée seconde vaut \(f''''(x) = \dfrac{2(2x^3+3x^2+9x-1)}{(x^2-x-2)^3} \).</p><p><br/></p><p>1) Quel est le domaine de définition de cette fonction?</p><p>2) Effectue un tableau de signe sur base du calcul des racines et du domaine.</p><p>3) Donne l''expression des 3 asymptotes (2 asymptotes verticales, 1 asymptote horizontale).</p><p>4) Détermine les intervalles de croissance/décroissance ainsi que les extrema.</p><p>5) Etudie la concavité. Pour te faciliter la tâche, \(f''''(x) \) est donné!</p><p>6) Sur base des informations récoltées ci-dessus, trace la fonction \(f(x) \).</p>', true, '2017-07-20 16:08:08.884526+02', '2017-07-20 16:08:08.884552+02', false, 'submitted', 1207, 475);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1069, '<p>Les parents d''Oscar veulent louer un appartement. Ils en ont trouvé un qui leur convienne parfaitement et dont le prix de la location s''élève initialement à 10 000 € par an.  </p><p>Mais, le propriétaire leur explique qu''il compte augmenter le loyer un petit peu chaque année et leur laisse le choix entre deux options. </p><p><u>Option A</u> : Chaque année, il augmente le loyer de 450 euros par an.</p><p><u>Option B</u> : Chaque année, il augmente le loyer de 4% du montant de l''année précédente.</p><p><br/></p><p>Sachant qu''on nomme l''année 1 comme étant l''année pour laquelle le loyer est de 10000€, réponds aux questions ci-dessous.</p><p></p><p><br/></p><p>\(\textbf{Arrondis}\) tes réponses à <u><i>deux décimales</i></u>.</p><p></p>', true, '2017-07-20 16:22:14.833115+02', '2017-07-20 16:22:14.833167+02', true, 'submitted', 1220, 459);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1070, '<img src="/media/exercices/T4-U4-C2_04.PNG" />
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1073, '<p style="font-size: 16px;">Réponds aux questions suivantes.</p><p style="font-size: 16px;">\(\textbf{Arrondis}\) tes réponses à deux décimales si les réponses ne sont pas des entiers.</p>', true, '2017-07-20 16:55:49.185947+02', '2017-07-20 16:55:49.185976+02', true, 'submitted', 1220, 455);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1075, '<p><b>Ecris</b> les réciproques des fonctions suivantes !</p><p><i>(Réponse sous forme : x=...)</i><br/></p>', true, '2017-07-20 17:17:51.236382+02', '2017-07-20 17:19:30.956652+02', true, 'submitted', 99, 328);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1076, '<p>Calcule les sommes suivantes.</p><p>\(\textbf{Arrondis}\) tes réponses à deux décimales lorsque ce ne sont pas des entiers.</p>', true, '2017-07-20 17:49:13.060005+02', '2017-07-20 17:49:13.060035+02', true, 'submitted', 1220, 454);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (823, '<img src="/media/exercices/T4-U3-C3_01.PNG" />
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1085, '<p>La population d''un petit village en haute montagne, exprimée en milliers d''habitants, est caractérisée par la fonction suivante :</p><p>\( f(x) = - \dfrac{6x+100}{x+10}+10 \)</p><p><br/></p><p>où \( x \) modélise le nombre d''années qui se sont écoulées depuis 2017. </p><p><br/></p>', true, '2017-07-24 11:01:15.506747+02', '2017-07-24 11:01:15.506796+02', true, 'submitted', 1207, 467);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (828, '<p><img src="/media/exercices/TG6-U1-A2_02.PNG"/></p><p>Parmi les 125 membres d''une association sportive, 60 font du basket, 45 font du tennis et 25 pratiquent les deux sports.</p><p><br/></p><p>Soit les événements suivant : </p><p><b>B : </b>&#34;Le membre fait du basket&#34;</p><p><b>T : </b>&#34;Le membre fait du tennis&#34;</p><p><br/></p><p><b>Compléte le diagramme de Venn :</b>​</p>', true, '2017-07-04 11:29:39.578539+02', '2017-07-24 11:19:51.215231+02', true, 'submitted', 99, 498);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1087, '<p>Soient les fonctions usuelles suivantes :</p><p>\(f(x) = e^x \)</p><p>\(g(x) = x + 3 \) </p><p>\(h(x) = \sqrt [3] {x} \)</p><p>\(i(x) = \tan (x) \)</p><p>\(j(x) = \dfrac{1}{x+2} \)</p><p><br/></p><p>Détermine la succession des opérations à appliquer afin d''obtenir les fonctions composées suivantes.</p><p><br/></p><p>A titre d''exemple, l''expression \( \tan(x+3) \) est obtenue de la manière suivante : \(i(g(x))\). Tu encoderas donc i(g(x)).</p>', true, '2017-07-24 11:28:15.226034+02', '2017-07-24 11:28:15.226075+02', true, 'submitted', 1207, 460);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (860, '<p>Un jour, William décide de confier un secret à ses quatres amis. Ils ne gardent pas le secret et le confient chacun le lendemain à quatre personnes et ainsi de suite...</p><p><b>Combien de personnes</b> (sans compte William lui-même) seront au courant du secret de William après trois jours ?<br/></p>', true, '2017-07-06 17:46:29.373194+02', '2017-07-25 09:59:29.57274+02', true, 'submitted', 99, 161);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1263, '<p>Soit les fonctions suivantes :<br/>\( \cdot f(x) = (x-3)-(2x+7) \)<br/>\( \cdot g(x) = \frac{x-6}{x+3} \)<br/>\( \cdot h(x) = \frac{3}{4} \)<br/>\( \cdot p(x) = 2x \)</p><p><b>Détermine</b> l''intersection des deux fonctions proposées :<br/></p>', true, '2017-07-31 11:14:36.64877+02', '2017-07-31 11:16:31.809802+02', true, 'submitted', 99, 570);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1086, '<p><img src="/media/exercices/T3-U2-C1B_01.PNG"/></p><p>La réciproque du théorème de Pythagore s''énonce ainsi : </p><p><i><b>« Si dans un triangle, le carré de la longueur d''un côté est égal à la somme des carrés des longueurs des deux autres côtés, alors ce triangle est rectangle et son hypoténuse est le plus grand côté. »</b></i></p><p>Soit pour le triangle ABC représenté dans la figure ci-dessus, le théorème peut s''énoncer de la manière suivante :</p><p>« Si <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">A</span></span><span id="MJXc-Node-14" class="mjx-msubsup"><span class="mjx-base"><span id="MJXc-Node-15" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">B</span></span></span><span class="mjx-sup" style="font-size: 70.7%;vertical-align: 0.513em;"><span id="MJXc-Node-16" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">2</span></span></span></span><span id="MJXc-Node-17" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-18" class="mjx-mi MJXc-space3"><span class="mjx-char MJXc-TeX-math-I">A</span></span><span id="MJXc-Node-19" class="mjx-msubsup"><span class="mjx-base"><span id="MJXc-Node-20" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">C</span></span></span><span class="mjx-sup" style="font-size: 70.7%;vertical-align: 0.513em;"><span id="MJXc-Node-21" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">2</span></span></span></span><span id="MJXc-Node-22" class="mjx-mo MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">+</span></span><span id="MJXc-Node-23" class="mjx-mi MJXc-space2"><span class="mjx-char MJXc-TeX-math-I">B</span></span><span id="MJXc-Node-24" class="mjx-msubsup"><span class="mjx-base"><span id="MJXc-Node-25" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">C</span></span></span><span class="mjx-sup" style="font-size: 70.7%;vertical-align: 0.513em;"><span id="MJXc-Node-26" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">2</span></span></span></span></span></span><span class="MJX_Assistive_MathML">AB2=AC2+BC2</span></span> »</p><p>Sur base des notions apprises au cours, <b>démontre</b> la réciproque du théorème de Pythagore​</p>', true, '2017-07-24 11:09:07.705505+02', '2017-07-26 11:23:00.273795+02', true, 'submitted', 99, 252);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1197, NULL, true, '2017-07-27 15:52:13.451385+02', '2017-07-27 15:52:13.451413+02', true, 'adapted', 1208, 90);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1214, '<img src="/media/exercices/P2D-U1-A2A_02.PNG" />
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (838, '<p><img src="/media/exercices/TG6-U1-A2_03.PNG"/></p><p>La probabilité qu''un enfant soit atteint d''une pathologie cardiaque à la naissance est de 0,01 pour les filles et de 0,05 pour les garçons. </p><p>Supposons qu''il y ait autant de nouveaux-nés garçons que filles.</p><p><br/></p><p>Soit les événements suivants :</p><p><b><i>F :</i> </b><i>&#34;Le nouveau-né est une fille &#34;</i></p><p><i><b>G :</b> &#34;Le nouveau-né est un garçon&#34;</i></p><p><i><b>C:</b> &#34;Le nouveau-né est atteint d''une pathologie cardiaque&#34;</i></p><div><i><br/></i></div><div><b>Place </b>les données dans l''arbre ci-dessus (probabilités données au centième près) </div><p>Ensuite,<b> réponds</b> aux questions suivantes<br/></p><p><br/></p>', true, '2017-07-05 10:01:42.928031+02', '2017-07-24 11:36:51.778955+02', true, 'submitted', 99, 498);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (840, '<p>On prend au hasard 3 ampoules dans un lot de 18 ampoules dont 4 sont défectueuses.</p><p>Calcule la probabilité pour que... <i> (réponse à</i> \(10^{-4}\)<span class="mjx-chtml MJXc-processed" id="MathJax-Element-3-Frame" style="font-size: 120%;"><span class="mjx-math" id="MJXc-Node-11"><span class="mjx-mrow" id="MJXc-Node-12"><span class="mjx-msubsup" id="MJXc-Node-13"><span class="mjx-base"><span class="mjx-mn" id="MJXc-Node-14"><span class="mjx-char MJXc-TeX-main-R">10</span></span></span><span class="mjx-sup" style="font-size: 70.7%;vertical-align: 0.59em;"><span class="mjx-texatom" id="MJXc-Node-15"><span class="mjx-mrow" id="MJXc-Node-16"><span class="mjx-mo" id="MJXc-Node-17"><span class="mjx-char MJXc-TeX-main-R">−</span></span><span class="mjx-mn" id="MJXc-Node-18"><span class="mjx-char MJXc-TeX-main-R">4</span></span></span></span></span></span></span></span><span class="MJX_Assistive_MathML">10−4</span><span class="mjx-math" id="MJXc-Node-11"><span class="mjx-mrow" id="MJXc-Node-12" style="width: 2.72em;"><span class="mjx-mi" id="MJXc-Node-13"><span class="mjx-char MJXc-TeX-math-I">L</span></span><span class="mjx-mspace" id="MJXc-Node-14" style="width: 0px;height: 0px;"></span><span class="mjx-mpadded" id="MJXc-Node-15"><span class="mjx-block" style="width: 0px;"><span class="mjx-box" style="width: 0px;"><span class="mjx-mrow" id="MJXc-Node-16"><span class="mjx-texatom" id="MJXc-Node-17"><span class="mjx-mrow" id="MJXc-Node-18"><span class="mjx-mstyle" id="MJXc-Node-19" style="font-size: 80%;"><span class="mjx-mrow" id="MJXc-Node-20" style="font-size: 88.4%;"><span class="mjx-texatom" id="MJXc-Node-21"><span class="mjx-mrow" id="MJXc-Node-22"><span class="mjx-mi" id="MJXc-Node-23"><span class="mjx-char MJXc-TeX-math-I">A</span></span></span></span></span></span></span></span></span></span><span class="mjx-strut"></span></span></span><span class="mjx-mspace" id="MJXc-Node-24" style="width: 0px;height: 0px;"></span><span class="mjx-mi" id="MJXc-Node-25"><span class="mjx-char MJXc-TeX-math-I">T</span></span><span class="mjx-mspace" id="MJXc-Node-26" style="width: 0px;height: 0px;"></span><span class="mjx-mpadded" id="MJXc-Node-27"><span class="mjx-block" style="width: 0px;"><span class="mjx-box" style="width: 0px;"><span class="mjx-mrow" id="MJXc-Node-28"><span class="mjx-texatom" id="MJXc-Node-29"><span class="mjx-mrow" id="MJXc-Node-30"><span class="mjx-mi" id="MJXc-Node-31"><span class="mjx-char MJXc-TeX-math-I">E</span></span></span></span></span></span><span class="mjx-strut"></span></span></span><span class="mjx-mspace" id="MJXc-Node-32" style="width: 0px;height: 0px;"></span><span class="mjx-mi" id="MJXc-Node-33"><span class="mjx-char MJXc-TeX-math-I">X</span></span></span></span><span class="MJX_Assistive_MathML">LATEX</span></span><i> près)</i></p><p><br/></p>', true, '2017-07-05 10:20:53.434499+02', '2017-07-24 11:40:17.593546+02', true, 'submitted', 99, 498);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1090, '<img src="/media/exercices/T3-U2-A3_02.PNG" />
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1092, '<p>Sur base des informations fournies ci-dessous, donne l''expression analytique de la fonction correspondante. Plusieurs solutions sont possibles!</p><p><br/></p><p>1) \(AH \equiv y = -2\) et \(AV \equiv x = -1\)</p><p>2) \(AH \equiv y = 0\), \(AV_1 \equiv x = -1\) et \(AV_2 \equiv x = 1\)</p><p>3) \(AV \equiv x = 1\) et \(AO \equiv y = x - 2\)</p><p>4) \(AO \equiv y = x - 1\)</p>', true, '2017-07-24 12:23:28.14596+02', '2017-07-24 12:23:28.145994+02', false, 'submitted', 1207, 469);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1093, '<img src="/media/exercices/TG5-U3-A4_01.PNG" />
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1094, '<p>Soit la fonction \(y = 4\sin(3\pi x + C) + 5 \).</p>', true, '2017-07-24 13:50:40.024498+02', '2017-07-24 13:50:40.024537+02', true, 'submitted', 1207, 492);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1097, '<p>Calcule les extremums des fonctions trigonométriques suivantes. Donne toutes les valeurs comprises dans l''intervalle \( \left[0;2\pi \right] \)</p><p>Encode ta réponse sous la forme suivante : </p><p>\(\dfrac{a}{b}\pi\) où \(\dfrac{a}{b}\) est une fraction irréductible, qui peut donc se simplifier en un entier.</p><p><br/></p><p>Par exemple, si \(f(x) = \sin(x) \), les extremums sont donnés par \(x = \dfrac{1}{2} \pi + k\pi \). Tu encoderas donc toutes les valeurs comprises dans l''intervalle \( \left[0;2\pi \right] \) dans l''ordre croissant, c''est-à-dire :</p><p>\( \dfrac{1}{2}\pi\), \( \dfrac{3}{2}\pi\)</p><p><br/></p>', true, '2017-07-24 14:37:13.836942+02', '2017-07-24 14:37:13.836978+02', true, 'submitted', 1207, 492);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (862, '<p>L''être humain cligne plus de 10 000 fois par jour des yeux. Si un homme a une vie de 75 ans, <b>combien de fois aura-t-il cligné des yeux au cours de sa vie ?</b><br/></p>', true, '2017-07-06 17:49:19.011038+02', '2017-07-25 10:01:31.46421+02', true, 'submitted', 99, 162);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1257, '<p><img src="/media/exercices/Q22-U1-A2_01.PNG"/></p><p><b>Complète</b> le tableau de nombres ci-dessus à partir du graphique<br/></p>', true, '2017-07-31 10:21:24.390297+02', '2017-08-01 10:44:20.754513+02', true, 'submitted', 99, 563);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1372, '<p>Dans un repère orthonormé de l''espace \((O;\overrightarrow{i};\overrightarrow{j};\overrightarrow{k})\), représente les points de coordonnées suivantes :</p><ol><li>\(​(0,0,0)\)</li><li>\(​(0,1,0)\)</li><li>\(​(1,1,1)\)</li><ol style="font-size: 16px;"><ol style="font-size: 16px;"></ol></ol><li>\(​(-1,2,1)\)</li><ol style="font-size: 16px;"><ol style="font-size: 16px;"><ol style="font-size: 16px;"></ol></ol></ol></ol>', true, '2017-08-17 12:15:28.310831+02', '2017-08-17 12:15:28.310866+02', false, 'submitted', 1210, 537);
