INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1103, '<p>Une somme de 450 euros est partagée de manière peu équitable entre 4 enfants. Le premier enfant reçoit trois fois plus que le second, tandis que le troisième reçoit la moitié de ce que reçoit le quatrième. Le quatrième reçoit 100 euros de plus que le premier.</p>', true, '2017-07-24 19:51:47.630962+02', '2017-07-24 19:51:47.630996+02', true, 'submitted', 1207, 288);
