INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1108, '<p>Donne la limite des suites suivantes lorsque n tend vers \( + \infty \)<br/></p>', true, '2017-07-25 10:02:14.367045+02', '2017-07-25 10:02:14.367076+02', true, 'submitted', 99, 451);
