INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1102, '<p>Lorsqu''on additionne les âges d''Alexandre, Nicolas et Oscar, ils ont en tout 19 ans. Alexandre a 2 ans de plus que Nicolas et Oscar a 3 ans de moins qu''Alexandre. </p>', true, '2017-07-24 19:24:14.632942+02', '2017-08-08 09:42:04.861832+02', true, 'submitted', 1207, 287);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1111, '<p>Soient les quatre fonctions suivantes :</p><p>\( f(x) = x + 1 \)</p><p>\( g(x) = -4x + \dfrac{7}{2} \)</p><p>\( h(x) = \dfrac{5}{3}x -2 \)</p><p>\( p(x) = 6 \)</p><p>Détermine algébriquement l''intersection entre les fonctions suivantes. Exprime ta réponse sous la forme \( \left(x, y \right) \) où \(x\) et \(y\) sont des fractions irréductibles ou des entiers. Par exemple, tu encoderas \( \left( \dfrac{2}{3}, 4 \right) \)</p>', true, '2017-07-25 10:39:50.062951+02', '2017-07-25 10:39:50.062979+02', true, 'submitted', 1207, 285);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1113, '<p>Oscar souhaite mettre un parterre de fleurs dans son jardin. Il demande au jardinier de planter un parterre de fleurs d''une superficie de \(8\) \(m^2\).</p>', true, '2017-07-25 11:21:05.457511+02', '2017-07-25 11:21:05.457546+02', true, 'submitted', 1207, 334);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1117, '<p><b>Calcule </b>les sommes suivantes<br/><i>Arrondis tes réponses à deux décimales près lorsque ce ne sont pas des entiers.</i><br/></p>', true, '2017-07-25 11:56:05.990557+02', '2017-07-25 11:56:05.990603+02', true, 'submitted', 99, 452);
