INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1230, '<p><b>Construis </b>dans un repère orthonormé le graphique de la fonction <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">f</span></span><span id="MJXc-Node-14" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-15" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-16" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span><span id="MJXc-Node-17" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-18" class="mjx-mfrac MJXc-space3"><span class="mjx-box MJXc-stacked" style="width: 0.495em;"><span class="mjx-numerator" style="font-size: 70.7%;width: 0.7em;"><span id="MJXc-Node-19" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">3</span></span></span><span class="mjx-denominator" style="font-size: 70.7%;width: 0.7em;"><span id="MJXc-Node-20" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">4</span></span></span><span style="width: 0.495em;" class="mjx-line"></span></span><span style="height: 1.353em;vertical-align: -0.423em;" class="mjx-vsize"></span></span><span id="MJXc-Node-21" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-22" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-23" class="mjx-mo MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">+</span></span><span id="MJXc-Node-24" class="mjx-mn MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">4</span></span><span id="MJXc-Node-25" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span><span id="MJXc-Node-26" class="mjx-mo MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">−</span></span><span id="MJXc-Node-27" class="mjx-mfrac MJXc-space2"><span class="mjx-box MJXc-stacked" style="width: 0.495em;"><span class="mjx-numerator" style="font-size: 70.7%;width: 0.7em;"><span id="MJXc-Node-28" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">1</span></span></span><span class="mjx-denominator" style="font-size: 70.7%;width: 0.7em;"><span id="MJXc-Node-29" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">2</span></span></span><span style="width: 0.495em;" class="mjx-line"></span></span><span style="height: 1.331em;vertical-align: -0.415em;" class="mjx-vsize"></span></span><span id="MJXc-Node-30" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-31" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-32" class="mjx-mo MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">−</span></span><span id="MJXc-Node-33" class="mjx-mn MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">2</span></span><span id="MJXc-Node-34" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span></span></span><span class="MJX_Assistive_MathML">f(x)=34(x+4)−12(x−2)</span></span><br/></p>', true, '2017-07-28 11:26:55.199335+02', '2017-08-01 10:31:55.720614+02', true, 'submitted', 99, 201);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1119, '<img src="/media/exercices/T4-U5-A3A_01.PNG" />
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1120, '<p>Soit la fonction \(f(x) = 3x^2 + 6x - 8\). Réponds aux questions suivantes.</p>', true, '2017-07-25 13:56:17.114542+02', '2017-07-25 13:56:17.11457+02', true, 'submitted', 1207, 349);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1121, '<p>Soit la fonction \(f(x) = 3x^2 -12x + 15\). Dessine le graphique de celle-ci.</p><p>Pour construire le graphique de cette expression analytique, il est plus facile de réécrire \(f(x)\) sous la forme \(f(x) = a(x \pm b)^2 \pm c \), en utilisant la factorisation (en carrés parfaits). Ainsi, tu pourras facilement effectuer des opérations élémentaires sur \(x^2\) pour finalement construire \(f(x)\). </p>', true, '2017-07-25 14:34:36.076578+02', '2017-07-25 14:34:36.076617+02', true, 'submitted', 1207, 348);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1122, '<p>Parmi les suites suivantes,<b> identifie</b> si la suite :<br/>- est une suite arithmétique<br/>- est une suite géométrique<br/>- n''est pas une suite<br/><b>Donne</b> ensuite, s''il s''agit bien d''une suite arithmétique ou géométrique, la raison de cette dernière. <br/><i>(S''il ne s''agit pas d''une des 2 suites, met un 0)</i><br/></p>', true, '2017-07-25 14:42:21.755356+02', '2017-07-26 11:46:21.480146+02', true, 'submitted', 99, 440);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1123, '<p><b>Détermine</b> la primitive de ces fonctions de base ! (en considérant la constante d''intégration nulle)<br/></p>', true, '2017-07-25 15:00:23.902358+02', '2017-07-25 15:07:13.070559+02', true, 'submitted', 99, 673);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (985, '<p>Soit <b>S</b> défini comme le succès et <b>p(S)</b> sa probabilité.</p><p>Pour chacune des situations suivant, <b>calcule</b> la probabilité de succès <b>p(S)</b><br/></p>', true, '2017-07-18 10:45:48.946024+02', '2017-07-26 10:05:11.041488+02', true, 'submitted', 99, 506);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1255, '<p><img src="/media/exercices/P2D-U1-A3_02.PNG"/></p><p><b>Complète</b> le tableau de nombres ci-dessus à partir du graphique.</p>', true, '2017-07-31 10:10:47.133248+02', '2017-08-01 10:42:47.119164+02', true, 'submitted', 99, 154);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1129, '<p>Soit les fonctions \(f(x)=e^x\) et \(g(x) = ln(x)+e\)<br/></p><p><b>Compare</b> les croissances de ces 2 fonctions sur le domaine \(R_{0}^{+}\)<br/></p>', true, '2017-07-25 16:35:37.467034+02', '2017-07-25 16:39:01.746969+02', true, 'submitted', 99, 522);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1124, '<p>Réponds aux questions suivantes. </p><p>Détermine l''expression analytique \(f(x) = ax^2 + 3x + c \) pour qu''elle réponde aux conditions suivantes: le polynôme admet un minimum en \( x = 3 \) et l''ordonnée à l''origine vaut 2. Encode-la comme suit : \(f(x) = ... \)<br/></p>', true, '2017-07-25 15:16:27.339578+02', '2017-07-25 15:16:27.339606+02', true, 'submitted', 1207, 350);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1125, '<p><b>Détermine</b> la primitive de ces fonctions de base ! (en considérant la constante d''intégration nulle)<br/></p>', true, '2017-07-25 15:16:54.181098+02', '2017-07-25 15:16:54.181127+02', true, 'submitted', 99, 673);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1126, '<p>Soit les fonctions suivantes :</p><p>\( \bullet \) \(f_1(x) = e^x \), \(f_2(x) = e^{2x} \), \(f_3(x) = e^{3x} \)</p><p>\( \bullet \) \(g_1(x) = ln(x) \), \(g_2(x) = ln(2x) \), \(g_3(x) = ln(3x) \)</p><p>\( \bullet \) \(h_1(x) = x^{-2} \), \(h_2(x) = (2x)^{-2} \), \(h_3(x) = (3x)^{-2} \)</p><p><br/></p><p>Compare les croissances de ces fonctions sur le domaine \( R_{0}^{+} \)<br/></p>', true, '2017-07-25 15:51:34.021755+02', '2017-07-25 15:51:34.021785+02', true, 'submitted', 99, 522);
