INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1130, '<p>Soit les fonctions \(f(x)=x^3\) et \(g(x) = x^{-3}\)<br/><b>Compare</b> les croissances de ces 2 fonctions sur le domaine \(R_{0}^{+}\)<br/></p>', true, '2017-07-25 16:35:46.592311+02', '2017-07-25 16:35:46.592339+02', true, 'submitted', 99, 522);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1127, '<p><img src="/media/exercices/T4-U5-T2_01.PNG"/></p><p>Soit un joli hublot dont le rayon est connu. Le fabricant, pour une question de design, souhaite que la surface de la partie en cuivre soit égale à la surface de la vitre. Que vaut la largeur de &#34;l''anneau&#34; (<span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span></span></span><span class="MJX_Assistive_MathML">x</span></span>) dans ce cas?</p>', true, '2017-07-25 15:56:32.137675+02', '2017-08-08 09:51:51.443898+02', true, 'submitted', 1207, 354);
