INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1131, '<p>Soit la fonction \( f(x) = \dfrac{8}{x^2-2x-5} \)</p><p><br/></p><p>Sur base des informations récoltées dans chaque sous-question, esquisse le graphique de la fonction.<br/></p>', true, '2017-07-25 16:52:58.777164+02', '2017-07-25 16:52:58.777191+02', true, 'submitted', 1207, 475);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (884, '<p>Voici 4 chiffres : 7 - 5 - 0 - 4.</p><p>Place ces 4 chiffres dans le bon ordre pour que chaque nombre ainsi créé soit divisible comme il convient.</p>', true, '2017-07-07 12:17:44.678853+02', '2017-07-26 08:52:56.979672+02', true, 'submitted', 1220, 12);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (970, '<p>Calcule l''intégrale suivante en utilisant un changement de variable.<br/></p>', true, '2017-07-17 14:32:04.928546+02', '2017-07-26 09:54:16.538356+02', true, 'submitted', 99, 676);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (972, '<p>Calcule l''intégrale suivante en effectuant les 2 changements de variables suivants :</p><p><span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">⋅</span></span><span id="MJXc-Node-14" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">u</span></span><span id="MJXc-Node-15" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-16" class="mjx-mi MJXc-space3"><span class="mjx-char MJXc-TeX-math-I">π</span></span><span id="MJXc-Node-17" class="mjx-mo MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">−</span></span><span id="MJXc-Node-18" class="mjx-mi MJXc-space2"><span class="mjx-char MJXc-TeX-math-I">x</span></span></span></span><span class="MJX_Assistive_MathML">⋅u=π−x</span></span> (Règle de Bioche)<br/></p>', true, '2017-07-17 14:39:44.98493+02', '2017-07-26 09:55:47.076333+02', true, 'submitted', 99, 676);
