INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1045, '<p><img src="/media/exercices/T3-U1-T1_01.PNG"/></p><p><b>Démontre</b> la propriété suivante :</p><p>« Dans un cercle, si un angle au centre et un angle inscrit interceptent le même arc, alors la mesure de l''angle au centre est le double de celle de l''angle inscrit. »<br/></p>', true, '2017-07-20 11:05:36.443554+02', '2017-07-26 10:58:13.645781+02', true, 'submitted', 99, 245);
