INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1081, '<p>Soit un triangle ABC tel que <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-munderover"><span class="mjx-stack"><span class="mjx-over" style="font-size: 70.7%;height: 0.096em;"><span id="MJXc-Node-17" class="mjx-mo" style="vertical-align: top;"><span class="mjx-delim-h"><span class="mjx-char MJXc-TeX-main-R">¯</span><span class="mjx-char MJXc-TeX-main-R">¯¯¯¯¯¯</span><span class="mjx-char MJXc-TeX-main-R">¯</span></span></span></span><span class="mjx-op"><span id="MJXc-Node-14" class="mjx-mrow"><span id="MJXc-Node-15" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">A</span></span><span id="MJXc-Node-16" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">B</span></span></span></span></span></span><span id="MJXc-Node-18" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-19" class="mjx-mn MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">50</span></span><span id="MJXc-Node-20" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">m</span></span><span id="MJXc-Node-21" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">m</span></span><span id="MJXc-Node-22" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">,</span></span><span id="MJXc-Node-23" class="mjx-munderover MJXc-space1"><span class="mjx-stack"><span class="mjx-over" style="font-size: 70.7%;height: 0.096em;"><span id="MJXc-Node-27" class="mjx-mo" style="vertical-align: top;"><span class="mjx-delim-h"><span class="mjx-char MJXc-TeX-main-R">¯</span><span class="mjx-char MJXc-TeX-main-R">¯¯¯¯¯¯</span><span class="mjx-char MJXc-TeX-main-R">¯</span></span></span></span><span class="mjx-op"><span id="MJXc-Node-24" class="mjx-mrow"><span id="MJXc-Node-25" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">B</span></span><span id="MJXc-Node-26" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">C</span></span></span></span></span></span><span id="MJXc-Node-28" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-29" class="mjx-mn MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">12</span></span><span id="MJXc-Node-30" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">c</span></span><span id="MJXc-Node-31" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">m</span></span><span id="MJXc-Node-32" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">,</span></span><span id="MJXc-Node-33" class="mjx-munderover MJXc-space1"><span class="mjx-stack"><span class="mjx-over" style="font-size: 70.7%;height: 0.096em;"><span id="MJXc-Node-37" class="mjx-mo" style="vertical-align: top;"><span class="mjx-delim-h"><span class="mjx-char MJXc-TeX-main-R">¯</span><span class="mjx-char MJXc-TeX-main-R">¯¯¯¯¯¯</span><span class="mjx-char MJXc-TeX-main-R">¯</span></span></span></span><span class="mjx-op"><span id="MJXc-Node-34" class="mjx-mrow"><span id="MJXc-Node-35" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">A</span></span><span id="MJXc-Node-36" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">C</span></span></span></span></span></span><span id="MJXc-Node-38" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-39" class="mjx-mn MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">13</span></span><span id="MJXc-Node-40" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">c</span></span><span id="MJXc-Node-41" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">m</span></span></span></span><span class="MJX_Assistive_MathML">AB¯=50mm,BC¯=12cm,AC¯=13cm</span></span>.</p><p><b>Vérifie</b> que le triangle est rectangle et <b>précise</b> son hypoténuse.<br/></p>', true, '2017-07-24 10:13:10.011617+02', '2017-07-26 11:12:14.835078+02', true, 'submitted', 99, 258);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1135, '<p>Pour les situations suivantes, indique quelle loi de probabilité est la plus adaptée. </p><p><br/></p><p>1) Oscar n''a pas un bon sens de l''orientation. Sa soeur a estimé qu''il ne se trompe pas de chemin avec une probabilité de 45%. Aujourd''hui, Oscar doit d''abord aller conduire sa soeur à son camp guides, puis il effectuera un deuxième trajet dans le courant de la journée pour aller rejoindre des amis. Quelle est la probabilité qu''il ne se trompe pas de chemin pour aller voir ses copains?</p><p><br/></p><p>2) Un sac de billes contient 9 billes : 5 rouges et 4 blanches. Oscar tire successivement 5 billes, en les replaçant systématiquement dans le sac avant chaque tirage de bille. Quelle est la probabilité qu''il pioche 3 boules rouges et 2 boules blanches? </p><p><br/></p><p>3) Oscar a dans son portefeuille une pièce mal équilibrée : la probabilité qu''elle tombe sur pile est de \(\dfrac{2}{5}\). Il jette sa pièce 100 fois. Quelle est la probabilité qu''il tombe 68 fois sur face?</p><p><br/></p><p>4) Oscar lit dans le journal que 10 % de la population fait partie du groupe sanguin AB-. Il se demande qu''elle est la probabilité que parmi 10 personnes, trois d''entre elles soient du groupe AB-.</p>', true, '2017-07-26 10:04:01.274308+02', '2017-07-26 10:10:10.099468+02', true, 'submitted', 1207, 502);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (989, '<p>Dans le cadre scolaire, Oscar a effectué un petit stage dans la célèbre firme de production laitière &#34;Lait pour tous&#34;. Celle-ci utilise une certaine race de vaches laitières pour leur production de lait (annuelle en litres). Oscar décide de modéliser cette production laitière par une variable aléatoire à densité <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">X</span></span></span></span><span class="MJX_Assistive_MathML">X</span></span>. </p><p><i>La fonction g désigne la fonction de densité de cette loi normale.</i></p><p>Il rend visite à un éleveur faisant naître des vaches de cette race. Dans le but de mieux gérer au plus près son quota laitier (en déterminant la taille optimale de son troupeau), ce dernier souhaite disposer de certaines probabilités.<br/></p><p><br/></p><p style="text-align: right;">Source : Académie de Toulouse​</p>', true, '2017-07-18 11:28:58.646919+02', '2017-07-26 10:13:43.778365+02', true, 'submitted', 99, 507);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1136, '<p>Identifie les paramètres de la loi binomiale pour les situations suivantes.</p><p><br/>1) Oscar joue aux fléchettes. La probabilité qu''il vise parfaitement au centre est d''\(\dfrac{1}{20}\). Supposons qu''il jette dix fois, quelle est la probabilité qu''il atteigne le centre 3 fois?</p><p><br/></p><p>2) Oscar va à son examen d''histoire. On lui pose 10 questions Vrai ou Faux mais il n''a pas étudié, il répond donc au hasard. Quelle est la probabilité qu''il obtienne au moins la moitié des points?</p>', true, '2017-07-26 10:14:22.795106+02', '2017-07-26 10:14:22.795151+02', true, 'submitted', 1207, 502);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1001, '<p>Soit <b>S</b> définit comme le succès et <b>p(S)</b> comme sa probabilité.</p><p>Pour chaque situation, <b>calcule</b> la probabilité de succès de celle-ci <b>p(S)</b><br/></p>', true, '2017-07-18 15:38:20.829068+02', '2017-07-26 10:20:50.053748+02', true, 'submitted', 99, 505);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1002, '<p>Des bouteilles de 1 litre d''eau sont remplies par une embouteilleuse. Malheureusement ces bouteilles ne sont pas remplies jusqu''à 1 litre pile (personne n''est parfait...). Il existe un écart-type qu''on ne peut pas modifier mais en revanche, il y a toujours moyen de régler le contenu moyen d''une bouteille.<br/></p><p>Constat : Ceci suit une loi normale dont l''écart-type est de 1,5 cl.</p><p>Souhait : Au moins 95% des bouteilles contiennent 99 cl ou plus.</p><p><br/></p><p><b>Sur quelle contenance régler l''embouteilleuse ?</b><br/></p>', true, '2017-07-18 15:56:28.370594+02', '2017-07-26 10:24:33.537255+02', true, 'submitted', 99, 505);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1042, '<p>Soit ABC un triangle isocèle.</p><p>On sait que <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-munderover"><span class="mjx-stack"><span class="mjx-over" style="font-size: 70.7%;height: 0.096em;"><span id="MJXc-Node-17" class="mjx-mo" style="vertical-align: top;"><span class="mjx-delim-h"><span class="mjx-char MJXc-TeX-main-R">¯</span><span class="mjx-char MJXc-TeX-main-R">¯¯¯¯¯¯</span><span class="mjx-char MJXc-TeX-main-R">¯</span></span></span></span><span class="mjx-op"><span id="MJXc-Node-14" class="mjx-mrow"><span id="MJXc-Node-15" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">A</span></span><span id="MJXc-Node-16" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">B</span></span></span></span></span></span><span id="MJXc-Node-18" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-19" class="mjx-munderover MJXc-space3"><span class="mjx-stack"><span class="mjx-over" style="font-size: 70.7%;height: 0.096em;"><span id="MJXc-Node-23" class="mjx-mo" style="vertical-align: top;"><span class="mjx-delim-h"><span class="mjx-char MJXc-TeX-main-R">¯</span><span class="mjx-char MJXc-TeX-main-R">¯¯¯¯¯¯</span><span class="mjx-char MJXc-TeX-main-R">¯</span></span></span></span><span class="mjx-op"><span id="MJXc-Node-20" class="mjx-mrow"><span id="MJXc-Node-21" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">A</span></span><span id="MJXc-Node-22" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">C</span></span></span></span></span></span><span id="MJXc-Node-24" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-25" class="mjx-mn MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">2</span></span><span id="MJXc-Node-26" class="mjx-munderover"><span class="mjx-stack"><span class="mjx-over" style="font-size: 70.7%;height: 0.096em;"><span id="MJXc-Node-30" class="mjx-mo" style="vertical-align: top;"><span class="mjx-delim-h"><span class="mjx-char MJXc-TeX-main-R">¯</span><span class="mjx-char MJXc-TeX-main-R">¯¯¯¯¯¯</span><span class="mjx-char MJXc-TeX-main-R">¯</span></span></span></span><span class="mjx-op"><span id="MJXc-Node-27" class="mjx-mrow"><span id="MJXc-Node-28" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">B</span></span><span id="MJXc-Node-29" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">C</span></span></span></span></span></span></span></span><span class="MJX_Assistive_MathML">AB¯=AC¯=2BC¯</span></span> et que D et E sont les milieux respectifs de [AB] et de [AC].</p><p>Sur base de ces informations,<b> démontre</b> que les triangles ADC et AEB sont isométriques.<br/></p>', true, '2017-07-20 10:02:54.485796+02', '2017-07-26 10:52:03.924663+02', true, 'submitted', 99, 246);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1137, '<img src="/media/exercices/TG6-U2-C2_01.PNG" />
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1044, '<p><img src="/media/exercices/T3-U1-T4_01.PNG"/></p><div><p>Un bon matin, Oscar décide d''aller visiter le parc se situant dans sa région. L''entrée du parc se situe au point E. Sachant qu''il n''a pas beaucoup de temps devant lui, car il doit par la suite aller rendre visite à sa grand-mère, il décide de prendre le chemin le plus court. Il y a 2 chemins existant permettant de visiter le parc :</p><p>-Le premier consiste à partir du point E, à se diriger vers le point C pour se rendre ensuite au point B et enfin revenir au point de départ E.</p><p>-Le second consiste à partir du point E, à se diriger vers le point A pour se rendre ensuite au point F. Du point F se rendre au point B pour enfin revenir au point de départ E.</p><p>Oscar ne sachant pas lequel choisir, il fait appel à un employé travaillant au parc. Celui-ci lui informe qu''il n''existe pas un chemin plus court que l''autre.</p><p>Oscar, assez perplexe, décide de se convaincre lui-même que ce que l''employé lui a dit est vrai. N''étant pas très futé, Oscar fait appel à vos connaissance en math pour l''aider.</p><p><u><i>Hypothèse :</i></u></p><p><i>- ABCD est un carré</i></p><p><i>-Les segments de droites [FB] et [CE] sont perpendiculaire</i></p><p><br/></p><p>1) Démontre que les angles <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-texatom"><span id="MJXc-Node-14" class="mjx-mrow"><span id="MJXc-Node-15" class="mjx-munderover"><span class="mjx-stack"><span class="mjx-over" style="height: 0.334em;"><span id="MJXc-Node-20" class="mjx-mo" style="vertical-align: top;"><span class="mjx-char MJXc-TeX-size4-R">ˆ</span></span></span><span class="mjx-op"><span id="MJXc-Node-16" class="mjx-mrow"><span id="MJXc-Node-17" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">B</span></span><span id="MJXc-Node-18" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">C</span></span><span id="MJXc-Node-19" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">E</span></span></span></span></span></span></span></span></span></span><span class="MJX_Assistive_MathML">BCE^</span></span>​</p></div>', true, '2017-07-20 10:39:00.500593+02', '2017-07-26 10:56:27.961153+02', true, 'submitted', 99, 248);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1140, '<img src="/media/exercices/TG5-U4-T3_04.PNG" />
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1060, '<p><img src="/media/exercices/T4-U4-A4B_02.PNG"/></p><p>Voici le graphique de f dont l''expression analytique est : <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">f</span></span><span id="MJXc-Node-14" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-15" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-16" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span><span id="MJXc-Node-17" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-18" class="mjx-mfrac MJXc-space3"><span class="mjx-box MJXc-stacked" style="width: 0.495em;"><span class="mjx-numerator" style="font-size: 70.7%;width: 0.7em;"><span id="MJXc-Node-19" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">1</span></span></span><span class="mjx-denominator" style="font-size: 70.7%;width: 0.7em;"><span id="MJXc-Node-20" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">2</span></span></span><span style="width: 0.495em;" class="mjx-line"></span></span><span style="height: 1.331em;vertical-align: -0.415em;" class="mjx-vsize"></span></span><span id="MJXc-Node-21" class="mjx-msubsup"><span class="mjx-base"><span id="MJXc-Node-22" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span></span><span class="mjx-sup" style="font-size: 70.7%;vertical-align: 0.513em;"><span id="MJXc-Node-23" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">2</span></span></span></span><span id="MJXc-Node-24" class="mjx-mo MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">+</span></span><span id="MJXc-Node-25" class="mjx-mfrac MJXc-space2"><span class="mjx-box MJXc-stacked" style="width: 0.495em;"><span class="mjx-numerator" style="font-size: 70.7%;width: 0.7em;"><span id="MJXc-Node-26" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">5</span></span></span><span class="mjx-denominator" style="font-size: 70.7%;width: 0.7em;"><span id="MJXc-Node-27" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">2</span></span></span><span style="width: 0.495em;" class="mjx-line"></span></span><span style="height: 1.346em;vertical-align: -0.415em;" class="mjx-vsize"></span></span></span></span><span class="MJX_Assistive_MathML">f(x)=12x2+52</span></span></p><p><b>Trouve</b> les différentes valeurs de f sans calculer !</p><p><i>Les réponses doivent être données de manière approximative !</i><br/></p>', true, '2017-07-20 14:55:01.444679+02', '2017-07-26 11:03:12.629745+02', true, 'submitted', 99, 668);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1234, '<p>Calcule les pourcentages suivants. Arrondis ta réponse à l''unité près.</p>', true, '2017-07-28 11:54:55.593281+02', '2017-07-28 11:54:55.59331+02', true, 'submitted', 1207, 188);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1226, '<p>Soient les 3 fonctions ci-dessous.</p><p><br/></p><p>\(f(x) = -3x + 2 \)</p><p>\(g(x) = \dfrac{4}{3}x - 1 \)</p><p>\(h(x) = \dfrac{5}{2} \)</p><p>\(i(x) = 2x - \dfrac{3}{4} \)</p><p><br/></p><p>Détermine algébriquement l''intersection entre les fonctions suivantes. Exprime ta réponse sous forme d''entier ou de fraction irréductible.</p>', true, '2017-07-28 10:51:57.461308+02', '2017-07-28 10:53:37.477463+02', true, 'submitted', 1207, 213);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1084, '<p><img src="/media/exercices/T3-U2-C1A_01.PNG"/></p><p>Le théorème de Pythagore s''énonce ainsi : </p><p><i><b>« Dans un triangle rectangle, le carré de la longueur de l’hypoténuse est égal à la somme des carrés des longueurs des côtés de l’angle droit »</b></i></p><p>Soit pour le triangle ABC représenté dans la figure ci-dessus, le théorème peut s''énoncer de la manière suivante :</p><p>« Si <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">A</span></span><span id="MJXc-Node-14" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">B</span></span><span id="MJXc-Node-15" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">C</span></span></span></span><span class="MJX_Assistive_MathML">ABC</span></span> »<br/></p><p>Sur base des notions apprises au cours, <b>démontre</b> le théorème de Pythagore.<br/></p>', true, '2017-07-24 10:58:47.100205+02', '2017-07-26 11:20:38.71191+02', true, 'submitted', 99, 251);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1139, '<p>Oscar jette 100 fois un dé parfaitement équilibré. Il s''intéresse au nombre de fois qu''il lance un \(6\).</p>', true, '2017-07-26 11:16:33.844794+02', '2017-07-26 11:32:47.958995+02', true, 'submitted', 1207, 512);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1145, '<p>2% de la population du pays X est gaucher. Le pays X est décomposé en communes d''habitants. Dans chaque commune, il y a 100 habitants. Quelle est la probabilité que lorsqu''on choisit une commune au hasard</p>', true, '2017-07-26 12:09:04.388078+02', '2017-07-26 12:09:35.193904+02', true, 'submitted', 1207, 511);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1146, '<p>En supposant qu''Oscar doive tirer 5 cartes au hasard <i>avec replacement</i> dans un jeu de 52 cartes, quelle est la probabilité</p>', true, '2017-07-26 12:21:20.99584+02', '2017-07-26 12:21:20.995915+02', true, 'submitted', 1207, 511);
