INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1088, '<p><img src="/media/exercices/T3-U2-A3_01.PNG"/></p><p>Dans un repère orthonormé ci dessus, on place les points suivants :</p><p><span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">A</span></span><span id="MJXc-Node-14" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">:</span></span><span id="MJXc-Node-15" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-16" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">4</span></span><span id="MJXc-Node-17" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">,</span></span><span id="MJXc-Node-18" class="mjx-mn MJXc-space1"><span class="mjx-char MJXc-TeX-main-R">5</span></span><span id="MJXc-Node-19" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span></span></span><span class="MJX_Assistive_MathML">A:(4,5)</span></span>.</p><p><b>Calcule</b> les distances suivantes :<br/></p>', true, '2017-07-24 11:34:24.714207+02', '2017-07-26 11:24:48.644809+02', true, 'submitted', 99, 260);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1095, '<p><img src="/media/exercices/T3-U2-C6_01.PNG"/></p><p>Soit le triangle IJK tel que <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-texatom"><span id="MJXc-Node-14" class="mjx-mrow"><span id="MJXc-Node-15" class="mjx-munderover"><span class="mjx-stack"><span class="mjx-over" style="height: 0.334em;"><span id="MJXc-Node-20" class="mjx-mo" style="vertical-align: top;"><span class="mjx-char MJXc-TeX-size4-R">ˆ</span></span></span><span class="mjx-op"><span id="MJXc-Node-16" class="mjx-mrow"><span id="MJXc-Node-17" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">I</span></span><span id="MJXc-Node-18" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">J</span></span><span id="MJXc-Node-19" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">K</span></span></span></span></span></span></span></span><span id="MJXc-Node-21" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-22" class="mjx-mn MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">90</span></span><span id="MJXc-Node-23" class="mjx-texatom"><span id="MJXc-Node-24" class="mjx-mrow"><span id="MJXc-Node-25" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">°</span></span></span></span><span id="MJXc-Node-26" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">,</span></span><span id="MJXc-Node-27" class="mjx-texatom MJXc-space1"><span id="MJXc-Node-28" class="mjx-mrow"><span id="MJXc-Node-29" class="mjx-munderover"><span class="mjx-stack"><span class="mjx-over" style="height: 0.334em;"><span id="MJXc-Node-34" class="mjx-mo" style="vertical-align: top;"><span class="mjx-char MJXc-TeX-size4-R">ˆ</span></span></span><span class="mjx-op"><span id="MJXc-Node-30" class="mjx-mrow"><span id="MJXc-Node-31" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">J</span></span><span id="MJXc-Node-32" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">I</span></span><span id="MJXc-Node-33" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">K</span></span></span></span></span></span></span></span><span id="MJXc-Node-35" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-36" class="mjx-texatom MJXc-space3"><span id="MJXc-Node-37" class="mjx-mrow"><span id="MJXc-Node-38" class="mjx-munderover"><span class="mjx-stack"><span class="mjx-over" style="height: 0.334em;"><span id="MJXc-Node-43" class="mjx-mo" style="vertical-align: top;"><span class="mjx-char MJXc-TeX-size4-R">ˆ</span></span></span><span class="mjx-op"><span id="MJXc-Node-39" class="mjx-mrow"><span id="MJXc-Node-40" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">J</span></span><span id="MJXc-Node-41" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">K</span></span><span id="MJXc-Node-42" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">I</span></span></span></span></span></span></span></span><span id="MJXc-Node-44" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-45" class="mjx-mn MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">45</span></span><span id="MJXc-Node-46" class="mjx-texatom"><span id="MJXc-Node-47" class="mjx-mrow"><span id="MJXc-Node-48" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">°</span></span></span></span></span></span><span class="MJX_Assistive_MathML">IJK^=90°,JIK^=JKI^=45°</span></span>.</p><p><b>Détermine</b> les valeurs suivantes</p>', true, '2017-07-24 14:17:24.405749+02', '2017-07-26 11:27:13.92419+02', true, 'submitted', 99, 257);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1096, '<p><img src="/media/exercices/T3-U2-C6_02.PNG"/></p><p>Soit le triangle rectangle RST tel que <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-texatom"><span id="MJXc-Node-14" class="mjx-mrow"><span id="MJXc-Node-15" class="mjx-munderover"><span class="mjx-stack"><span class="mjx-over" style="height: 0.334em;"><span id="MJXc-Node-20" class="mjx-mo" style="vertical-align: top;"><span class="mjx-char MJXc-TeX-size4-R">ˆ</span></span></span><span class="mjx-op"><span id="MJXc-Node-16" class="mjx-mrow"><span id="MJXc-Node-17" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">R</span></span><span id="MJXc-Node-18" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">S</span></span><span id="MJXc-Node-19" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">T</span></span></span></span></span></span></span></span><span id="MJXc-Node-21" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-22" class="mjx-mn MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">90</span></span><span id="MJXc-Node-23" class="mjx-texatom"><span id="MJXc-Node-24" class="mjx-mrow"><span id="MJXc-Node-25" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">°</span></span></span></span><span id="MJXc-Node-26" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">,</span></span><span id="MJXc-Node-27" class="mjx-texatom MJXc-space1"><span id="MJXc-Node-28" class="mjx-mrow"><span id="MJXc-Node-29" class="mjx-munderover"><span class="mjx-stack"><span class="mjx-over" style="height: 0.334em;"><span id="MJXc-Node-34" class="mjx-mo" style="vertical-align: top;"><span class="mjx-char MJXc-TeX-size4-R">ˆ</span></span></span><span class="mjx-op"><span id="MJXc-Node-30" class="mjx-mrow"><span id="MJXc-Node-31" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">S</span></span><span id="MJXc-Node-32" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">R</span></span><span id="MJXc-Node-33" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">T</span></span></span></span></span></span></span></span><span id="MJXc-Node-35" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-36" class="mjx-mn MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">30</span></span><span id="MJXc-Node-37" class="mjx-texatom"><span id="MJXc-Node-38" class="mjx-mrow"><span id="MJXc-Node-39" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">°</span></span></span></span><span id="MJXc-Node-40" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">,</span></span><span id="MJXc-Node-41" class="mjx-texatom MJXc-space1"><span id="MJXc-Node-42" class="mjx-mrow"><span id="MJXc-Node-43" class="mjx-munderover"><span class="mjx-stack"><span class="mjx-over" style="height: 0.334em;"><span id="MJXc-Node-48" class="mjx-mo" style="vertical-align: top;"><span class="mjx-char MJXc-TeX-size4-R">ˆ</span></span></span><span class="mjx-op"><span id="MJXc-Node-44" class="mjx-mrow"><span id="MJXc-Node-45" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">S</span></span><span id="MJXc-Node-46" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">T</span></span><span id="MJXc-Node-47" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">R</span></span></span></span></span></span></span></span><span id="MJXc-Node-49" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-50" class="mjx-mn MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">60</span></span><span id="MJXc-Node-51" class="mjx-texatom"><span id="MJXc-Node-52" class="mjx-mrow"><span id="MJXc-Node-53" class="mjx-mo"><span class="mjx-char