INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1106, '<p>Représente sur un graphique la suite <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-msubsup"><span class="mjx-base"><span id="MJXc-Node-14" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">u</span></span></span><span class="mjx-sub" style="font-size: 70.7%;vertical-align: -0.212em;"><span id="MJXc-Node-15" class="mjx-texatom"><span id="MJXc-Node-16" class="mjx-mrow"><span id="MJXc-Node-17" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">n</span></span><span id="MJXc-Node-18" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">+</span></span><span id="MJXc-Node-19" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">1</span></span></span></span></span></span><span id="MJXc-Node-20" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-21" class="mjx-msqrt MJXc-space3"><span class="mjx-box"><span class="mjx-surd"><span class="mjx-char MJXc-TeX-main-R">√</span></span><span class="mjx-box"><span id="MJXc-Node-22" class="mjx-mrow"><span id="MJXc-Node-23" class="mjx-msubsup"><span class="mjx-base"><span id="MJXc-Node-24" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">u</span></span></span><span class="mjx-sub" style="font-size: 70.7%;vertical-align: -0.212em;"><span id="MJXc-Node-25" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">n</span></span></span></span><span id="MJXc-Node-26" class="mjx-mo MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">+</span></span><span id="MJXc-Node-27" class="mjx-mn MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">2</span></span></span></span></span></span></span></span><span class="MJX_Assistive_MathML">un+1=un+2</span></span>. <br/></p>', true, '2017-07-25 09:35:29.756145+02', '2017-07-26 11:30:53.711971+02', true, 'submitted', 99, 444);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1143, '<p>Une usine fabrique des pièces mais les machines ne sont pas parfaites. En effet, 10% des pièces sont défectueuses. Si l''usine fabrique 540 pièces par jour, quelle est la probabilité que sur une journée </p>', true, '2017-07-26 11:42:17.521409+02', '2017-07-26 11:42:17.521438+02', true, 'submitted', 1207, 512);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1118, '<p>Parmi les suites suivantes, <b>identifie</b> si la suite :</p><p>- est une suite arithmétique</p><p>- est une suite géométrique</p><p>- n''est pas une suite</p><p><b>Donne </b>ensuite, s''il s''agit bien d''une suite, la raison de cette dernière. </p><p><i>(Si il ne s''agit pas d''une suite, met un 0)</i><br/></p>', true, '2017-07-25 12:21:17.69618+02', '2017-07-26 11:44:19.651285+02', true, 'submitted', 99, 440);
