INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1153, '<p>Soit la fonction \( f(x) = \frac{1}{2}x^2-3x+13\) <b>Dessine</b> le graphique de celle-ci.<br/></p><p>Pour construire le graphique de cette expression analytique, il est plus facile de réécrire \(f(x)\) sous la forme  \(f(x)=a(x\pm b)^2 \pm c\) , en utilisant la factorisation (en carrés parfaits). Ainsi, tu pourras facilement effectuer des opérations élémentaires sur \(x^2\) pour finalement construire \(f(x)\).<br/>. <br/></p>', true, '2017-07-26 14:56:03.305559+02', '2017-07-26 14:56:03.305598+02', true, 'submitted', 99, 346);
