INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1161, '<p><img src="/media/exercices/Q22-U1-A4_01.PNG"/></p><p style="font-size: 16px;">Voici 4 graphiques de fonctions ainsi que 4 tableaux de nombres. Associe à chaque expression analytique son tableau et son graphique correspondant. </p><p style="font-size: 16px;"><br/></p><p style="font-size: 16px;">Si à \(f_1(x)\)correspond le tableau 1 et le graphique f<span id="MathJax-Element-4-Frame" class="mjx-chtml MJXc-processed" style="text-align: left;font-size: 121%;float: none;direction: ltr;"><span id="MJXc-Node-19" class="mjx-math"><span id="MJXc-Node-20" class="mjx-mrow" style="text-align: left;"><span id="MJXc-Node-21" class="mjx-mi" style="text-align: left;"><span class="mjx-char MJXc-TeX-math-I" style="text-align: left;">f</span></span></span></span><span class="MJX_Assistive_MathML" style="height: 1px !important;width: 1px !important;">f</span><span id="MJXc-Node-34" class="mjx-math"><span id="MJXc-Node-35" class="mjx-mrow" style="width: 2.72em;"><span id="MJXc-Node-36" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">L</span></span><span id="MJXc-Node-37" class="mjx-mspace" style="width: 0px;height: 0px;"></span><span id="MJXc-Node-38" class="mjx-mpadded"><span class="mjx-block" style="width: 0px;"><span class="mjx-box" style="width: 0px;"><span id="MJXc-Node-39" class="mjx-mrow"><span id="MJXc-Node-40" class="mjx-texatom"><span id="MJXc-Node-41" class="mjx-mrow"><span id="MJXc-Node-42" class="mjx-mstyle" style="font-size: 80%;"><span id="MJXc-Node-43" class="mjx-mrow" style="font-size: 88.4%;"><span id="MJXc-Node-44" class="mjx-texatom"><span id="MJXc-Node-45" class="mjx-mrow"><span id="MJXc-Node-46" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">A</span></span></span></span></span></span></span></span></span></span><span class="mjx-strut"></span></span></span><span id="MJXc-Node-47" class="mjx-mspace" style="width: 0px;height: 0px;"></span><span id="MJXc-Node-48" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">T</span></span><span id="MJXc-Node-49" class="mjx-mspace" style="width: 0px;height: 0px;"></span><span id="MJXc-Node-50" class="mjx-mpadded"><span class="mjx-block" style="width: 0px;"><span class="mjx-box" style="width: 0px;"><span id="MJXc-Node-51" class="mjx-mrow"><span id="MJXc-Node-52" class="mjx-texatom"><span id="MJXc-Node-53" class="mjx-mrow"><span id="MJXc-Node-54" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">E</span></span></span></span></span></span><span class="mjx-strut"></span></span></span><span id="MJXc-Node-55" class="mjx-mspace" style="width: 0px;height: 0px;"></span><span id="MJXc-Node-56" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">X</span></span></span></span><span class="MJX_Assistive_MathML">LATEX</span></span>, tu encoderas \(f_1(x)\).</p>', true, '2017-07-26 16:13:48.640022+02', '2017-07-26 16:26:58.41603+02', true, 'submitted', 1207, 567);
