INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1228, '<p>Soient les 4 fonctions ci-dessous.<br/></p><p><br/></p><p>\(f(x) = -\dfrac{1}{3}x+1 \)</p><p>\(g(x) = \dfrac{2}{3}x + \dfrac{1}{5} \)</p><p>\(h(x) = 2\)</p><p>\(p(x) = \dfrac{2}{5}x \)</p><p><br/></p><p>Détermine algébriquement l''intersection entre les fonctions suivantes. Exprime ta réponse sous forme d''entier ou de fraction irréductible.<br/></p>', true, '2017-07-28 11:10:24.10253+02', '2017-07-28 11:10:24.102559+02', true, 'submitted', 1207, 213);
