INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1163, '<p><img src="/media/exercices/Q32-U1-A1_01.PNG"/></p><p>Soit une fonction cubique dont le graphe est représenté ci-dessus.</p><p><b>Réponds</b> aux différentes questions ci-dessous.</p><p><i></i><br/></p><p><i>Remarque:</i><br/></p><p>\( \cdot \) Pour le domaine de définitions et l''ensemble-image, veille à utiliser les mêmes symboles que ci-contre : \( R, R+, R- ,R \backslash \{ a \}, [a,b] , ]a,b] , [a,b[ , ]a,b[ , \{ \} \)</p><p>\( \cdot \) Pour les intersections : </p><p>- si il y en a plusieurs veillez bien les séparer comme sur l''exempleci-contre : \((x_1),(x_2),(x_3),...\) avec \(x_1&lt;x_2&lt;x_3&lt;...\)</p><p>- si il n''y en a pas, mettre une parenthèse vide \( ( ) \)<br/></p>', true, '2017-07-26 16:53:57.092337+02', '2017-07-26 17:09:32.855296+02', true, 'submitted', 99, 618);
