INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1173, '<p><img src="/media/exercices/Q32-U1-A2_02.PNG"/></p><p>Soit les fonctions <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">f</span></span><span id="MJXc-Node-14" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-15" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-16" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span><span id="MJXc-Node-17" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">,</span></span><span id="MJXc-Node-18" class="mjx-mi MJXc-space1"><span class="mjx-char MJXc-TeX-math-I">g</span></span><span id="MJXc-Node-19" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-20" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-21" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span><span id="MJXc-Node-22" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">,</span></span><span id="MJXc-Node-23" class="mjx-mi MJXc-space1"><span class="mjx-char MJXc-TeX-math-I">h</span></span><span id="MJXc-Node-24" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-25" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-26" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span><span id="MJXc-Node-27" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">,</span></span><span id="MJXc-Node-28" class="mjx-mi MJXc-space1"><span class="mjx-char MJXc-TeX-math-I">p</span></span><span id="MJXc-Node-29" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-30" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-31" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span></span></span><span class="MJX_Assistive_MathML">f(x),g(x),h(x),p(x)</span></span><br/></p>', true, '2017-07-27 09:58:37.087026+02', '2017-08-02 08:46:35.874374+02', true, 'submitted', 99, 619);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1164, '<p><img src="/media/exercices/Q32-U1-A1_02.PNG"/></p><p>Soit une fonction exponentielle dont le graphe est représenté ci-dessus.<br/><b>Réponds</b> aux différentes questions ci-dessous.</p><p><br/><i>Remarque :</i><br/>\( \cdot \) Pour le domaine de définitions et l''ensemble-image, veille à utiliser les mêmes symboles que ci-contre : \( R, R+, R- ,R \backslash \{ a \}, [a,b] , ]a,b] , [a,b[ , ]a,b[ , \{ \} \)</p><p>\( \cdot \) Pour les intersections : </p><p>- si il y en a plusieurs veillez bien les séparer comme sur l''exemple ci-contre : \( (x_1),(x_2),(x_3),... \) avec \(x_1&lt;x_2&lt;x_3&lt;... \)</p><p>- si il n''y en a pas, mettre une parenthèse vide \( ( ) \)<br/></p>', true, '2017-07-26 17:01:10.070379+02', '2017-07-26 17:08:57.870498+02', true, 'submitted', 99, 618);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1167, '<p>Soient les équations suivantes :</p><ol><li>​\(-x²-x+6\)</li><li>\(-x²+10x-9\)</li><li>\(-3x²+3x+18\)</li><li>\(-4x²-36x-80\)</li></ol><p style="font-size: 16px;">Pour chacune d''entre elles, trouve le discriminant et trouve la ou les solution(s).</p><p style="font-size: 16px;text-align: right;">L.Vds.​</p><!--EndFragment--><p><br/></p><p><br/></p>', true, '2017-07-26 21:46:38.577444+02', '2017-07-26 21:46:38.57748+02', true, 'submitted', 593, 342);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1198, '<p>Parmi les suites suivantes,<b> identifie</b> si la suite :<br/>- est une suite arithmétique<br/>- est une suite géométrique<br/>- n''est pas une suite</p><p><br/></p><p>Afin de <b>justifier</b> ton choix : </p><p>-Si c''est une suite (arithmétique ou géométrique), donne la raison de celle-ci</p><p>-Sinon met un 0</p>', true, '2017-07-27 16:02:56.552448+02', '2017-07-27 16:02:56.552478+02', true, 'submitted', 99, 631);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1168, '<p>Soient les équations suivantes : </p><ol><li>​\(x²+4x+4\)</li><li>\(-x²+10x-25\)</li><li>\(9x²-6x+1\)</li><li>\(-16x²-24x-9\)</li></ol><!--StartFragment--><p style="font-size: 16px;">Pour chacune d''entre elles, trouve le discriminant et trouve la ou les solution(s).</p><p style="font-size: 16px;text-align: right;">L.Vds.​</p><!--EndFragment--><p><br/></p><p><br/></p>', true, '2017-07-26 21:55:55.245102+02', '2017-07-26 21:55:55.245134+02', true, 'submitted', 593, 342);
