INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1177, '<p><img src="/media/exercices/Q32-U1-A5_01.PNG"/></p><p>Soit les fonctions \(f(x),g(x),h(x),p(x)\) dont les graphiques sont représentés ci-dessus.</p><p><b>Résous</b> les équations et inéquations suivantes à l''aide du graphique de ces fonctions.</p><p><br/></p><p><i>Remarques :</i></p><p>Utilise les symboles suivants : \( [a,b] , ]a,b] , [a,b[ , ]a,b[ , U \) avec \(a\) et \(b\) étant des réels ou \(-\infty\) , \(+\infty\). Pour le symbole \(\infty\) marque \(inf\)<br/></p>', true, '2017-07-27 10:53:55.874012+02', '2017-07-27 11:10:56.371677+02', true, 'submitted', 99, 622);
