INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1182, '<p>Soient les fonctions</p><p> \(f(x) = \sqrt{-(-3x - 4)} + x - 1\) et \(g(x) = \dfrac{4}{x} - \sqrt{x+5} \)</p><p><br/></p>', true, '2017-07-27 12:00:27.634978+02', '2017-07-27 12:00:27.635013+02', true, 'submitted', 1207, 614);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1184, '<p>Soient les fonctions </p><p>\( f(x) = \dfrac{5}{2}x - \sqrt{x} \)</p><p>\( g(x) = \dfrac{1}{x+3} + \sqrt{x} \)</p>', true, '2017-07-27 12:13:26.798768+02', '2017-07-27 12:13:26.7988+02', true, 'submitted', 1207, 615);
