INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1199, '<p>Parmi les suites suivantes, <b>identifie</b> si la suite :<br/>- est une suite arithmétique<br/>- est une suite géométrique<br/>- n''est pas une suite<br/><br/>Afin de <b>justifier</b> ton choix : <br/>-Si c''est une suite (arithmétique ou géométrique), donne la raison de celle-ci<br/>-Sinon met un 0<br/></p>', true, '2017-07-27 16:06:52.522168+02', '2017-07-27 16:06:52.522204+02', true, 'submitted', 99, 631);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1181, '<p><b>Calcul</b>e les images du réel demandé par les fonctions données.<br/></p>', true, '2017-07-27 11:48:57.674391+02', '2017-08-02 08:51:58.540488+02', true, 'submitted', 99, 614);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1187, '<p>Soient les équations suivantes:</p><ol><li>​\(\frac{x+2}{x-2}=\frac{-1}{2-x}\)</li><li>\(\frac{4x²+4x+3}{4x²-1}=0\)</li><li>\(x+1=\frac{2x²-5x+1}{x-1}\)</li><li>\(\frac{2}{x²-4}-\frac{4}{x+2}=1+\frac{3}{x-2}\)</li></ol><p>Pour chacune d''entre elles, donne les conditions d''existence et trouve leur(s) solutions.</p><p>ATTENTION : s''il n''existe pas de solution, écris &#34;impossible&#34; comme réponse. S''ils existent plusieurs solutions, écris les sans parenthèses, séparées d''un point-virgule. Exemple : 1;2</p><p style="text-align: right;">L.Vds.​</p>', true, '2017-07-27 13:45:37.38796+02', '2017-07-27 13:45:37.387989+02', true, 'submitted', 593, 342);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1166, '<p>Soient les équations suivantes :</p><ol><li>​\(x²-6x+5\)</li><li>\(x²+15x\)</li><li>\(2x²+8x-42\)</li><li>\(5x²+25x-70\)</li></ol><p>Pour chacune d''entre elles, trouve le discriminant et trouve la ou les solution(s).</p><p>ATTENTION : S''il n''existe pas de solution, écris &#34;impossible&#34; comme réponse.</p><p>lorsqu''il existe plusieurs solutions, écris les sans parenthèses, séparées d''un point-virgule. Exemple : 1;2</p><p><br/></p><p style="text-align: right;">L.Vds.​</p>', true, '2017-07-26 21:34:05.329623+02', '2017-07-27 14:01:18.380399+02', true, 'submitted', 593, 342);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1189, '<p>Oscar possède un compte dans une banque proposant des intérêts simples (annuels) de 5%. Son capital initial est de 1000 euros.</p><p><br/></p><p>Cela fait deux ans qu''Oscar possède ce compte en banque. Durant sa troisième année, Oscar a un job d''étudiant qui lui permet de gagner 500 euros. Il décide de les placer immédiatement sur son compte en banque. <br/></p>', true, '2017-07-27 14:38:43.158011+02', '2017-07-27 14:38:43.158041+02', true, 'submitted', 1207, 644);
