INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1193, '<p style="font-size: 16px;">Oscar possède un compte dans une banque proposant des intérêts composés (annuels) de 3%. Son capital initial est de 100 euros.</p><p style="font-size: 16px;"><br/></p><p style="font-size: 16px;">Trois ans après avoir placé ses 100 euros à la banque, Oscar reçoit 245 euros de sa grand-mère pour Noël! </p><p><br/></p>', true, '2017-07-27 15:20:12.525557+02', '2017-07-27 15:20:12.525585+02', true, 'submitted', 1207, 645);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1200, '<p>Parmi les suites suivantes, <b>identifie</b> si la suite :<br/>- est une suite arithmétique<br/>- est une suite géométrique<br/>- n''est pas une suite<br/><br/>Afin de <b>justifier</b> ton choix : <br/>-Si c''est une suite (arithmétique ou géométrique), donne la raison de celle-ci<br/>-Sinon met un 0<br/></p>', true, '2017-07-27 16:12:52.938682+02', '2017-07-27 16:12:52.938748+02', true, 'submitted', 99, 632);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1201, '<p>Une banque A propose à Oscar de placer son argent (160 euros) avec intérêts simples à un taux annuel de 3,2%. Une banque B propose à Oscar de placer son argent avec intérêts composés à un taux annuel de 2,5%. </p>', true, '2017-07-27 16:14:31.909425+02', '2017-07-27 16:14:31.909458+02', true, 'submitted', 1207, 643);
