INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1240, '<p>Réponds aux questions suivantes. Ta réponse doit être précise à l''unité près. </p><p><br/></p>', true, '2017-07-28 14:50:25.385652+02', '2017-07-28 14:50:25.385681+02', true, 'submitted', 1207, 190);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1244, '<p>Soit les 4 fonctions suivantes :</p><p>\( \cdot f(x) = \frac{1}{3}(x-2)+x \)</p><p>\( \cdot g(x) = 2x + \frac{1}{2} \)</p><p>\( \cdot h(x) = \frac{-1}{5}x + 2(x-4)\)</p><p>\( \cdot p(x) = 4(\frac{x}{2}+1) \)</p><p><br/></p><p><b>Détermine</b> algébriquement l''intersection entre les fonctions suivantes. Exprime ta réponse sous forme d''entier ou de fraction irréductible.<br/></p>', true, '2017-07-28 15:28:16.570436+02', '2017-07-28 15:28:16.570474+02', true, 'submitted', 99, 211);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1245, '<p>Une banque A propose à Oscar de placer son argent avec un intérêt simple à un taux annuel de 3 %. Oscar accepte et dépose 450 euros sur son compte en banque. </p><p><br/></p><p>Trois ans sont passés depuis, durant lesquels il a bénéficié des intérêts simples. Oscar joue à Win for Life. Il y gagne 150 euros par an à vie. Il décide de placer systématiquement cette somme sur son compte en banque. </p>', true, '2017-07-28 15:37:04.456127+02', '2017-07-28 15:37:04.456162+02', true, 'submitted', 1207, 208);
