INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1249, '<p style="font-size: 16px;">Oscar possède un compte dans une banque proposant des intérêts composés (annuels) de 3%. Son capital initial est de 1000 euros.</p><p style="font-size: 16px;"><br/></p><p style="font-size: 16px;">Trois ans après avoir placé ses 1000 euros à la banque, Oscar gagne 245 euros en faisant du baby-sitting durant l''année. </p>', true, '2017-07-28 16:39:12.097571+02', '2017-07-28 16:39:12.097606+02', true, 'submitted', 1207, 209);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1252, '<p>Une banque A propose à Oscar de placer son argent (350 euros) avec intérêts simples à un taux annuel de 3,2%. Une banque B propose à Oscar de placer son argent avec intérêts composés à un taux annuel de 2,5%. <br/></p>', true, '2017-07-28 16:52:19.446561+02', '2017-07-28 16:52:19.4466+02', true, 'submitted', 1207, 210);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1253, '<p>Oscar joue aux dés avec un ami. Exprime ta réponse sous forme de fraction irréductible.</p>', true, '2017-07-31 09:44:02.429517+02', '2017-07-31 09:44:02.429557+02', true, 'submitted', 1207, 231);
