INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1268, '<p>Résous les équations suivantes. Encode ta réponse sous forme de fraction irréductible ou sous forme d''entier. Si l''équation possède plusieurs réponses, encode-les par ordre croissant, en les séparant par une virgule.</p>', true, '2017-07-31 12:16:47.896012+02', '2017-07-31 12:16:47.896042+02', true, 'submitted', 1207, 667);
