INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1288, '<p>Réponds aux questions suivantes en utilisant le graphe ci-dessous lorsque cela est demandé.<br/></p><p><img src="/media/exercices/TB5-U3-C4_01.PNG"/></p>', true, '2017-08-07 17:35:50.132294+02', '2017-08-08 12:17:35.696007+02', true, 'submitted', 1210, 403);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1031, '<p><img src="/media/exercices/T3-U1-C3_01.PNG"/></p><p>Soit 2 triangles AMN et ARL communs en A.</p><p>En tenant compte des données ci-dessous,<b> réponds</b> aux différentes questions.</p><p>\( \overline{AR}=2,4 \)  , \( \overline{MR}=4 \) , \( \overline{RL}=5 \)</p><p><span class="MathJax_Preview" style="color: inherit;"></span><span class="mjx-chtml MJXc-processed" id="MathJax-Element-3-Frame" style="font-size: 120%;"><span class="mjx-math" id="MJXc-Node-11"><span class="mjx-mrow" id="MJXc-Node-12"><span class="mjx-mo" id="MJXc-Node-13"><span class="mjx-char MJXc-TeX-main-R">⋅</span></span></span></span><span class="MJX_Assistive_MathML">⋅</span><span class="mjx-math" id="MJXc-Node-11"><span class="mjx-mrow" id="MJXc-Node-12" style="width: 2.72em;"><span class="mjx-mi" id="MJXc-Node-13"><span class="mjx-char MJXc-TeX-math-I">L</span></span><span class="mjx-mspace" id="MJXc-Node-14" style="width: 0px;height: 0px;"></span><span class="mjx-mpadded" id="MJXc-Node-15"><span class="mjx-block" style="width: 0px;"><span class="mjx-box" style="width: 0px;"><span class="mjx-mrow" id="MJXc-Node-16"><span class="mjx-texatom" id="MJXc-Node-17"><span class="mjx-mrow" id="MJXc-Node-18"><span class="mjx-mstyle" id="MJXc-Node-19" style="font-size: 80%;"><span class="mjx-mrow" id="MJXc-Node-20" style="font-size: 88.4%;"><span class="mjx-texatom" id="MJXc-Node-21"><span class="mjx-mrow" id="MJXc-Node-22"><span class="mjx-mi" id="MJXc-Node-23"><span class="mjx-char MJXc-TeX-math-I">A</span></span></span></span></span></span></span></span></span></span><span class="mjx-strut"></span></span></span><span class="mjx-mspace" id="MJXc-Node-24" style="width: 0px;height: 0px;"></span><span class="mjx-mi" id="MJXc-Node-25"><span class="mjx-char MJXc-TeX-math-I">T</span></span><span class="mjx-mspace" id="MJXc-Node-26" style="width: 0px;height: 0px;"></span><span class="mjx-mpadded" id="MJXc-Node-27"><span class="mjx-block" style="width: 0px;"><span class="mjx-box" style="width: 0px;"><span class="mjx-mrow" id="MJXc-Node-28"><span class="mjx-texatom" id="MJXc-Node-29"><span class="mjx-mrow" id="MJXc-Node-30"><span class="mjx-mi" id="MJXc-Node-31"><span class="mjx-char MJXc-TeX-math-I">E</span></span></span></span></span></span><span class="mjx-strut"></span></span></span><span class="mjx-mspace" id="MJXc-Node-32" style="width: 0px;height: 0px;"></span><span class="mjx-mi" id="MJXc-Node-33"><span class="mjx-char MJXc-TeX-math-I">X</span></span></span></span><span class="MJX_Assistive_MathML">LATEX</span></span><br/></p>', true, '2017-07-19 14:56:03.849162+02', '2017-07-31 12:24:26.100969+02', true, 'submitted', 99, 238);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1269, '<p>Le théorème du calcul d''un volume d''un solide de révolution s''énonce comme suit :</p><p>« <i>Le volume du solide de révolution engendré par la rotation  autour de l''axe </i>\((0,\vec{i})\) <i>du domaine plan limité par la courbe de la fonction</i> \( f \), <i>les droites d''équations</i> \( x=a \)<i> et</i> \( x=b\)  \( (a&lt;b) \), et <i>l''axe </i>\((0,\vec{i})\), <i>est</i> \( V = \pi \int_a^b (f(x))^2 dx \) »</p><p><br/></p><p><b>Justifie</b> la formule et <b>illustre graphiquement</b> le volume du solide de révolution engendré par la rotation autour de l''axe \((0,\vec{i})\)  de la fonction \( f(x) = 5 \)  sur l''intervalle \( [3,12] \)</p>', true, '2017-07-31 12:41:19.666257+02', '2017-07-31 12:41:19.666287+02', false, 'submitted', 99, 513);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1259, '<p><img src="/media/exercices/Q22-U1-A2_02.PNG"/></p><p>Complète le tableau de nombres ci-dessus correspondant à la fonction <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">f</span></span><span id="MJXc-Node-14" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-15" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-16" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span><span id="MJXc-Node-17" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-18" class="mjx-mfrac MJXc-space3"><span class="mjx-box MJXc-stacked" style="width: 2.039em;"><span class="mjx-numerator" style="font-size: 70.7%;width: 2.883em;"><span id="MJXc-Node-19" class="mjx-mrow"><span id="MJXc-Node-20" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">2</span></span><span id="MJXc-Node-21" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">−</span></span><span id="MJXc-Node-22" class="mjx-msqrt"><span class="mjx-box"><span class="mjx-surd"><span class="mjx-char MJXc-TeX-main-R">√</span></span><span class="mjx-box"><span id="MJXc-Node-23" class="mjx-mrow"><span id="MJXc-Node-24" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span></span></span></span></span></span></span><span class="mjx-denominator" style="font-size: 70.7%;width: 2.883em;"><span id="MJXc-Node-25" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span></span><span style="width: 2.039em;" class="mjx-line"></span></span><span style="height: 1.564em;vertical-align: -0.37em;" class="mjx-vsize"></span></span></span></span><span class="MJX_Assistive_MathML">f(x)=2−xx</span></span><br/></p>', true, '2017-07-31 10:42:54.924371+02', '2017-08-01 10:46:22.167216+02', true, 'submitted', 99, 563);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1324, '<p>Détermine l''équation cartésienne d''un cercle ...</p><p>(la solution sera donnée sous la forme \((x-x_A)^2 + (y-y_A)^2 = r^2\) où \(x_A\), \(y_A\) et \(r\) auront été remplacés par leur valeur correspondante)</p>', true, '2017-08-09 15:54:47.210745+02', '2017-08-09 15:58:12.598019+02', true, 'submitted', 1210, 365);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1270, '<p>Soit la fonction \(f(x) = 2x^2 + 2x + 1 \). Dessine le graphique de celle-ci. </p><p>Pour construire le graphique de cette expression analytique, il est plus facile de réécrire \(f(x)\) sous la forme \f(x) = a(x\pm b )^2 \pm c \), en utilisant la factorisation (en carrés parfaits). Ainsi, tu pourras facilement effectuer des opérations élémentaires sur \(x^2\) pour finalement construire \(f(x)\).</p>', true, '2017-07-31 14:25:47.021403+02', '2017-07-31 14:25:47.021435+02', true, 'submitted', 1207, 348);
