INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1302, '<p>En utilisant les composantes des vecteurs suivants,</p><p>\( \overrightarrow{a} \begin{pmatrix} 1 \\ 0 \end{pmatrix} \) ; \( \overrightarrow{b} \begin{pmatrix} -2 \\ 4 \end{pmatrix} \) ; \( \overrightarrow{c} \begin{pmatrix} 3 \\ -2 \end{pmatrix} \) ; \( \overrightarrow{d} \begin{pmatrix} 0 \\ 3 \end{pmatrix} \) ; \( \overrightarrow{e} \begin{pmatrix} -1 \\ -4 \end{pmatrix} \)</p><p>réponds aux questions ci-dessous. </p><p>La solution sera à chaque fois donnée sous la forme : \( (x,y) \) où \(x\) et \(y\) auront été remplacés par les coordonnées recherchées.</p>', true, '2017-08-09 09:33:04.197914+02', '2017-08-09 09:57:36.056293+02', true, 'submitted', 1210, 359);
