INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1134, '<p>A l''aide du cercle trigonométrique et de ta calculatrice <b>résous</b> les équations suivantes.<br/><i></i></p><p><i>Les réponses doivent être</i><i> exprimées de manière suivante :</i></p><p> pour une réponse <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-14" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-15" class="mjx-mi MJXc-space3"><span class="mjx-char MJXc-TeX-math-I">a</span></span><span id="MJXc-Node-16" class="mjx-mo MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">+</span></span><span id="MJXc-Node-17" class="mjx-mi MJXc-space2"><span class="mjx-char MJXc-TeX-math-I">k</span></span><span id="MJXc-Node-18" class="mjx-mo MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">⋅</span></span><span id="MJXc-Node-19" class="mjx-mi MJXc-space2"><span class="mjx-char MJXc-TeX-math-I">b</span></span></span></span><span class="MJX_Assistive_MathML">x=a+k⋅b</span></span>​</p>', true, '2017-07-26 10:01:31.48149+02', '2017-08-02 08:35:27.968284+02', true, 'submitted', 99, 490);
