INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1183, '<p><b>Identifie</b> les antécédents d''un réel demandé par une fonction donnée.</p><p><i>Si il y a plusieurs antécédents, veille à respecter la structure comme sur l''exemple ci-contre :</i> <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-14" class="mjx-msubsup"><span class="mjx-base"><span id="MJXc-Node-15" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span></span><span class="mjx-sub" style="font-size: 70.7%;vertical-align: -0.212em;"><span id="MJXc-Node-16" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">1</span></span></span></span><span id="MJXc-Node-17" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span><span id="MJXc-Node-18" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">,</span></span><span id="MJXc-Node-19" class="mjx-mo MJXc-space1"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-20" class="mjx-msubsup"><span class="mjx-base"><span id="MJXc-Node-21" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span></span><span class="mjx-sub" style="font-size: 70.7%;vertical-align: -0.212em;"><span id="MJXc-Node-22" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">2</span></span></span></span><span id="MJXc-Node-23" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span><span id="MJXc-Node-24" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">,</span></span><span id="MJXc-Node-25" class="mjx-mo MJXc-space1"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-26" class="mjx-msubsup"><span class="mjx-base"><span id="MJXc-Node-27" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span></span><span class="mjx-sub" style="font-size: 70.7%;vertical-align: -0.212em;"><span id="MJXc-Node-28" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">3</span></span></span></span><span id="MJXc-Node-29" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span><span id="MJXc-Node-30" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">,</span></span><span id="MJXc-Node-31" class="mjx-mo MJXc-space1"><span class="mjx-char MJXc-TeX-main-R">.</span></span><span id="MJXc-Node-32" class="mjx-mo MJXc-space1"><span class="mjx-char MJXc-TeX-main-R">.</span></span><span id="MJXc-Node-33" class="mjx-mo MJXc-space1"><span class="mjx-char MJXc-TeX-main-R">.</span></span></span></span><span class="MJX_Assistive_MathML">(x1),(x2),(x3),...</span></span><br/></p>', true, '2017-07-27 12:02:53.427487+02', '2017-08-02 08:54:05.263886+02', true, 'submitted', 99, 615);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1203, '<p>Soit la fonction carrée <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">f</span></span><span id="MJXc-Node-14" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-15" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-16" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span><span id="MJXc-Node-17" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-18" class="mjx-msubsup MJXc-space3"><span class="mjx-base"><span id="MJXc-Node-19" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span></span><span class="mjx-sup" style="font-size: 70.7%;vertical-align: 0.513em;"><span id="MJXc-Node-20" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">2</span></span></span></span></span></span><span class="MJX_Assistive_MathML">f(x)=x2</span></span>. </p><p>Identifie les différentes caratéristiques de cette fonction.<br/></p>', true, '2017-07-27 16:40:09.398424+02', '2017-08-02 09:01:59.034798+02', true, 'submitted', 99, 629);
