INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1023, '<p><img src="/media/exercices/TG5-U5-C4_01.PNG"/></p><p>Sur chacune des trois figures ci-dessus sont représentées 4 fonctions de type <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">f</span></span><span id="MJXc-Node-14" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-15" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-16" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span><span id="MJXc-Node-17" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-18" class="mjx-mi MJXc-space3"><span class="mjx-char MJXc-TeX-math-I">a</span></span><span id="MJXc-Node-19" class="mjx-mi MJXc-space1"><span class="mjx-char MJXc-TeX-main-R">sin</span></span><span id="MJXc-Node-20" class="mjx-mo"><span class="mjx-char"></span></span><span id="MJXc-Node-21" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-22" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">b</span></span><span id="MJXc-Node-23" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-24" class="mjx-mo MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">+</span></span><span id="MJXc-Node-25" class="mjx-mi MJXc-space2"><span class="mjx-char MJXc-TeX-math-I">c</span></span><span id="MJXc-Node-26" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span></span></span><span class="MJX_Assistive_MathML">f(x)=asin&#8289;(bx+c)</span></span> correspond à l''expression 4)<br/></p><p style="font-size: 16px;">Alors tu écris :  f, g, h, p</p><p style="font-size: 16px;"><br/></p>', true, '2017-07-19 12:12:43.835002+02', '2017-08-02 10:56:09.328935+02', true, 'submitted', 1207, 485);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (967, '<p>La notation scientifique est très utile lorsque tu seras amené à écrire de très petits chiffres, ou de très grands. Cela te permet de faciliter tes calculs mais également d''y voir plus clair. Exprime les nombres qui suivent en notation scientifique. <br/>Voici un exemple à suivre pour clarifier l''encodage de la réponse:</p><p>S''il faut écrire 1230 en notation scientifique, tu réponds :</p><p><span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">1</span></span><span id="MJXc-Node-14" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">,</span></span><span id="MJXc-Node-15" class="mjx-mn MJXc-space1"><span class="mjx-char MJXc-TeX-main-R">23</span></span><span id="MJXc-Node-16" class="mjx-mo MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">⋅</span></span><span id="MJXc-Node-17" class="mjx-msubsup MJXc-space2"><span class="mjx-base"><span id="MJXc-Node-18" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">10</span></span></span><span class="mjx-sup" style="font-size: 70.7%;vertical-align: 0.591em;"><span id="MJXc-Node-19" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">3</span></span></span></span></span></span><span class="MJX_Assistive_MathML">1,23⋅103</span></span></p><p><br/></p>', true, '2017-07-17 14:12:15.46664+02', '2017-08-02 12:20:01.42377+02', true, 'submitted', 1207, 298);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1282, '<p>Pour chacune des sous-questions suivantes, choisis la solution la plus intéressante.</p>', true, '2017-08-07 12:38:06.082369+02', '2017-08-07 12:38:06.082418+02', true, 'submitted', 1210, 399);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1281, '<p>Pour chacune des suites arithmétiques suivantes, trouve sa raison et son terme général.</p>', true, '2017-08-07 11:12:11.377458+02', '2017-08-07 12:45:53.057411+02', true, 'submitted', 1210, 385);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1297, '<p>Dans un graphique en échelle logarithmique ou semi-logarithmique (linéaire en \(x\) et logarithmique en \(y\)), représente les fonctions suivantes :</p><ol><li>​\(f(x) = x^2\)</li><li>\(f(x) = \sqrt{x}\)</li><li>​\(f(x) = \exp(x)\)</li><li>​\(f(x) = \ln(x)\)</li></ol>', true, '2017-08-08 15:17:52.34282+02', '2017-08-08 15:17:52.342851+02', false, 'submitted', 1210, 406);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1058, '<p style="font-size: 16px;">Dans les situations ci-dessous, une certaine somme d''argent est placée à <i>intérêts composés</i> à la banque, pendant un certain temps et à un certain taux. </p><p style="font-size: 16px;">Réponds aux questions ci-dessous et arrondis tes réponses à <b><i>deux décimales</i></b>.</p>', true, '2017-07-20 12:57:54.015612+02', '2017-08-08 10:15:25.449452+02', true, 'submitted', 1220, 457);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1290, '<p>La forme générale d''une fonction exponentielle \(f\) est donnée par l''expression</p><p>\( f(x) = Ab^x \)</p><p>où \(A\) est une constante quelconque et \(b\) est une constante strictement positive.</p><p><br/></p><p>En utilisant cette forme générale, modélise la situation demandée puis réponds aux questions associées.<br/></p>', true, '2017-08-08 10:28:55.454293+02', '2017-08-08 10:28:55.454325+02', true, 'submitted', 1210, 408);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1323, '<p style="font-size: 16px;">Soit le repère suivant :</p><p><img src="/media/exercices/T4-U6-A06_01.PNG"/></p><p>calcule (et arrondi au centième près) la distance entre la droite \(d\) et le point</p><p><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span class="MJX_Assistive_MathML"><span style="font-size: 16px;">et le p</span></span></span></p>', true, '2017-08-09 15:27:44.367138+02', '2017-08-09 15:29:08.466955+02', true, 'submitted', 1210, 364);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1289, '<p>La forme générale d''une fonction puissance \(f\) est donnée par</p><p>\( f(x) = Ax^r \)</p><p>avec \(x&gt;0\), \(r\) et \(A\) des constantes quelconques.</p><p><br/></p><p>En utilisant cette forme générale, modélise la situation demandée puis réponds aux questions associées.</p>', true, '2017-08-08 09:56:33.069784+02', '2017-08-08 10:31:25.247834+02', true, 'submitted', 1210, 408);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1291, '<p style="font-size: 16px;">L''évolution de la population (en centaine d''habitants) en fonction du temps (en années) dans le pays Mathland est décrite par la courbe suivante :</p><p><img src="/media/exercices/TB5-U3-T1_01.PNG"/></p><p>En utilisant ce graphe, répondez aux questions suivantes :</p>', true, '2017-08-08 11:04:41.889262+02', '2017-08-08 11:11:18.825571+02', true, 'submitted', 1210, 407);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (932, '<p>Jean voudrait construire un enclos rectangulaire pour ses moutons. Il voudrait que l''enclos soit le plus grand possible afin que ses moutons aient le plus d''espace possible pour gambader. Sachant qu''il dispose à cet effet de 700m de clôture, donne les dimensions que Jean doit donner aux côtés de sa clôture pour que l''aire de l''enclos soit la plus grande possible.</p><p><br/></p>', true, '2017-07-13 12:23:58.428368+02', '2017-08-08 11:46:06.024601+02', true, 'submitted', 1220, 476);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1298, '<p>Reproduit le graphique suivant mais en utilisant une échelle logarithmique ou semi-logarithmique (linéaire en \(x\) et logarithmique en \(y\)) :<br/></p><p><img src="/media/exercices/TB5-U3-A3_01.PNG"/></p>', true, '2017-08-08 15:23:02.650713+02', '2017-08-08 15:24:13.41136+02', true, 'submitted', 1210, 406);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1292, '<p style="font-size: 16px;">Grâce à de savants calculs, la jeune entreprise MATH-erne qui produit de la confiture bio a réussi à approximer le profit en euros qu''elle peut potentiellement gagner par jour en fonction du nombre de kilogrammes qu''elle produit journalièrement par la courbe suivante :</p><p><img src="/media/exercices/TB5-U3-T1_02.PNG"/></p><p>Cette toute petite entreprise, ne peut actuellement produire que 10kg de confiture par jour mais elle a déjà simulé comment évoluerait son profit si elle réussissait à augmenter sa production journalière.</p><p>En utilisant le graphe fourni, réponds aux questions suivantes :</p>', true, '2017-08-08 12:04:16.089924+02', '2017-08-08 12:04:32.431822+02', true, 'submitted', 1210, 407);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1294, '<p>Pour chacune des courbes présentées dans ce graphe, associe le modèle de croissance correspondant : <br/></p><p><img src="/media/exercices/TB5-U3-C1_01.PNG"/></p>', true, '2017-08-08 13:02:21.9359+02', '2017-08-08 13:03:32.426586+02', true, 'submitted', 1210, 400);
