INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1299, '<p>En utilisant le tableau de valeurs d''une certaine fonction, calcule les différents taux d''accroissement demandés afin d''approximer la dérivée en \(x=2\) :</p><table border="2" style="text-align: center;">   <tbody><tr>       <th>Ordonnée (\(x\)) </th>       <th>Abscisse (\(y\)) </th>   </tr>   <tr>       <td>0</td>       <td>-0.5</td>   </tr>   <tr>       <td>1</td>       <td>-1</td>   </tr><tr>       <td>1.5</td>       <td>-1.4142</td>   </tr><tr>       <td>1.75</td>       <td>-1.6818</td>   </tr><tr>       <td>1.9</td>       <td>-1.8661</td>   </tr><tr>       <td>2</td>       <td>-2</td>   </tr></tbody></table><p>Pour chacune des sous-questions, il t''est demandé d''arrondir ta réponse au centième d''unité le plus proche.</p>', true, '2017-08-08 16:00:05.886318+02', '2017-08-08 16:00:05.886348+02', true, 'submitted', 1210, 404);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1325, '<p style="font-size: 16px;">Soit le repère suivant,</p><p><img src="/media/exercices/T4-U6-A07_01.PNG"/></p><p>détermine l''équation cartésienne d''un cercle ...</p><p>(la solution sera donnée sous la forme \((x-x_A)^2 + (y-y_A)^2 = r^2\) où \(x_A\), \(y_A\) et \(r\) <span>auront été remplacés par leur valeur correspondante)</span></p>', true, '2017-08-09 16:27:20.562839+02', '2017-08-09 16:30:13.226328+02', true, 'submitted', 1210, 365);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1301, '<p>La société MATH-erne qui produit de la confiture bio a un coût marginal pour la fabrication de \(x\) kilogrammes de confiture qui est égal à </p><p>\(c''(x) = a\exp(bx) + f\) </p><p>avec \(b \ne 0\).</p><p><br/></p><p>Réponds aux questions suivantes (fais en sorte de ne jamais utiliser le signe de la multiplication (\(\cdot\)) et de ne pas changer l''ordre des termes) :</p>', true, '2017-08-08 17:25:33.660907+02', '2017-08-08 17:25:33.660936+02', true, 'submitted', 1210, 520);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (961, '<p>Sans effectuer de division, identifie et coche les polynômes par lesquels les polynômes suivants sont divisibles : </p><p>N.B.: Plusieurs réponses peuvent être cochées.</p>', true, '2017-07-17 12:23:01.638051+02', '2017-08-09 09:21:24.63178+02', true, 'submitted', 1220, 291);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (946, '<p style="font-size: 16px;">Soit les systèmes d''équations suivants :</p><p style="font-size: 16px;">a.) <span class="MathJax_Preview" style="color: inherit;"></span><span class="mjx-chtml MJXc-display" style="text-align: center;"><span id="MathJax-Element-3-Frame" class="mjx-chtml MJXc-processed" style="font-size: 121%;text-align: center;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mrow"><span id="MJXc-Node-14" class="mjx-mo"><span class="mjx-char MJXc-TeX-size3-R">{</span></span><span id="MJXc-Node-15" class="mjx-mtable" style="vertical-align: -0.925em;"><span class="mjx-table"><span id="MJXc-Node-16" class="mjx-mtr" style="height: 1.175em;"><span id="MJXc-Node-17" class="mjx-mtd" style="text-align: left;width: 11.915em;"><span id="MJXc-Node-18" class="mjx-mrow"><span id="MJXc-Node-19" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">6</span></span><span id="MJXc-Node-20" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-21" class="mjx-mo MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">−</span></span><span id="MJXc-Node-22" class="mjx-mn MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">2</span></span><span id="MJXc-Node-23" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">y</span></span><span id="MJXc-Node-24" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-25" class="mjx-mn MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">2</span></span><span id="MJXc-Node-26" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-27" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">3</span></span><span id="MJXc-Node-28" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-29" class="mjx-mo MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">−</span></span><span id="MJXc-Node-30" class="mjx-mi MJXc-space2"><span class="mjx-char MJXc-TeX-math-I">y</span></span><span id="MJXc-Node-31" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span><span class="mjx-strut"></span></span></span></span><span id="MJXc-Node-32" class="mjx-mtr" style="height: 1.175em;"><span id="MJXc-Node-33" class="mjx-mtd" style="text-align: left;"><span id="MJXc-Node-34" class="mjx-mrow"><span id="MJXc-Node-35" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">−</span></span><span id="MJXc-Node-36" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-37" class="mjx-mo MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">−</span></span><span id="MJXc-Node-38" class="mjx-mn MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">4</span></span><span id="MJXc-Node-39" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">y</span></span><span id="MJXc-Node-40" class="mjx-mo MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">+</span></span><span id="MJXc-Node-41" class="mjx-mn MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">4</span></span><span id="MJXc-Node-42" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-43" class="mjx-mn MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">4</span></span><span id="MJXc-Node-44" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-45" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">1</span></span><span id="MJXc-Node-46" class="mjx-mo MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">−</span></span><span id="MJXc-Node-47" class="mjx-mi MJXc-space2"><span class="mjx-char MJXc-TeX-math-I">y</span></span><span id="MJXc-Node-48" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span><span id="MJXc-Node-49" class="mjx-mo MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">−</span></span><span id="MJXc-Node-50" class="mjx-mi MJXc-space2"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span class="mjx-strut"></span></span></span></span></span></span><span id="MJXc-Node-51" class="mjx-mo" style="width: 0.12em;"></span></span></span></span><span class="MJX_Assistive_MathML MJX_Assistive_MathML_Block">{6x−2y=2(3x−y)−x−4y+4=4(1−y)−x</span><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow" style="width: 2.72em;"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">L</span></span><span id="MJXc-Node-14" class="mjx-mspace" style="width: 0px;height: 0px;"></span><span id="MJXc-Node-15" class="mjx-mpadded"><span class="mjx-block" style="width: 0px;"><span class="mjx-box" style="width: 0px;"><span id="MJXc-Node-16" class="mjx-mrow"><span id="MJXc-Node-17" class="mjx-texatom"><span id="MJXc-Node-18" class="mjx-mrow"><span id="MJXc-Node-19" class="mjx-mstyle" style="font-size: 80%;"><span id="MJXc-Node-20" class="mjx-mrow" style="font-size: 88.4%;"><span id="MJXc-Node-21" class="mjx-texatom"><span id="MJXc-Node-22" class="mjx-mrow"><span id="MJXc-Node-23" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">A</span></span></span></span></span></span></span></span></span></span><span class="mjx-strut"></span></span></span><span id="MJXc-Node-24" class="mjx-mspace" style="width: 0px;height: 0px;"></span><span id="MJXc-Node-25" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">T</span></span><span id="MJXc-Node-26" class="mjx-mspace" style="width: 0px;height: 0px;"></span><span id="MJXc-Node-27" class="mjx-mpadded"><span class="mjx-block" style="width: 0px;"><span class="mjx-box" style="width: 0px;"><span id="MJXc-Node-28" class="mjx-mrow"><span id="MJXc-Node-29" class="mjx-texatom"><span id="MJXc-Node-30" class="mjx-mrow"><span id="MJXc-Node-31" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">E</span></span></span></span></span></span><span class="mjx-strut"></span></span></span><span id="MJXc-Node-32" class="mjx-mspace" style="width: 0px;height: 0px;"></span><span id="MJXc-Node-33" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">X</span></span></span></span><span class="MJX_Assistive_MathML">LATEX</span></span></span></p><p style="font-size: 16px;">Donne le nombre de solutions pour chacun des systèmes et leur solution.</p><p style="font-size: 16px;">Lorsque tu entres la solution utilise les notations suivantes (en fonction de si ta solution est l''ensemble de points, l''ensemble des réels au carré, l''ensemble vide) : </p><p style="font-size: 16px;">{ (a;b) ; (c;d) }</p><p style="font-size: 16px;">R carré</p><p style="font-size: 16px;">{/}</p><p style="font-size: 16px;"><br/></p><p style="text-align: right;font-size: 16px;">Source : auto-maths.be, Marielle Cherpion​</p>', true, '2017-07-14 17:37:30.607237+02', '2017-08-09 09:32:07.337744+02', true, 'submitted', 1220, 292);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (945, '<p>Soit les systèmes d''équations suivants :</p><p>a.)<span class="MathJax_Preview" style="color: inherit;"></span><span class="mjx-chtml MJXc-display" style="text-align: center;"><span id="MathJax-Element-3-Frame" class="mjx-chtml MJXc-processed" style="font-size: 121%;text-align: center;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mrow"><span id="MJXc-Node-14" class="mjx-mo"><span class="mjx-char MJXc-TeX-size3-R">{</span></span><span id="MJXc-Node-15" class="mjx-mtable" style="vertical-align: -0.88em;"><span class="mjx-table"><span id="MJXc-Node-16" class="mjx-mtr" style="height: 1.13em;"><span id="MJXc-Node-17" class="mjx-mtd" style="text-align: left;width: 5.124em;"><span id="MJXc-Node-18" class="mjx-mrow"><span id="MJXc-Node-19" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">3</span></span><span id="MJXc-Node-20" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-21" class="mjx-mo MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">+</span></span><span id="MJXc-Node-22" class="mjx-mn MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">2</span></span><span id="MJXc-Node-23" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">y</span></span><span id="MJXc-Node-24" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-25" class="mjx-mn MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">9</span></span><span class="mjx-strut"></span></span></span></span><span id="MJXc-Node-26" class="mjx-mtr" style="height: 1.13em;"><span id="MJXc-Node-27" class="mjx-mtd" style="text-align: left;"><span id="MJXc-Node-28" class="mjx-mrow"><span id="MJXc-Node-29" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">4</span></span><span id="MJXc-Node-30" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-31" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-32" class="mjx-mi MJXc-space3"><span class="mjx-char MJXc-TeX-math-I">y</span></span><span id="MJXc-Node-33" class="mjx-mo MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">+</span></span><span id="MJXc-Node-34" class="mjx-mn MJXc-space2"><span class="mjx-char MJXc-TeX-main-R">1</span></span><span class="mjx-strut"></span></span></span></span></span></span><span id="MJXc-Node-35" class="mjx-mo" style="width: 0.12em;"></span></span></span></span><span class="MJX_Assistive_MathML MJX_Assistive_MathML_Block">{3x+2y=94x=y+1</span><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow" style="width: 2.72em;"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">L</span></span><span id="MJXc-Node-14" class="mjx-mspace" style="width: 0px;height: 0px;"></span><span id="MJXc-Node-15" class="mjx-mpadded"><span class="mjx-block" style="width: 0px;"><span class="mjx-box" style="width: 0px;"><span id="MJXc-Node-16" class="mjx-mrow"><span id="MJXc-Node-17" class="mjx-texatom"><span id="MJXc-Node-18" class="mjx-mrow"><span id="MJXc-Node-19" class="mjx-mstyle" style="font-size: 80%;"><span id="MJXc-Node-20" class="mjx-mrow" style="font-size: 88.4%;"><span id="MJXc-Node-21" class="mjx-texatom"><span id="MJXc-Node-22" class="mjx-mrow"><span id="MJXc-Node-23" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">A</span></span></span></span></span></span></span></span></span></span><span class="mjx-strut"></span></span></span><span id="MJXc-Node-24" class="mjx-mspace" style="width: 0px;height: 0px;"></span><span id="MJXc-Node-25" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">T</span></span><span id="MJXc-Node-26" class="mjx-mspace" style="width: 0px;height: 0px;"></span><span id="MJXc-Node-27" class="mjx-mpadded"><span class="mjx-block" style="width: 0px;"><span class="mjx-box" style="width: 0px;"><span id="MJXc-Node-28" class="mjx-mrow"><span id="MJXc-Node-29" class="mjx-texatom"><span id="MJXc-Node-30" class="mjx-mrow"><span id="MJXc-Node-31" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">E</span></span></span></span></span></span><span class="mjx-strut"></span></span></span><span id="MJXc-Node-32" class="mjx-mspace" style="width: 0px;height: 0px;"></span><span id="MJXc-Node-33" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">X</span></span></span></span><span class="MJX_Assistive_MathML">LATEX</span></span></span></p><p><br/></p><p>Donne le nombre de solutions pour chacun des systèmes et leur solution.</p><p>Lorsque tu entres la solution utilise les notations suivantes (en fonction de si ta solution est l''ensemble de points, l''ensemble des réels au carré, l''ensemble vide) : </p><p>{ (a;b) ; (c;d) }</p><p>R carré</p><p>{/}</p><p><span style="font-size: 17.5px;"><br/></span></p><p><span style="font-size: 17.5px;"></span></p><div style="text-align: right;">​Source : auto-maths.be, Marielle Cherpion</div><p></p>', true, '2017-07-14 17:30:49.796253+02', '2017-08-09 09:33:57.600317+02', true, 'submitted', 1220, 292);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (666, '<p>Le tableau ci-dessous indique la distance parcourue par un coureur pendant son entraînement.</p><table class="table table-bordered">    <tbody><tr>        <th>Temps écoulé [minutes]</th>        <td>30</td>        <td>60</td>        <td>120</td>        <td>180</td>    </tr>    <tr>        <th>Distance parcourue [kilomètre]</th>        <td>60</td>        <td>120</td>        <td>240</td>        <td>360</td>    </tr></tbody></table>', true, '2017-05-09 23:06:18.216004+02', '2017-08-09 09:47:01.064408+02', true, 'adapted', 123, 81);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1322, '<p>Calcule (et arrondi au centième près) la distance entre la droite d''équation \(3x + 2y - 6 + 0\) et les points </p>', true, '2017-08-09 15:16:51.951007+02', '2017-08-09 15:16:51.951036+02', true, 'submitted', 1210, 364);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (931, '<p><img src="/media/exercices/TG5-U4-T2_01.PNG"/></p><p>Soit un cercle C de centre (0;0) et de rayon r=1. Le rectangle ABDE y est inscrit. Si on peut faire glisser les points A, B, D et E le long du cercle, tout en gardant les segments a et c parallèles et les segments b et d parallèles (de sorte que ABDE reste un rectangle inscrit), où doit-on placer A pour maximiser l''aire de ce rectangle ?</p><p>Astuce : Cherche d''abord comment maximiser l''aire du rectangle, délimité par les axes d''abscisses et d''ordonnées dans le cadran supérieur droit, pour trouver la position de A. La position de B, D, E est alors facilement trouvable par symétrie. </p><p><br/></p><p>Ecris tes réponses sous formes de fractions irréductibles. Et, au besoin, mets le signe &#34;-&#34; devant la fraction (pas au numérateur ni dénominateur).</p><p><br/></p>', true, '2017-07-13 11:06:03.140796+02', '2017-08-09 09:57:34.597983+02', true, 'submitted', 1220, 476);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1303, '<p>Quel est le nom de 3 dans les calculs suivants?  </p>', true, '2017-08-09 10:09:48.177892+02', '2017-08-09 10:09:48.177924+02', true, 'submitted', 122, 36);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1305, '<p>Pour chaque situation, détermine le nom de l''opération.</p>', true, '2017-08-09 10:22:08.631299+02', '2017-08-09 10:22:08.631342+02', true, 'submitted', 122, 36);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1304, '<p style="font-size: 16px;">En utilisant la figure suivante,<br/></p><p><img src="/media/exercices/T4-U6-A01_01.PNG" width="500"/></p><p style="font-size: 16px;">calcule les sommes vectorielles ci-dessous.</p><p style="font-size: 16px;">La solution sera à chaque fois donnée sous la forme : \(XY\) où \(X\) et \(Y\) auront été remplacés respectivement par l''origine et l''extrémité du vecteur recherché.</p>', true, '2017-08-09 10:15:30.840645+02', '2017-08-09 10:28:32.19193+02', true, 'submitted', 1210, 359);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1306, '<p><b>Réponds en utilisant l’unité appropriée.<br/><br/></b></p><p>Une cannette de 25 ___a___ ou 250 ___b___.</p><p><br/></p><p>Un sac de 25 ___c___ de béton.</p><p><br/></p><p>Il me faut 25 ___d___ pour rentrer chez moi à une vitesse de 50 ___e___.</p><p><br/></p><p>J’ai acheté un aquarium de 500 ___f___ ou 500 ___g___.</p><p><br/></p><p>Un crayon mesure 12 ___h___ alors qu’un camion peut mesurer 12 ___i___ ou 1200 ___j___.</p><p><br/></p><p>Mon appartement à une superficie de 60 ___k___.</p><p><br/></p>', true, '2017-08-09 10:29:47.357645+02', '2017-08-09 10:29:47.357682+02', true, 'submitted', 164, 149);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1356, '<p>Le théorème de Pythagore s''énonce de la manière suivante :</p><blockquote><p>​Dans un triangle rectangle, l''aire du carré construit sur l''hypothénuse est égale à la somme des aires des carrés construits sur les côtés de l''angle droit.</p></blockquote><p>Enonce puis démontre <u>la réciproque</u> du théorème de Pythagore.</p>', true, '2017-08-14 10:47:51.267983+02', '2017-08-14 10:48:58.966351+02', true, 'submitted', 1210, 250);
