INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1293, '<p>Réponds aux questions suivantes en utilisant la relation de réciprocité qui unit les fonctions exponentielles et logarithmes.</p>', true, '2017-08-08 12:39:00.893622+02', '2017-08-09 11:08:53.539389+02', true, 'submitted', 1210, 403);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1300, '<p>En utilisant le graphe  de la fonction donné ci-dessous, calcule les différents taux d''accroissement demandés afin d''approximer la dérivée en <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-14" class="mjx-mo MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">=</span></span><span id="MJXc-Node-15" class="mjx-mn MJXc-space3"><span class="mjx-char MJXc-TeX-main-R">1</span></span></span></span><span class="MJX_Assistive_MathML">x=1</span></span> :<br/></p><p><img src="/media/exercices/TB5-U3-A1_01.PNG"/></p><p>Pour chacune des sous-questions, il t''est demandé d''arrondir ta réponse au dixième d''unité le plus proche.</p>', true, '2017-08-08 16:30:48.629014+02', '2017-08-09 11:13:02.631093+02', true, 'submitted', 1210, 404);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1334, '<p>Dans chacun des repères ci-dessous, indique l''extrémité du vecteur demandé (l''origine du vecteur demandé étant pour chaque sous-question le point \((0,0)\)).</p>', true, '2017-08-10 12:32:28.927436+02', '2017-08-10 12:32:28.927473+02', true, 'submitted', 1210, 358);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1308, '<p style="font-size: 16px;">En utilisant le repère ci-dessous,</p><p><img src="/media/exercices/T4-U6-A02_01.PNG"/></p><p>réponds aux questions en indiquant sur le graphe l''extrémité des vecteurs demandés (pour toutes tes réponses, l''origine du vecteur demandé est le point <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MJXc-processed" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-14" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">0</span></span><span id="MJXc-Node-15" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">,</span></span><span id="MJXc-Node-16" class="mjx-mn MJXc-space1"><span class="mjx-char MJXc-TeX-main-R">0</span></span><span id="MJXc-Node-17" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span></span></span><span class="MJX_Assistive_MathML">(0,0)</span><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow" style="width: 2.72em;"><span id="MJXc-Node-13" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">L</span></span><span id="MJXc-Node-14" class="mjx-mspace" style="width: 0px;height: 0px;"></span><span id="MJXc-Node-15" class="mjx-mpadded"><span class="mjx-block" style="width: 0px;"><span class="mjx-box" style="width: 0px;"><span id="MJXc-Node-16" class="mjx-mrow"><span id="MJXc-Node-17" class="mjx-texatom"><span id="MJXc-Node-18" class="mjx-mrow"><span id="MJXc-Node-19" class="mjx-mstyle" style="font-size: 80%;"><span id="MJXc-Node-20" class="mjx-mrow" style="font-size: 88.4%;"><span id="MJXc-Node-21" class="mjx-texatom"><span id="MJXc-Node-22" class="mjx-mrow"><span id="MJXc-Node-23" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">A</span></span></span></span></span></span></span></span></span></span><span class="mjx-strut"></span></span></span><span id="MJXc-Node-24" class="mjx-mspace" style="width: 0px;height: 0px;"></span><span id="MJXc-Node-25" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">T</span></span><span id="MJXc-Node-26" class="mjx-mspace" style="width: 0px;height: 0px;"></span><span id="MJXc-Node-27" class="mjx-mpadded"><span class="mjx-block" style="width: 0px;"><span class="mjx-box" style="width: 0px;"><span id="MJXc-Node-28" class="mjx-mrow"><span id="MJXc-Node-29" class="mjx-texatom"><span id="MJXc-Node-30" class="mjx-mrow"><span id="MJXc-Node-31" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">E</span></span></span></span></span></span><span class="mjx-strut"></span></span></span><span id="MJXc-Node-32" class="mjx-mspace" style="width: 0px;height: 0px;"></span><span id="MJXc-Node-33" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">X</span></span></span></span><span class="MJX_Assistive_MathML">LATEX</span></span>.</p>', true, '2017-08-09 10:48:18.954506+02', '2017-08-21 10:50:31.309861+02', true, 'submitted', 1210, 360);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1335, '<p>Mathias, en vacances dans les Ardennes belges, aimerait se rendre de l''autre côté d''un fleuve. Pour ce faire, il nage dans la direction perpendiculaire aux berges à une vitesse constante de 3m/s. De plus, il est soumis à un vent contraire de 2m/s et à un courant latéral (perpendiculaire à sa trajectoire) venant de sa droite de 1m/s.</p><p>En considérant que la berge est parallèle à l''axe d''équation \(y=0\) et en considérant qu''une unité représente une vitesse de 1m/s, représente en y indiquant l''extrémité du vecteur demandé (on considère que l''origine du vecteur demandé est le point \((0,0)\) pour chaque sous-question) :</p>', true, '2017-08-10 12:56:02.485407+02', '2017-08-10 12:56:02.485445+02', true, 'submitted', 1210, 358);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1310, '<p>En utilisant les composantes des vecteurs suivants,</p><p>\( \overrightarrow{a} \begin{pmatrix} 1 \\ 0 \end{pmatrix} \) ; \( \overrightarrow{b} \begin{pmatrix} -2 \\ 4 \end{pmatrix} \) ; \( \overrightarrow{c} \begin{pmatrix} 3 \\ -2 \end{pmatrix} \) ; \( \overrightarrow{d} \begin{pmatrix} 0 \\ 3 \end{pmatrix} \) ; \( \overrightarrow{e} \begin{pmatrix} -1 \\ -4 \end{pmatrix} \)</p><p><span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-3-Frame" class="mjx-chtml MJXc-processed" style="font-size: 121%;"><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-munderover"><span class="mjx-stack"><span class="mjx-over"><span id="MJXc-Node-15" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">→</span></span></span><span class="mjx-op"><span id="MJXc-Node-14" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">a</span></span></span></span></span><span id="MJXc-Node-16" class="mjx-mrow MJXc-space1"><span id="MJXc-Node-17" class="mjx-mo"><span class="mjx-char MJXc-TeX-size3-R">(</span></span><span id="MJXc-Node-18" class="mjx-mtable" style="vertical-align: -0.95em;"><span class="mjx-table"><span id="MJXc-Node-19" class="mjx-mtr" style="height: 1.2em;"><span id="MJXc-Node-20" class="mjx-mtd" style="width: 0.5em;"><span id="MJXc-Node-21" class="mjx-mrow"><span id="MJXc-Node-22" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">1</span></span><span class="mjx-strut"></span></span></span></span><span id="MJXc-Node-23" class="mjx-mtr" style="height: 1.2em;"><span id="MJXc-Node-24" class="mjx-mtd"><span id="MJXc-Node-25" class="mjx-mrow"><span id="MJXc-Node-26" class="mjx-mn"><span class="mjx-char MJXc-TeX-main-R">0</span></span><span class="mjx-strut"></span></span></span></span></span></span><span id="MJXc-Node-27" class="mjx-mo"><span class="mjx-char MJXc-TeX-size3-R">)</span></span></span></span></span><span class="MJX_Assistive_MathML">a→(10)</span><span id="MJXc-Node-11" class="mjx-math"><span id="MJXc-Node-12" class="mjx-mrow"><span id="MJXc-Node-13" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">(</span></span><span id="MJXc-Node-14" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">x</span></span><span id="MJXc-Node-15" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">,</span></span><span id="MJXc-Node-16" class="mjx-mi MJXc-space1"><span class="mjx-char MJXc-TeX-math-I">y</span></span><span id="MJXc-Node-17" class="mjx-mo"><span class="mjx-char MJXc-TeX-main-R">)</span></span></span></span><span class="MJX_Assistive_MathML">(x,y)</span></span></p><p style="font-size: 16px;">réponds aux questions ci-dessous. </p><p><span style="font-size: 16px;">La solution sera à chaque fois donnée sous la forme : \((x,y)\) où \(x\) et \(y\) </span><span style="font-size: 16px;">auront été remplacés par les coordonnées recherchées.</span></p>', true, '2017-08-09 11:04:33.590672+02', '2017-08-09 11:21:10.530086+02', true, 'submitted', 1210, 360);
