INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1313, '<p>Pour chacun des vecteurs suivants, décompose le comme la combinaison linéaire des deux vecteurs de la base demandée.</p><p>Pour chaque sous-question, la solution sera donnée sous la forme : \(x,y\) où \(x\) et \(y\) seront remplacés par les coefficients multiplicatifs des vecteurs de la base demandée.</p>', true, '2017-08-09 11:41:56.42692+02', '2017-08-09 11:41:56.426948+02', true, 'submitted', 1210, 361);
