INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1316, '<p>Détermine la propriété utilisée pour passer d''une étape à la suivante dans chacune des situations : </p>', true, '2017-08-09 12:12:45.210133+02', '2017-08-09 12:12:45.21017+02', true, 'submitted', 122, 24);
