INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1317, '<p style="font-size: 16px;">En utilisant le repère ci-dessous, décompose à chaque sous-question le vecteur demandé selon les directions des deux autres vecteurs donnés.</p><p><img src="/media/exercices/T4-U6-A03_01.PNG"/></p><p>Pour chaque sous-question, la solution sera donnée sous la forme : \(x,y\) où \(x\) et \(y\) seront remplacés par les coefficients multiplicatifs des vecteurs de la base demandée (sous forme fractionnaire si nécessaire).</p>', true, '2017-08-09 12:13:07.29583+02', '2017-08-09 12:16:19.945805+02', true, 'submitted', 1210, 361);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1318, '<p>Pour chaque calcul, détermine si tu dois utiliser la distributivité ou la mise en évidence pour calculer plus facilement:</p>', true, '2017-08-09 12:18:01.617187+02', '2017-08-09 12:18:01.617234+02', true, 'submitted', 122, 24);
