INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1319, '<p>Ecris les situations suivantes en une seule suite d''opérations : </p>', true, '2017-08-09 12:34:59.629026+02', '2017-08-09 13:00:41.475249+02', true, 'submitted', 122, 30);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1320, '<p>En utilisant les informations procurées à chaque sous-question, détermine une équation cartésienne de la droite recherchée. La solution sera exprimée sous la forme : \(ax + by + c = 0\).</p>', true, '2017-08-09 14:06:42.866181+02', '2017-08-09 14:08:47.401275+02', true, 'submitted', 1210, 363);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1321, '<p>Soit \((O, \overrightarrow{i}, \overrightarrow{j})\) un repère du plan :<br/></p><p><img src="/media/exercices/T4-U6-A04_02.PNG"/></p><p>Détermine des équations vectorielles et cartésiennes pour les droites <span class="MathJax_Preview" style="color: inherit;"></span><span id="MathJax-Element-4-Frame" class="mjx-chtml MathJax_CHTML" style="font-size: 121%;"><span id="MJXc-Node-24" class="mjx-math"><span id="MJXc-Node-25" class="mjx-mrow"><span id="MJXc-Node-26" class="mjx-mi"><span class="mjx-char MJXc-TeX-math-I">d</span></span></span></span><span class="MJX_Assistive_MathML">d</span></span>.</p><p style="font-size: 16px;">Les équations vectorielles seront encodées sous la forme :</p><p style="font-size: 16px;">\(AM = kAB\).</p><p>Les équations cartésiennes seront encodées sous la forme :</p><p><span class="MathJax_Preview" style="color: inherit;"></span>\(ax + by + c = 0\).</p>', true, '2017-08-09 14:32:00.436674+02', '2017-08-09 15:01:38.650709+02', true, 'submitted', 1210, 362);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1326, '<p>Associe chacune des équations suivantes avec le lieu de points correspond dans le graphe ci-dessous (en identifiant la couleur de la courbe).<br/></p><p><img src="/media/exercices/T4-U6-C1_01.PNG"/></p>', true, '2017-08-09 17:08:25.120085+02', '2017-08-09 17:10:27.661927+02', true, 'submitted', 1210, 357);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1327, '<p>Pour chacune des expressions analytiques suivantes, identifie de quel lieu de points il s''agit.</p>', true, '2017-08-09 17:25:26.962756+02', '2017-08-10 09:25:13.36109+02', true, 'submitted', 1210, 357);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1328, '<p>Dans un repère orthonormé, représente les paraboles ayant les caractéristiques suivantes :</p><ol><li>son foyer est \(F(1,0)\) et sa directrice \(d\) passe par les points \(A(-2,1)\) et \(B(-2,-1)\) ;</li><li>son foyer est \(G(0,-1)\) et sa directrice \(e\) a comme équation \(y = 1\) ;</li><li>son foyer est \(H(2,1)\) et sa directrice \(f\) a comme équation \(y = -2\) ;</li><li>son sommet est \(S(1,1)\) et son foyer, \(I(1,4)\).</li></ol>', true, '2017-08-10 09:41:53.307911+02', '2017-08-10 09:41:53.30794+02', false, 'submitted', 1210, 367);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1329, '<p>On donne les points \(F(0,0)\) et \(G(2,3)\) et les droites \(d \equiv y = -2\) et \(e \equiv x = -2\).</p><p>Détermine ...</p><p><br/></p><p>Lorsque les coordonnées d''un point sont demandées, la solution sera donnée sous la forme : \((x,y)\) où \(x\) et \(y\) auront été remplacés par leur valeur correspondante. </p><p>Lorsque l''équation d''une parabole est demandée, la solution sera donnée sous la forme : \(x^2+ax+by+c=0\) ou (y^2+ay+bx+c=0\) où \(a\), \(b\) et \(c\) auront été remplacés par leur valeur correspondante.<br/></p>', true, '2017-08-10 10:18:09.996131+02', '2017-08-10 10:18:09.996169+02', true, 'submitted', 1210, 367);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1330, '<p>Détermine ...</p><p>Lorsque les coordonnées d''un point sont demandées, la solution sera donnée sous la forme \((x,y)\) où \(x\) et \(y\) auront été remplacés par leur valeur correspondante. <br/></p>', true, '2017-08-10 10:29:43.107353+02', '2017-08-10 10:29:43.107387+02', true, 'submitted', 1210, 366);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1331, '<p>Détermine ...</p>', true, '2017-08-10 10:37:39.762326+02', '2017-08-10 10:37:39.762383+02', true, 'submitted', 1210, 366);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1332, '<p>Détermine le/les point(s) d''intersection entre les lieux de points demandés.</p><p>Si un tel point n''existe pas, réponds \(0\) à la question concernée.</p><p>S''il existe, la solution sera donnée sous la forme : \((x,y)\) où \(x\) et \(y\) auront été remplacés par leur valeur correspondante.<br/></p>', true, '2017-08-10 11:15:10.708334+02', '2017-08-10 11:15:10.70837+02', true, 'submitted', 1210, 368);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1333, '<p style="font-size: 16px;">Détermine le point d''intersection entre les lieux de points demandés.</p><p><img src="/media/exercices/T4-U6-A10_01.PNG"/></p><p style="font-size: 16px;">La solution sera donnée sous la forme \((x,y)\) où \(x\) et \(y\) auront été remplacés par leur valeur correspondante (en écriture fractionnaire si nécessaire).</p>', true, '2017-08-10 12:07:05.31347+02', '2017-08-10 12:09:10.901824+02', true, 'submitted', 1210, 368);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1336, '<p></p><p style="font-size: 16px;">Soit le triangle défini par les coordonnées de ses sommets : \(A(0,0)\), \(B(2,4)\) et \(C(8,0)\).</p><p style="font-size: 16px;">Calcule les coordonnées du point d''intersection ...</p><p style="font-size: 16px;">La solution sera exprimée sous la forme \((x,y)\) où \(x\) et \(y\) auront été remplacés par leur valeur correspondante (sous forme fractionnaire si nécessaire).</p><p></p>', true, '2017-08-10 14:31:14.977632+02', '2017-08-10 14:31:14.977675+02', true, 'submitted', 1210, 371);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1337, '<p style="font-size: 16px;">Soit le triangle défini par les coordonnées de ses sommets : \(A(0,0)\), \(B(0,4)\) et \(C(8,0)\).</p><p style="font-size: 16px;">Calcule les coordonnées du point d''intersection ...</p><p style="font-size: 16px;">La solution sera exprimée sous la forme \((x,y)\) où \(x\) et \(y\) auront été remplacés par leur valeur correspondante (sous forme fractionnaire si nécessaire).</p>', true, '2017-08-10 14:57:31.244165+02', '2017-08-10 14:57:31.244196+02', true, 'submitted', 1210, 371);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1338, '<p>Mathias et Mathilde participent à une chasse au trésor. Ils ont déjà réussi à récolter plusieurs indices et doivent maintenant localiser la position du trésor pour pouvoir le récupérer.</p><p>Les informations qu''ils possèdent sont</p><ul><li>​Les coordonnées de l''île Pythagoras sont \(P(1,0)\).</li><li>​Les coordonnées de l''île Thalésis sont \(T(4,2)\).</li><li>Les coordonnées de la ville Mathistown sont \(P(2,4)\).</li><li>Le trésor se trouve à égale distance des îles de Pythagoras et Thalésis.</li><li>Le trésor se trouve à une distance de 4 de la ville de Mathistown.</li><li>Les coordonnées du trésor sont toutes les deux positives.</li></ul><p>Réponds aux questions suivantes afin de les aider dans leur recherche :</p><p>(on notera l''équation d''une droite \(ax+by+c=0\), l''équation d''un cercle \((x-d)^2+(y-e)^2=r^2\) et les coordonnées d''un point \((u,v)\)).</p>', true, '2017-08-10 15:39:34.209418+02', '2017-08-10 15:39:34.209448+02', true, 'submitted', 1210, 370);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1339, '<p>Mathieu vient juste d''acquérir un terrain rectangulaire de sommets \(A(3,1)\), \(B(6,1)\), \(C(6,6)\) et \(A(3,6)\) dans la charmante ville de Mathistown afin d''y bâtir la maison de ses rêves.</p><p>Dans un premier temps, il aimerait déterminer la position idéale de sa maison sur son terrain.</p><p>Il aimerait que cette dernière se trouve à égale distance de la route qui longe son terrain et du grand pommier de coordonnées \(P(4,5)\). La route qui longe le terrain de Mathieu est une route rectiligne qui relie l''école \(E(1,1)\) et la ferme \(F(8,1)\) de Mathistown.</p><p>De plus, il aimerait que sa maison se trouve à une distance \(\sqrt{5}\) de son trampoline qu''il a positionné aux coordonnées \(T(5,5)\).</p><p>Réponds à ces questions afin d''aider Mathias à positionner sa maison.</p><p>(On notera l''équation d''une droite \(ax+by+c=0\), l''équation d''un cercle \((x-d)^2+(y-e)^2=r^2\), l''équation d''une parabole \(x^2+ax+by+c=0\) et les coordonnées d''un point \((u,v)\)).</p>', true, '2017-08-10 16:38:39.630715+02', '2017-08-10 16:38:39.630745+02', true, 'submitted', 1210, 370);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1340, '<div><p>​<b>Alignement de points.</b></p></div>', true, '2017-08-10 17:12:02.002041+02', '2017-08-10 17:12:02.002083+02', true, 'submitted', 1210, 369);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1341, '<p>On donne les points de l''espace \(A(4,2,1)\) et \(B(3,8,4)\).</p><p>Détermine les valeurs de \(s\), \(t\), \(u\) et \(v\) pour que les points suivants soient alignés avec \(A\) et \(B\).</p><ol><li>​\(C(7,s,t)\)</li><li>​\(D(u,-4,v)\)</li></ol>', true, '2017-08-11 10:01:10.833851+02', '2017-08-11 10:01:10.833882+02', true, 'submitted', 1210, 540);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1342, '<p style="font-size: 16px;"></p><p style="font-size: 16px;">On donne les points de l''espace \(A(4,2,1)\), \(B(3,8,4)\) et \(C(-2,6,-1)\).</p><p style="font-size: 16px;">Détermine les valeurs de \(s\), \(t\), \(u\) et \(v\) pour que les points suivants soient coplanaires avec \(A\), \(B\) et \(C\).</p><ol style="font-size: 16px;"><li>​\(D(-3,12,s)\)</li><li>​\(E(t,4,-6)\)</li><li>\(F(0,u,-7)\)</li><li>\(G(0,26,v)\)</li></ol>', true, '2017-08-11 10:09:56.026446+02', '2017-08-11 10:09:56.026486+02', true, 'submitted', 1210, 541);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1343, '<p style="font-size: 16px;">Soit la droite d''équation \(d \equiv \dfrac{x+1}{2} = \dfrac{y-1}{3} = z+1\).</p><p style="font-size: 16px;">Détermine les valeurs de \(s\), \(t\), \(u\) et \(v\) pour que les droites suivantes soient orthogonales à la droite \(d\).</p><ol style="font-size: 16px;"><li>\(e \equiv \dfrac{x}{2} = y-3 = \dfrac{z-1}{s}\)<br/></li><li>\(f \equiv \dfrac{2x-1}{4} = \dfrac{-y}{2} = \dfrac{z}{t}\)<br/></li><li>\(g \equiv (x,y,z) = (0,0,0) +\lambda(3,u,6) \)<br/></li><li>\(h \equiv (x,y,z) = (-1,2,-3) +\dfrac{\mu}{4}(v,2,-4) \)<br/></li></ol>', true, '2017-08-11 11:02:33.105054+02', '2017-08-11 11:02:33.105082+02', true, 'submitted', 1210, 542);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1344, '<p>Soit les points \(A(2, -1, 4)\), \(B(3, 6, -2)\) et \(C(-5,1,0)\).</p><p>Détermine ...</p>', true, '2017-08-11 11:20:21.704535+02', '2017-08-11 11:20:21.704564+02', true, 'submitted', 1210, 539);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1346, '<p>Soit les vecteurs directeurs \(\overrightarrow{d}(1,1,1)\) et \(\overrightarrow{e}(-3,4,2)\) et les points \(A(1,-1,4)\), \(B(1,1,1)\) et \(C(-3,4,2\)).</p><p>Détermine ...</p><p><br/></p><p>(Des équations paramétriques d''un plan seront écrites sous la forme \((x,y,u) = (a,b,c) + f\cdot(l,m,n) + g\cdot(o,p,q)\) où les lettres \(a\), \(b\), \(c\), \(l\), \(m\), \(n\), \(o\), \(p\) et \(q\) auront été remplacées par leur valeur correspondante. Une équation cartésienne d''un plan sera écrite sous la forme \(ax + by + cu = d\) où les lettres \(a\), \(b\), \(c\) et \(d\) auront été remplacées par leur valeur correspondante).</p>', true, '2017-08-11 12:16:34.040492+02', '2017-08-11 12:51:48.304901+02', true, 'submitted', 1210, 545);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1345, '<p>Soit les points \(A(3,1,-2)\) et \(B(-6,8,0)\) et le vecteur directeur \(\overrightarrow{d}=(3,1,4)\).</p><p>Détermine ...</p><p>(Les équations paramétriques d''une droite seront écrites sous la forme \((x,y,u) = (a,b,c) + h\cdot(d,e,f)\) où les lettres a, b, c, d, e, f auront été remplacées par leur valeur correspondante. Les équations cartésiennes d''une droite seront écrites sous la forme \(\dfrac{x-a}{d} = \dfrac{y-b}{e} = \dfrac{u-c}{f}\) où les lettres a, b, c, d, e, f auront été remplacées par leur valeur correspondante.)</p>', true, '2017-08-11 12:00:44.521147+02', '2017-08-11 13:54:36.779709+02', true, 'submitted', 1210, 544);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1347, '<p>Soit les points \(A(1, 4, -3)\) et \(B(2,-1,2)\).</p><p>Réponds aux questions suivantes.</p><p><br/></p><p>Des équations paramétriques d''une droite seront écrites sous la forme \((x,y,u) = (a,b,c) + h\cdot(d,e,f)\) où les lettres \(a\), \(b\), \(c\), \(d\), \(e\) et \(f\) auront été remplacées par leur valeur correspondante. </p><p>Une équation cartésienne d''un plan sera écrite sous la forme \(ax+by+cu=d\) où les lettres \(a\), \(b\), \(c\) et \(d\) auront été remplacées par leur valeur correspondante.<span id="selectionBoundary_1502452377468_8406121785752925" class="rangySelectionBoundary">&#65279;</span><span id="selectionBoundary_1502452075165_9159370838367109" class="rangySelectionBoundary">&#65279;</span></p><p>Les coordonnées cartésiennes d''un plan seront écrites sous la forme \((a,b)\) où les lettres \(a\) et \(b\) auront été remplacées par leur valeur correspondante.<br/></p>', true, '2017-08-11 14:18:48.377014+02', '2017-08-11 14:18:48.377046+02', true, 'submitted', 1210, 543);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1348, '<p style="font-size: 16px;">En utilisant le repère ci-dessous, réponds aux questions de la manière la plus simple possible.</p><p><img src="/media/exercices/TG6-U5-A4A_01.PNG"/></p><p>On écrira les équations paramétriques d''une droite sous la forme \((x,y,z) = (a,b,c)+h\cdot(d,e,f)\) où \(a\), \(b\), \(c\), \(d\), \(e\) et \(f\) auront été remplacés par leur valeur correspondante.</p>', true, '2017-08-11 15:46:39.873097+02', '2017-08-11 15:49:57.399693+02', true, 'submitted', 1210, 550);
