INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1350, '<p>On considère les plans suivants :</p><ul><li>​\(\pi_1 \equiv 2x+y-z=0\)</li><li>​\(\pi_2 \equiv x-4y+z=-2\)</li><li>​\(\pi_3 \equiv -4x+y+2z=4\)</li><li>​\(\pi_4 \equiv -6x-3y+3z=1\)</li></ul><p>Détermine l''intersection entre les plans ... (si la réponse est un point, on la notera \((a,b,c)\) sinon on notera simplement &#34;0&#34;).</p>', true, '2017-08-11 17:03:59.561443+02', '2017-08-11 17:04:33.561318+02', true, 'submitted', 1210, 554);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1351, '<p>Pour chacun des énoncés suivants, détermine s''il s''agit du théorème de Pythagore, de sa réciproque ou de sa contraposée.</p>', true, '2017-08-14 09:38:16.778124+02', '2017-08-14 09:38:16.77816+02', true, 'submitted', 1210, 253);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1352, '<p>Pour chacun des énoncés suivants, détermine s''il s''agit du théorème de Pythagore, de sa réciproque ou de sa contraposée.<br/></p>', true, '2017-08-14 09:38:22.976291+02', '2017-08-14 09:38:22.976326+02', true, 'submitted', 1210, 253);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1353, '<p>En utilisant le théorème de Pythagore et en considérant que l''origine du plan \(O\) est la première extrémité du segment, détermine la seconde extrémité (de coordonnées entières naturelles) d''un segment de longueur ...</p>', true, '2017-08-14 09:53:56.484138+02', '2017-08-14 09:53:56.484178+02', true, 'submitted', 1210, 261);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1354, '<p>Quelles seraient les longueurs entières naturelles des côtés adjacents à l''angle droit d''un triangle rectangle dont l''hypothénuse mesure une longueur de ...</p><p><br/></p><p>Pour chaque sous-question, la solution sera donnée sous la forme : \(a,b\) avec \(a\leq b\).</p>', true, '2017-08-14 10:08:50.546892+02', '2017-08-14 10:08:50.546954+02', true, 'submitted', 1210, 261);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1355, '<p>En te basant sur la figure suivante, calcule ...<br/></p><p><img src="/media/exercices/T3-U2-A2_02.PNG"/></p>', true, '2017-08-14 10:40:28.460076+02', '2017-08-14 10:41:02.934524+02', true, 'submitted', 1210, 259);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1357, '<p></p><p style="font-size: 16px;">La réciproque du théorème de Pythagore s''énonce de la manière suivante :</p><blockquote style="font-size: 17.5px;"><p>​Dans un triangle, si le carré de la mesure du plus grand côté est égal à la somme des carrés des mesures des deux autres cotés, alors le triangle est rectangle.</p></blockquote><p style="font-size: 16px;">Enonce puis démontre <u>le théorème</u> de Pythagore (et non sa réciproque).</p><p></p>', true, '2017-08-14 10:51:04.24356+02', '2017-08-14 10:51:04.243593+02', false, 'submitted', 1210, 250);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1358, '<p>Soit le triangle \(ABC\) rectangle en \(C\) :</p><p><img src="/media/exercices/T3-U2-C5_01.PNG"/></p>', true, '2017-08-14 11:42:04.953655+02', '2017-08-14 12:19:42.809612+02', true, 'submitted', 1210, 256);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1359, '<p>Soit le triangle \(ABC\) rectangle en \(C\) :<br/></p><p><img src="/media/exercices/T3-U2-C5_02.PNG"/></p>', true, '2017-08-14 12:11:30.409817+02', '2017-08-14 12:11:47.845729+02', true, 'submitted', 1210, 256);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1362, '<p style="font-size: 16px;">Soit le triangle \(ABC\) rectangle en \(B\) et \(\mathcal{C_0}\) le cercle circonscrit au triangle \(ABC\) de centre \(E\) et de diamètre \([AC]\). Soit \(\mathcal{C_1}\) le demi-cercle de centre \(F\) et de diamètre \([AB]\) et \(\mathcal{C_2}\) le demi-cercle de centre \(G\) et de diamètre \([BC]\).</p><p style="font-size: 16px;">La lunule \(L_1\) est la surface délimitée par \(\mathcal{C_0}\) et \(\mathcal{C_1}\). La lunule \(L_2\) est la surface délimitée par \(\mathcal{C_0}\) et \(\mathcal{C_2}\) comme indiqué sur la figure suivante : </p><p><img src="/media/exercices/T3-U2-T1_01.PNG"/></p><p></p><p style="font-size: 16px;">Démontre que la somme des aires des lunules \(L_1\) et \(L_2\) (en jaune) est égale à l''aire du triangle \(ABC\) (en orange).</p><p></p>', true, '2017-08-14 15:46:55.898014+02', '2017-08-14 15:47:26.542299+02', true, 'submitted', 1210, 262);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1360, '<p style="font-size: 16px;">On considère la figure exacte ci-dessous composée d''un carré et de neuf cercles de 3 cm de diamètre.</p><p><img src="/media/exercices/T3-U2-C3_03.PNG" width="500"/></p><p>Réponds aux questions suivantes :</p>', true, '2017-08-14 13:17:27.942617+02', '2017-08-14 14:18:52.380499+02', true, 'submitted', 1210, 254);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1361, '<p style="font-size: 16px;">En utilisant les informations de la figure suivante :</p><p><img src="/media/exercices/T3-U2-C3_04.PNG"/></p><p>et en sachant que \(\overline{BC} = 5\), calcule en arrondissant au centième le plus proche :</p>', true, '2017-08-14 14:59:07.049464+02', '2017-08-14 15:01:44.014094+02', true, 'submitted', 1210, 254);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1369, '<p>Soit le plan \(P\) d''équation cartésienne \(2x+2y+4z=g\). Soit la droite \(D\) passant par le point \(p\) de coordonnées \((x,y,z) = (1,1,1)\) et parallèle au vecteur \(v=(0,4,3)\). Soit \(q\) le point de percée de \(D\) dans \(P\). On cherche à déterminer \(g\) pour que la distance entre \(p\) et \(q\) soit égale à 5.</p><p><br/></p><p style="text-align: right;">Examen d''admission 2011, Ecole Polytechnique de Louvain​</p>', true, '2017-08-17 10:01:52.370252+02', '2017-08-17 10:01:52.370285+02', true, 'submitted', 1210, 557);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1371, '<p>On peut interpréter géométriquement les solutions d''un système de trois équations à trois inconnues comme l''intersection de trois plans dans l''espace.</p><p><br/></p><p>On donne les équations de plan suivantes :</p><p>\( \begin{cases} \pi_1 \equiv 2x - 4y +6z = 4 \\ \pi_2 \equiv 2x -3y - z = 5 \\ \pi_3 \equiv 2x + 3y + 5z = 2 \\ \pi_4 \equiv x - 2y + 3z = 0 \end{cases} \)</p><p><br/></p><p>Détermine dans chacun des cas si l''intersection des trois plans concernés est</p><ul><li>​un point</li><li>une droite</li><li>un plan</li><li>inexistante car les plans se coupent deux à deux suivant des droites parallèles</li><li>inexistante car les plans sont parallèles non tous trois confondus</li><li>inexistante car un plan coupe les deux autres qui sont parallèles distincts</li></ul>', true, '2017-08-17 11:03:36.716187+02', '2017-08-17 11:03:36.716225+02', true, 'submitted', 1210, 538);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1364, '<p>Mathéo et Mathilde viennent tout juste de sortir de la finale du Championnat International de Jeux Mathématiques et Logiques. Ils décident de jouer à un jeu afin de se changer les idées : Mathilde pense à un nombre à trois chiffres \(x\) et Mathéo doit le deviner grâce aux renseignements donnés par Mathilde.</p><p>Les indices sont :</p><ol><li>​Le chiffre des unités vaut le double de la somme des deux autres.</li><li>La somme des trois chiffres vaut 9.</li><li>La moyenne arithmétique entre le chiffre des centaines et celui des unités vaut quatre fois le chiffre des dizaines.</li></ol><p>Traduis chacun des indices donnés par Mathilde en une équation puis détermine le nombre recherché par Mathilde.</p><p>On notera \(a\) le chiffre des centaines, \(b\) le chiffre des dizaines et \(c\) le chiffre des unités; \(x = 100a+10b+c\).</p>', true, '2017-08-14 17:06:33.047878+02', '2017-08-14 17:07:54.74616+02', true, 'submitted', 1210, 556);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1365, '<p>Alex, Béatrice et Clément se rendent dans une friterie pour l''anniversaire de Didier. Ils décident de se répartir la commande de Didier pour que celui-ci ne paie pas.</p><p></p><p>Alex commande un litre de limonade, un petit paquet de frites et un hamburger pour lui ainsi qu''un demi-litre de limonade et un petit paquet de frites pour Didier.</p><p>Béatrice achète 0,5l de limonade, un petit paquet de frites et un hamburger pour elle ainsi que deux hamburgers pour Didier.</p><p>Enfin, Clément commande un grand paquet de frites (coûtant 4/3 du prix d''un petit paquet) et un hamburger pour lui ainsi qu''un petit paquet de frites et un hamburger pour Didier.</p><p></p><p></p><p>Chacun d''entre eux paie exactement 5€.</p><p>Etonnés de ne pas voir le détail de leurs commandes sur les tickets de caisse, ils aimeraient déterminer le prix d''un litre de limonade, d''un petit paquet de frites et d''un hamburger afin de savoir qui a payé le plus pour Didier.</p>', true, '2017-08-16 12:56:01.033648+02', '2017-08-16 12:56:01.033683+02', true, 'submitted', 1210, 556);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1366, '<p>Soit les droites</p><p>\(d_1 \equiv\begin{cases} x = 2\lambda \\ y = 3 + 2\lambda \\ z = 2 + \lambda \end{cases}\)</p><p></p><p style="font-size: 16px;">\(d_2 \equiv \dfrac{x+1}{2} = \dfrac{y+4}{3} = \dfrac{z-2}{2} \)</p><p></p><p></p><p>et les plans</p><p>\(\pi_1 \equiv 2x-y+3z=2\)</p><p style="font-size: 16px;">\(\pi_2 \equiv\begin{cases} x = 4 + 2\lambda - 5\mu \\ y = -1 + 5\lambda + \mu \\ z = 3 -\lambda - \mu \end{cases}\)</p><p><br/></p><p style="font-size: 16px;">Détermine ...</p><p style="font-size: 16px;"><br/></p><p style="font-size: 16px;">(Les solutions seront données sous la forme : \((\dfrac{a}{b}, \dfrac{c}{d}, \dfrac{e}{f})\).)</p>', true, '2017-08-16 15:02:24.942066+02', '2017-08-16 15:02:24.942093+02', true, 'submitted', 1210, 553);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1367, '<p>Soit la droite</p><p>\(d \equiv \begin{cases} x = 3 + \lambda \\ y = \lambda \\ z = 1 + 3\lambda \end{cases}\)</p><p>et les plans</p><p>\(\pi_1 \equiv 2x-3y+mz=-3\)</p><p>\(\pi_2 \equiv x+2z=n\)<br/></p><p>Détermine la valeur de \(m\) et \(n\) pour que le point de percée de la droite \(d\) dans le plan \(\pi_1\) soit \((3,0,1)\) et le point de percée de la droite \(d\) dans le plan \(\pi_2\) soit \((7,4,13)\).</p>', true, '2017-08-16 15:32:04.211393+02', '2017-08-16 15:32:04.211419+02', true, 'submitted', 1210, 553);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1368, '<p>Soit un tétraèdre \(ABCD\) dont les coordonnées des sommets sont \(A(0;4;2)\), \(B(3;1;5)\), \(C(-1;\dfrac{3}{2};-6)\) et \(D(6;-2;1)\).</p><p>On demande :</p><p><br/></p><p style="text-align: right;font-size: 16px;">Examen d''admission, Faculté Polytechnique de Mons</p>', true, '2017-08-16 17:19:56.195392+02', '2017-08-16 17:25:16.147437+02', true, 'submitted', 1210, 557);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1370, '<p>Soit le système de deux équations à deux inconnues :</p><p>\(\begin{cases} 2x + 3y = m \\ 4x + ny = 6 \end{cases}\)</p><p>On considère \(m = 2\).</p>', true, '2017-08-17 10:27:47.962466+02', '2017-08-17 10:27:47.962502+02', true, 'submitted', 1210, 538);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1373, '<p>Pour chacune des équations suivantes, détermine de quelle type d''équation(s) il s''agit.</p>', true, '2017-08-17 12:53:44.870861+02', '2017-08-17 12:53:44.870895+02', true, 'submitted', 1210, 534);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1374, '<p style="font-size: 16px;">En utilisant la figure ci-dessous,</p><p><img src="/media/exercices/TG6-U5-C1A_01.PNG"/></p><p>Associe ...</p>', true, '2017-08-17 14:57:59.790365+02', '2017-08-17 14:58:26.285264+02', true, 'submitted', 1210, 535);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1375, '<p><b><u>Quel est l''intrus / Quels sont les intrus ?</u></b></p>', true, '2017-08-17 16:48:19.033662+02', '2017-08-17 16:48:19.0337+02', true, 'submitted', 1210, 536);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1376, '<p style="font-size: 16px;">Associe chaque triplet d''équations paramétriques d''un plan avec son équation cartésienne correspondante.</p><p style="font-size: 16px;"><u>Equations paramétriques :</u></p><ol style="font-size: 16px;"><li>\( \pi_1\equiv \begin{cases} x = 2 - 2\lambda + 5\mu \\ y = 4 + 2\lambda + 3\mu \\ z = -1 + 2\lambda - 5\mu\end{cases}\)</li><li>\( \pi_2\equiv \begin{cases} x = 15\mu \\ y = 10\lambda \\ z = 6(\lambda-\mu) \end{cases}\)</li><li>\( \pi_3\equiv \begin{cases} x = \mu \\ y = 2\lambda \\ z = 3\lambda \end{cases}\)</li><li>\( \pi_4\equiv \begin{cases} x = - \lambda + \mu \\ y = -1 + \lambda + \mu \\ z = -1 -\lambda + \mu \end{cases}\)</li></ol><p style="font-size: 16px;"><u>Equations cartésiennes :</u><br/></p><ol type="A" style="font-size: 16px;"><li>\( \pi_A\equiv 2x - 3y + 5z = 1 \)</li><li>\( \pi_B \equiv x + z = 1 \)</li><li>\( \pi_C\equiv x - z = 1 \)</li><li>\( \pi_D\equiv 3y - 2z = 0 \)</li></ol>', true, '2017-08-18 10:15:58.01116+02', '2017-08-18 10:15:58.01119+02', true, 'submitted', 1210, 536);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1377, '<p>Associe chaque triplet d''équations paramétriques d''une droite avec sa paire d''équations cartésiennes correspondante.</p><p><u>Equations paramétriques :</u></p><p></p><ol><li>\( d_1\equiv \begin{cases} x &amp;= 2 (1 + \lambda) \\ y &amp;= -1 \\ z &amp;= 3 \end{cases}\)</li><li>\( d_2\equiv \begin{cases} x &amp;= 2 - \lambda \\ y &amp;= -1 \\ z &amp;= 3 + 2\lambda \end{cases}\)</li><li>\( d_3\equiv \begin{cases} x &amp;= 2 - \lambda \\ y &amp;= -1 + 2\lambda \\ z &amp;= 3 - \lambda \end{cases}\)</li><li>\( d_4\equiv \begin{cases} x &amp;= 3 - \lambda \\ y &amp;= -1 + 2\lambda \\ z &amp;= 2 - 3\lambda \end{cases}\)</li></ol><p></p><p><u>Equations cartésiennes :</u><br/></p><p></p><ol type="A"><li>\( d_A\equiv \begin{cases} y &amp;= -1 \\ 2y + z &amp;= 1 \end{cases}\)<br/></li><li>\( d_B\equiv \begin{cases} x + y + z &amp;= 4 \\ 3x + 2y + z &amp;= 7 \end{cases}\)</li><li>\( d_C\equiv \begin{cases} y &amp;= -1 \\ 2x + z &amp;= 7 \end{cases}\)</li><li>\( d_D\equiv \begin{cases} x + 2y + z &amp;= 3 \\ 3x + 3y + z &amp;= 8 \end{cases}\)</li></ol><p></p>', true, '2017-08-18 10:44:00.695172+02', '2017-08-18 10:44:00.695209+02', true, 'submitted', 1210, 535);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1378, '<p style="font-size: 16px;">Associe chaque ensemble d''équations paramétriques avec son ensemble d''équations cartésiennes correspondant.</p><p style="font-size: 16px;"><u>Equations paramétriques :</u></p><ol style="font-size: 16px;"><li>\( \alpha_1\equiv \begin{cases} x &amp;= 1 + 2\lambda + 5\mu \\ y &amp;= 6 - \lambda - 2\mu \\ z &amp;= 7 + 3\lambda \end{cases}\)</li><li>\( \alpha_2\equiv \begin{cases} x &amp;= 3k - 2 \\ y &amp;= -6k + 5 \\ z &amp;= -2k + 6 \end{cases}\)</li><li>\( \alpha_3\equiv \begin{cases} x &amp;= -1.5 - \eta \\ y &amp;= 2\eta \\ z &amp;= 1.5 + 3\eta \end{cases}\)</li><li>\( \alpha_4\equiv \begin{cases} x &amp;= 3k - 2 \\ y &amp;= -6k -m + 5 \\ z &amp;= -2k - 6m + 6\end{cases}\)</li></ol><p style="font-size: 16px;"><u>Equations cartésiennes :</u><br/></p><ol type="A" style="font-size: 16px;"><li>\( \alpha_A\equiv \begin{cases} y - 3z &amp;= -13 \\ 2x + y &amp;= 1 \end{cases}\)<br/></li><li>\( \alpha_B\equiv 34x + 18y - 3z = 4\)</li><li>\( \alpha_C\equiv 6x + 15y + z = 103\)</li><li>\( \alpha_D\equiv \begin{cases} x - y + z &amp;= 0 \\ x + 2y - z + 3 &amp;= 0 \end{cases}\)</li></ol>', true, '2017-08-18 11:31:04.853125+02', '2017-08-18 11:31:04.853153+02', true, 'submitted', 1210, 534);
INSERT INTO examinations_context (id, context, approved, created_at, modified_at, testable_online, file_name, added_by_id, skill_id) VALUES (1379, '<p>Soit les droites et les plans d''équations :</p><p>\(d_1 \equiv (x,y,z) = (-3,2,2) + \lambda (3,-2,0) \)</p><p>\(d_2 \equiv (x,y,z) = (-3,2,2) + \lambda (0,0,1) \)<br/></p><p>\(d_3 \equiv (x,y,z) = (-3,2,2) + \lambda (3,1,-2) \)<br/></p><p>\(d_4 \equiv (x,y,z) = (-3,2,2) + \lambda (-2,1,0) \)<br/></p><p>\(\pi_1 \equiv z = 2 \)<br/></p><p>\(\pi_2 \equiv -2x + y = 0 \)<br/></p><p>\(\pi_3 \equiv x + 2y = 1 \)<br/></p><p>Détermine :</p>', true, '2017-08-18 11:59:04.647208+02', '2017-08-18 11:59:04.647236+02', true, 'submitted', 1210, 552);
