INSERT INTO resources_resource (id, section, content, created_at, modified_at, added_by_id) VALUES (12, 'lesson_resource', '{"kind": "lesson", "title": "Le théorème  de Pythagore : Quand? Comment? ", "author": "Mathrix", "comment": "Vidéo ludique de 8 minutes en vue subjective sur le théorème de Pythagore. L''utilisation de couleurs ainsi qu''une écriture à la main sur papier peut faciliter la compréhension de certains d''entre vous.", "resources": [{"link": "http://www.mathslibres.com/ordreop.php", "type": "site", "mediaType": "link", "optionalName": "Fiches d''Exercices sur l''Ordre des Opérations"}, {"link": "https://www.youtube.com/watch?v=3s-9LRzKs1U", "type": "video", "mediaType": "link", "optionalName": "Vidéo explicative ludique (sans voix)"}, {"link": "https://www.auto-math.be/public/0/module/13/theorie/47", "type": "site", "mediaType": "link", "optionalName": "Auto-Math"}, {"link": "https://www.auto-math.be/public/0/module/13/theorie/45", "type": "site", "mediaType": "link", "optionalName": "Auto-Math"}, {"link": "https://www.auto-math.be/public/0/module/13/theorie/47", "type": "site", "mediaType": "link", "optionalName": "Auto-Math"}, {"link": "https://fr.khanacademy.org/math/geometry/hs-geo-foundations/hs-geo-intro-euclid/e/recognizing_rays_lines_and_line_segments", "type": "site", "mediaType": "link", "optionalName": "Ne pas confondre les demi-droites, les droites et les segments de droite"}, {"link": "https://fr.khanacademy.org/math/geometry/hs-geo-foundations/hs-geo-intro-euclid/e/drawing-lines", "type": "site", "mediaType": "link", "optionalName": "Tracer des droites, des demi-droites ou des segments de droite"}, {"link": "https://www.desmos.com/calculator/hfgxtcgazd", "type": "animation", "mediaType": "link", "optionalName": ""}, {"link": "http://oas.ccdmd.qc.ca/app/scenario.php?demande=[Filtered]&scenario_id_scenario=727", "type": "site", "mediaType": "link", "optionalName": "OAS - Identification"}, {"link": "http://guessthecorrelation.com/", "type": "game", "mediaType": "link", "optionalName": "Guess the Correlation"}, {"link": "http://www.jeuxmaths.fr/cours/completer-tableau-proportionnalite.php", "type": "synthesis", "mediaType": "link", "optionalName": "Cours : Tableau de proportionnalité"}, {"link": "https://www.youtube.com/watch?v=tzOV7zcqJJs", "type": "video", "mediaType": "link", "optionalName": "Théorème de Pythagore 4ème - Mathrix - YouTube"}]}', '2017-07-04 13:11:20.897903+02', '2017-07-04 13:11:20.897934+02', 1065);
INSERT INTO resources_resource (id, section, content, created_at, modified_at, added_by_id) VALUES (13, 'lesson_resource', '{"kind": "lesson", "title": "Le théorème de Pythagore ", "author": "Les bons profs", "comment": "Un enseignant devant son tableau te fait un rappel sur le théorème de Pythagore et son application. \r\n\r\nCelui-ci sert à calculer la longueur d''un côté du triangle rectangle en connaissant la longueur des deux autres côtés. /!\\ Dans la fin de la vidéo : Partie \"A retenir\" Ne pas oublier que le triangle doit être rectangle en A pour appliquer la formule: |AB|² + |AC|² = |BC|². Le côté [BC] étant l''hypoténuse de ce triangle . Entre autre le côté opposé à l''angle droit de sommet A.", "resources": [{"link": "http://www.mathslibres.com/ordreop.php", "type": "site", "mediaType": "link", "optionalName": "Fiches d''Exercices sur l''Ordre des Opérations"}, {"link": "https://www.youtube.com/watch?v=3s-9LRzKs1U", "type": "video", "mediaType": "link", "optionalName": "Vidéo explicative ludique (sans voix)"}, {"link": "https://www.auto-math.be/public/0/module/13/theorie/47", "type": "site", "mediaType": "link", "optionalName": "Auto-Math"}, {"link": "https://www.auto-math.be/public/0/module/13/theorie/45", "type": "site", "mediaType": "link", "optionalName": "Auto-Math"}, {"link": "https://www.auto-math.be/public/0/module/13/theorie/47", "type": "site", "mediaType": "link", "optionalName": "Auto-Math"}, {"link": "https://fr.khanacademy.org/math/geometry/hs-geo-foundations/hs-geo-intro-euclid/e/recognizing_rays_lines_and_line_segments", "type": "site", "mediaType": "link", "optionalName": "Ne pas confondre les demi-droites, les droites et les segments de droite"}, {"link": "https://fr.khanacademy.org/math/geometry/hs-geo-foundations/hs-geo-intro-euclid/e/drawing-lines", "type": "site", "mediaType": "link", "optionalName": "Tracer des droites, des demi-droites ou des segments de droite"}, {"link": "https://www.desmos.com/calculator/hfgxtcgazd", "type": "animation", "mediaType": "link", "optionalName": ""}, {"link": "http://oas.ccdmd.qc.ca/app/scenario.php?demande=[Filtered]&scenario_id_scenario=727", "type": "site", "mediaType": "link", "optionalName": "OAS - Identification"}, {"link": "http://guessthecorrelation.com/", "type": "game", "mediaType": "link", "optionalName": "Guess the Correlation"}, {"link": "http://www.jeuxmaths.fr/cours/completer-tableau-proportionnalite.php", "type": "synthesis", "mediaType": "link", "optionalName": "Cours : Tableau de proportionnalité"}, {"link": "https://www.youtube.com/watch?v=tzOV7zcqJJs", "type": "video", "mediaType": "link", "optionalName": "Théorème de Pythagore 4ème - Mathrix - YouTube"}, {"link": "https://www.youtube.com/watch?v=CI9LhnfUih0https://www.youtube.com/watch?v=CI9LhnfUih0", "type": "video", "mediaType": "link", "optionalName": "Théorème de Pythagore - Maths 3e - Les Bons Profs - YouTube"}]}', '2017-07-04 13:15:42.576861+02', '2017-07-04 13:15:42.576893+02', 1065);
