INSERT INTO resources_resource (id, section, content, created_at, modified_at, added_by_id) VALUES (67, 'other_resource', '{"kind": "exercice", "title": "Guess the correlation", "author": "Omar Wagih", "comment": "Ce jeu (en anglais) vous invite à deviner le coefficient de corrélation caractérisant un nuage de points.\r\nSi votre estimation est meilleure que la moyenne des autres joueurs, vous gagnez des points et pouvez récupérer une \"vie\". Sinon, vous perdez une \"vie\".", "resources": [{"file": "./LES_LOGARITHMES_DECIMAUX.pdf", "type": "Document / image", "mediaType": "file", "optionalName": ""}, {"file": "./FONCTION_REPRESENTATION_ET_DOM.pdf", "type": "Document / image", "mediaType": "file", "optionalName": ""}, {"file": "./devoir_manipulation_fonction.pdf", "type": "Application pratique", "mediaType": "file", "optionalName": ""}, {"file": "./suite_arithmetique_et_geometrique_fgF1Iei.pdf", "type": "document", "mediaType": "file", "optionalName": ""}, {"file": "./Guessthecorrelation.png", "type": "image", "mediaType": "file", "optionalName": ""}]}', '2017-06-16 16:37:43.693634+02', '2017-06-16 16:37:43.693675+02', 2);
